     7→/**
     8→ * Fetch all headshots from Firebase teamsDatabase
     9→ * Returns a map with multiple keys per headshot for flexible matching
    10→ * Keys include: normalized name, stripped version, Firebase key variant
    11→ */
    12→async function getFirebaseHeadshots() {
    13→  try {
    14→    const headshotsRef = ref(db, 'teamsDatabase/headshots');
    15→    const snapshot = await get(headshotsRef);
    16→    const headshotsData = snapshot.val() || {};
    17→
    18→    // Build a map with multiple keys per headshot for flexible matching
    19→    const headshotMap = {};
    20→    for (const [key, data] of Object.entries(headshotsData)) {
    21→      if (data?.url) {
    22→        // Store by Firebase key (underscores → spaces)
    23→        const keyWithSpaces = key.toLowerCase().trim().replace(/_/g, ' ').replace(/\s+/g, ' ');
    24→        headshotMap[keyWithSpaces] = data.url;
    25→
    26→        // Store by fully normalized key
    27→        const normalizedKey = normalizeName(key);
    28→        headshotMap[normalizedKey] = data.url;
    29→
    30→        // Store by name field if available
    31→        if (data.name) {
    32→          headshotMap[normalizeName(data.name)] = data.url;
    33→          // Also store just lowercased version
    34→          headshotMap[data.name.toLowerCase().trim().replace(/\s+/g, ' ')] = data.url;
    35→        }
    36→
    37→        // Store stripped version (only letters and spaces)
    38→        const strippedKey = normalizedKey.replace(/[^a-z\s]/g, '').replace(/\s+/g, ' ').trim();
    39→        if (strippedKey && strippedKey.length > 2) {
    40→          headshotMap[strippedKey] = data.url;
    41→        }
    42→      }
    43→    }
    44→    return headshotMap;
    45→  } catch (err) {
    46→    console.error('Failed to fetch Firebase headshots:', err);
    47→    return {};
    48→  }
    49→}
    50→
    51→/**
    52→ * Look up a headshot URL from the headshot map using multiple lookup keys
    53→ * Handles accents, hyphens, apostrophes, and other edge cases
    54→ */
    55→function lookupHeadshot(headshotMap, firstName, lastName) {
    56→  if (!firstName && !lastName) return null;
    57→
    58→  // Get all possible lookup keys for this name
    59→  const keys = getLookupKeys(firstName, lastName);
    60→
    61→  // Try each key until we find a match
    62→  for (const key of keys) {
    63→    if (headshotMap[key]) {
    64→      return headshotMap[key];
    65→    }
    66→  }
    67→
    68→  return null;
    69→}
