    71→/**
    72→ * Parse Virtius roster HTML to extract RTN IDs and headshot URLs
    73→ * @param {string} html - Raw HTML from Virtius roster table
    74→ * @returns {Array<{rtnId: string, headshotUrl: string, name: string}>}
    75→ */
    76→export function parseVirtiusRosterHtml(html) {
    77→  const results = [];
    78→
    79→  // Match each row: find athlete name, headshot URL, and RTN ID
    80→  // Pattern: img src for headshot, then name in a div, then rtnId in an input
    81→  const rowRegex = /<tr[^>]*role="row"[^>]*>([\s\S]*?)<\/tr>/gi;
    82→  const imgRegex = /src="(https:\/\/media\.virti\.us\/upload\/images\/athlete\/[^"]+)"/i;
    83→  const nameRegex = /alt="([^"]+)\s+Profile"/i;
    84→  const rtnIdRegex = /<input[^>]*readonly[^>]*value="(\d+)"/i;
    85→
    86→  let match;
    87→  while ((match = rowRegex.exec(html)) !== null) {
    88→    const rowHtml = match[1];
    89→
    90→    const imgMatch = rowHtml.match(imgRegex);
    91→    const nameMatch = rowHtml.match(nameRegex);
    92→    const rtnIdMatch = rowHtml.match(rtnIdRegex);
    93→
    94→    if (imgMatch && rtnIdMatch) {
    95→      results.push({
    96→        headshotUrl: imgMatch[1],
    97→        name: nameMatch ? nameMatch[1] : 'Unknown',
    98→        rtnId: rtnIdMatch[1],
    99→      });
   100→    }
   101→  }
   102→
   103→  return results;
   104→}
