   378→export function useCompetitions() {
   379→  const [competitions, setCompetitions] = useState({});
   380→  const [loading, setLoading] = useState(true);
   381→  const [error, setError] = useState(null);
   382→
   383→  useEffect(() => {
   384→    const competitionsRef = ref(db, 'competitions');
   385→
   386→    const unsubscribe = onValue(competitionsRef, (snapshot) => {
   387→      setCompetitions(snapshot.val() || {});
   388→      setLoading(false);
   389→    }, (err) => {
   390→      setError(err.message);
   391→      setLoading(false);
