   396→
   397→  const createCompetition = useCallback(async (compId, config, options = {}) => {
   398→    try {
   399→      await set(ref(db, `competitions/${compId}/config`), config);
   400→
   401→      // Optionally enrich with RTN data
   402→      if (options.enrichWithRTN !== false) {
   403→        // Use explicit gender field if available, otherwise extract from compType (backward compatibility)
   404→        const gender = config.gender || (config.compType?.startsWith('womens') ? 'womens' : 'mens');
   405→        const teamData = await enrichTeamsWithRTN(config, gender);
   406→        if (Object.keys(teamData).length > 0) {
   407→          await set(ref(db, `competitions/${compId}/teamData`), teamData);
   408→
   409→          // Also sync coaches to config as newline-separated strings for graphics
   410→          const configUpdates = {};
   411→          for (const teamKey of Object.keys(teamData)) {
   412→            const coaches = teamData[teamKey]?.coaches;
   413→            if (coaches && Array.isArray(coaches) && coaches.length > 0) {
   414→              const coachesString = coaches.map(c => c.fullName).join('\n');
   415→              configUpdates[`${teamKey}Coaches`] = coachesString;
   416→            }
   417→          }
   418→
   419→          if (Object.keys(configUpdates).length > 0) {
   420→            await update(ref(db, `competitions/${compId}/config`), configUpdates);
   421→          }
   422→        }
   423→      }
   424→
   425→      return { success: true };
   426→    } catch (err) {
   427→      return { success: false, error: err.message };
   428→    }
