   317→    const firstName = parts[0] || '';
   318→    const lastName = parts.slice(1).join(' ') || '';
   319→    const keys = getLookupKeys(firstName, lastName);
   320→
   321→    for (const key of keys) {
   322→      const keySafe = getSafeFirebaseKey(key);
   323→      if (headshots[keySafe]?.url) {
   324→        return headshots[keySafe].url;
   325→      }
   326→      if (headshots[key]?.url) {
   327→        return headshots[key].url;
   328→      }
   329→    }
   330→
   331→    return '';
   332→  }, [headshots]);
   333→
   334→  /**
   335→   * Check if athlete has a headshot
   336→   */
   337→  const hasHeadshot = useCallback((athleteName) => {
   338→    return !!getHeadshot(athleteName);
   339→  }, [getHeadshot]);
   340→
   341→  /**
   342→   * Get roster with headshot info for a team
   343→   */
   344→  const getTeamRosterWithHeadshots = useCallback((teamKey) => {
   345→    const team = getTeam(teamKey);
   346→    if (!team?.roster) return [];
   347→
   348→    return team.roster.map(name => ({
   349→      name,
   350→      hasHeadshot: hasHeadshot(name),
   351→      headshotUrl: getHeadshot(name),
   352→    }));
   353→  }, [getTeam, hasHeadshot, getHeadshot]);
   354→
   355→  /**
   356→   * Get roster stats for a team
   357→   */
   358→  const getTeamRosterStats = useCallback((teamKey) => {
   359→    const roster = getTeamRosterWithHeadshots(teamKey);
   360→    const withHeadshots = roster.filter(a => a.hasHeadshot).length;
   361→    return {
   362→      total: roster.length,
   363→      withHeadshots,
   364→      percentage: roster.length > 0 ? Math.round((withHeadshots / roster.length) * 100) : 0,
   365→    };
   366→  }, [getTeamRosterWithHeadshots]);
   367→
   368→  /**
   369→   * Resolve a team name to a school key (handles aliases and variations)
   370→   * E.g., "California" -> "cal", "Penn State" -> "penn-state"
   371→   */
   372→  const resolveSchoolKey = useCallback((teamName) => {
   373→    if (!teamName) return null;
   374→
   375→    const normalized = normalizeName(teamName)
   376→      .replace(/ men'?s?$/i, '')
   377→      .replace(/ women'?s?$/i, '')
   378→      .replace(/-mens$/, '')
   379→      .replace(/-womens$/, '');
   380→
   381→    // Check aliases first
   382→    if (aliases[normalized]) {
   383→      return aliases[normalized];
   384→    }
   385→
   386→    // Check if any team key starts with this school name
   387→    const possibleKeys = Object.keys(teams).filter(key =>
   388→      key.startsWith(normalized + '-') ||
   389→      key === normalized
   390→    );
   391→
   392→    if (possibleKeys.length > 0) {
   393→      // Extract school part from key (e.g., "penn-state-mens" -> "penn-state")
   394→      return possibleKeys[0].replace(/-mens$/, '').replace(/-womens$/, '');
   395→    }
   396→
   397→    // Try converting spaces to dashes
   398→    const dashedName = normalized.replace(/ /g, '-');
   399→    if (aliases[dashedName]) {
   400→      return aliases[dashedName];
   401→    }
   402→
   403→    const dashedPossibleKeys = Object.keys(teams).filter(key =>
   404→      key.startsWith(dashedName + '-') ||
   405→      key === dashedName
   406→    );
   407→
   408→    if (dashedPossibleKeys.length > 0) {
   409→      return dashedPossibleKeys[0].replace(/-mens$/, '').replace(/-womens$/, '');
   410→    }
   411→
   412→    return null;
   413→  }, [teams, aliases]);
   414→
   415→  /**
   416→   * Get team with flexible matching (handles various name formats)
   417→   * @param {string} teamName - Team name in any format (e.g., "Penn State", "California Men's")
   418→   * @param {string} gender - Optional gender: 'mens' or 'womens'
   419→   */
   420→  const getTeamFlexible = useCallback((teamName, gender = null) => {
   421→    if (!teamName) return null;
   422→
   423→    // First try exact match
   424→    const exactMatch = getTeam(teamName);
   425→    if (exactMatch) return exactMatch;
   426→
   427→    // Resolve to school key
   428→    const schoolKey = resolveSchoolKey(teamName);
   429→    if (!schoolKey) return null;
   430→
   431→    // Determine gender from input
   432→    const normalized = normalizeName(teamName);
   433→    let targetGender = gender;
   434→    if (!targetGender) {
   435→      if (normalized.includes('women') || normalized.includes('womens')) {
   436→        targetGender = 'womens';
   437→      } else if (normalized.includes('men') || normalized.includes('mens')) {
   438→        targetGender = 'mens';
   439→      }
   440→    }
   441→
   442→    // Try to get team with specific gender
   443→    if (targetGender) {
   444→      const teamWithGender = teams[`${schoolKey}-${targetGender}`];
   445→      if (teamWithGender) return teamWithGender;
   446→    }
   447→
   448→    // Try mens first, then womens
   449→    if (teams[`${schoolKey}-mens`]) return teams[`${schoolKey}-mens`];
   450→    if (teams[`${schoolKey}-womens`]) return teams[`${schoolKey}-womens`];
   451→
   452→    return null;
   453→  }, [teams, getTeam, resolveSchoolKey]);
   454→
   455→  /**
   456→   * Get roster stats with flexible matching
   457→   * @param {string} teamName - Team name in any format
   458→   * @param {string} gender - Optional gender
   459→   */
   460→  const getTeamRosterStatsFlexible = useCallback((teamName, gender = null) => {
   461→    const team = getTeamFlexible(teamName, gender);
   462→    if (!team?.roster?.length) {
   463→      return { total: 0, withHeadshots: 0, percentage: 0 };
   464→    }
   465→
   466→    const withHeadshots = team.roster.filter(name => hasHeadshot(name)).length;
   467→    return {
   468→      total: team.roster.length,
   469→      withHeadshots,
   470→      percentage: Math.round((withHeadshots / team.roster.length) * 100),
   471→    };
   472→  }, [getTeamFlexible, hasHeadshot]);
   473→
   474→  /**
   475→   * Check if team has a roster (with flexible matching)
   476→   */
   477→  const hasTeamRoster = useCallback((teamName, gender = null) => {
   478→    const team = getTeamFlexible(teamName, gender);
   479→    return team?.roster?.length > 0;
   480→  }, [getTeamFlexible]);
   481→
   482→  /**
   483→   * Get all team keys
   484→   */
   485→  const getAllTeamKeys = useCallback(() => {
   486→    return Object.keys(teams);
   487→  }, [teams]);
   488→
   489→  /**
   490→   * Get all schools (unique)
   491→   */
   492→  const getAllSchools = useCallback(() => {
   493→    const schools = new Set();
   494→    for (const team of Object.values(teams)) {
   495→      if (team.school) schools.add(team.school);
   496→    }
   497→    return Array.from(schools).sort();
   498→  }, [teams]);
   499→
   500→  /**
   501→   * Get teams grouped by school
   502→   */
   503→  const getTeamsBySchool = useCallback(() => {
   504→    const bySchool = {};
   505→    for (const [key, team] of Object.entries(teams)) {
   506→      if (!team.school) continue;
   507→      if (!bySchool[team.school]) {
   508→        bySchool[team.school] = [];
   509→      }
   510→      bySchool[team.school].push({ key, ...team });
   511→    }
   512→    return bySchool;
   513→  }, [teams]);
   514→
   515→  // ============================================
   516→  // MIGRATION HELPER
   517→  // ============================================
   518→
   519→  /**
   520→   * Migrate data from static teamsDatabase.js to Firebase
   521→   * Call this once to populate Firebase with existing data
   522→   */
   523→  const migrateFromStatic = useCallback(async (staticTeams, staticHeadshots, staticAliases) => {
   524→    try {
   525→      // Migrate teams
   526→      for (const [key, team] of Object.entries(staticTeams)) {
   527→        await saveTeam(key, team);
   528→      }
   529→
   530→      // Migrate headshots
   531→      const headshotsArray = Object.entries(staticHeadshots).map(([name, url]) => ({
   532→        name,
   533→        headshotUrl: url,
   534→      }));
   535→      await saveHeadshots(headshotsArray);
   536→
   537→      // Migrate aliases
   538→      if (staticAliases) {
   539→        await set(ref(db, 'teamsDatabase/aliases'), staticAliases);
   540→      }
   541→
   542→      return { success: true };
   543→    } catch (err) {
   544→      return { success: false, error: err.message };
   545→    }
   546→  }, [saveTeam, saveHeadshots]);
   547→
   548→  // ============================================
   549→  // DIAGNOSTICS
   550→  // ============================================
   551→
   552→  /**
   553→   * Run data integrity diagnostics
   554→   * Checks for common issues like orphaned headshots, missing data, etc.
   555→   * @returns {Object} Diagnostic results with issues found
   556→   */
   557→  const runDiagnostics = useCallback(() => {
   558→    const issues = [];
   559→    const stats = {
   560→      totalTeams: Object.keys(teams).length,
   561→      totalHeadshots: Object.keys(headshots).length,
   562→      teamsWithRosters: 0,
   563→      teamsWithLogos: 0,
   564→      totalRosterEntries: 0,
   565→      headshotsMatched: 0,
   566→      headshotsOrphaned: 0,
   567→    };
   568→
   569→    // Check each team
   570→    for (const [teamKey, team] of Object.entries(teams)) {
   571→      if (team.logo) stats.teamsWithLogos++;
   572→      if (team.roster?.length > 0) {
   573→        stats.teamsWithRosters++;
   574→        stats.totalRosterEntries += team.roster.length;
   575→
   576→        // Check each roster entry for headshot
   577→        for (const name of team.roster) {
   578→          const headshotUrl = getHeadshot(name);
   579→          if (!headshotUrl) {
   580→            issues.push({
   581→              type: 'missing_headshot',
   582→              severity: 'warning',
   583→              teamKey,
   584→              athleteName: name,
   585→              message: `No headshot found for "${name}" on ${team.displayName || teamKey}`,
   586→            });
   587→          } else {
   588→            stats.headshotsMatched++;
   589→          }
   590→        }
   591→      }
   592→
   593→      // Check for missing required fields
   594→      if (!team.displayName) {
   595→        issues.push({
   596→          type: 'missing_field',
   597→          severity: 'error',
   598→          teamKey,
   599→          field: 'displayName',
   600→          message: `Team "${teamKey}" is missing displayName`,
   601→        });
   602→      }
   603→      if (!team.school) {
   604→        issues.push({
   605→          type: 'missing_field',
   606→          severity: 'error',
   607→          teamKey,
   608→          field: 'school',
   609→          message: `Team "${teamKey}" is missing school name`,
   610→        });
   611→      }
   612→      if (!team.gender) {
   613→        issues.push({
   614→          type: 'missing_field',
   615→          severity: 'error',
   616→          teamKey,
   617→          field: 'gender',
   618→          message: `Team "${teamKey}" is missing gender`,
   619→        });
   620→      }
   621→    }
   622→
   623→    // Check for headshots with invalid teamKey references
   624→    for (const [key, headshot] of Object.entries(headshots)) {
   625→      if (headshot.teamKey && !teams[headshot.teamKey]) {
