   642→function TeamInfoDisplay({ teamName, gender }) {
   643→  const { dashboard, loading } = useTeamDashboard(teamName, gender);
   644→
   645→  if (loading) {
   646→    return (
   647→      <div className="flex items-center justify-center py-8">
   648→        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-cyan-500"></div>
   649→        <span className="ml-3 text-zinc-400">Loading team data from Road to Nationals...</span>
   650→      </div>
   651→    );
   652→  }
   653→
   654→  // Derive all data from the single dashboard response
   655→  const staff = dashboard?.staff
   656→    ?.filter(s => s.position?.toLowerCase().includes('coach'))
   657→    .map(s => ({
   658→      id: s.id,
   659→      fullName: `${s.first_name?.trim() || ''} ${s.last_name?.trim() || ''}`.trim(),
   660→      position: s.position,
   661→      imageUrl: s.image_url ? `https://www.roadtonationals.com/images/staff/${s.image_url}` : null,
   662→    }))
   663→    .sort((a, b) => {
   664→      if (a.position?.toLowerCase().includes('head')) return -1;
   665→      if (b.position?.toLowerCase().includes('head')) return 1;
   666→      return 0;
   667→    }) || [];
   668→
   669→  const links = {};
   670→  if (dashboard?.links) {
   671→    for (const link of dashboard.links) {
   672→      const type = link.tax_value?.toLowerCase() || '';
   673→      if (type.includes('facebook')) links.facebook = link.link;
   674→      else if (type.includes('twitter')) links.twitter = link.link;
   675→      else if (type.includes('instagram')) links.instagram = link.link;
   676→      else if (type.includes('official')) links.officialSite = link.link;
   677→    }
   678→  }
   679→
   680→  const ranks = dashboard?.ranks;
   681→  const rankings = ranks ? (gender === 'womens' ? {
   682→    vault: ranks.vault ? parseInt(ranks.vault) : null,
   683→    bars: ranks.bars ? parseInt(ranks.bars) : null,
   684→    beam: ranks.beam ? parseInt(ranks.beam) : null,
   685→    floor: ranks.floor ? parseInt(ranks.floor) : null,
   686→    team: ranks.team ? parseInt(ranks.team) : null,
   687→  } : {
   688→    floor: ranks.floor ? parseInt(ranks.floor) : null,
   689→    pommel: ranks.pommel ? parseInt(ranks.pommel) : null,
   690→    rings: ranks.rings ? parseInt(ranks.rings) : null,
   691→    vault: ranks.vault ? parseInt(ranks.vault) : null,
   692→    pBars: ranks.pbars ? parseInt(ranks.pbars) : null,
   693→    hBar: ranks.hbar ? parseInt(ranks.hbar) : null,
   694→    team: ranks.team ? parseInt(ranks.team) : null,
   695→  }) : null;
   696→
   697→  const roster = dashboard?.roster?.map(r => ({
   698→    id: r.id,
   699→    fullName: `${r.fname?.trim() || ''} ${r.lname?.trim() || ''}`.trim(),
   700→    hometown: r.hometown || '',
   701→    year: r.school_year ? parseInt(r.school_year) : null,
   702→  })) || [];
   703→
   704→  const hasData = staff.length > 0 || Object.keys(links).length > 0 || rankings || roster.length > 0;
   705→
   706→  if (!hasData) {
   707→    return (
   708→      <div className="text-center py-6 text-zinc-500">
   709→        <p>No data found for "{teamName}" ({gender === 'womens' ? "Women's" : "Men's"})</p>
   710→        <p className="text-xs mt-1">Try a different team name or check spelling</p>
   711→      </div>
   712→    );
   713→  }
   714→
   715→  return (
   716→    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
   717→      {/* Coaching Staff */}
   718→      <div className="bg-zinc-800/50 rounded-lg p-4">
   719→        <h3 className="text-sm font-semibold text-white mb-3 flex items-center gap-2">
   720→          <UserGroupIcon className="w-4 h-4 text-cyan-500" />
   721→          Coaching Staff ({staff.length})
   722→        </h3>
   723→        {staff.length > 0 ? (
   724→          <div className="space-y-2">
   725→            {staff.map((coach) => (
   726→              <div key={coach.id} className="flex items-center gap-3 p-2 bg-zinc-700/50 rounded">
   727→                <div className="w-10 h-10 bg-zinc-600 rounded-full flex items-center justify-center overflow-hidden flex-shrink-0">
   728→                  {coach.imageUrl ? (
   729→                    <img src={coach.imageUrl} alt={coach.fullName} className="w-10 h-10 object-cover" />
   730→                  ) : (
   731→                    <UserGroupIcon className="w-5 h-5 text-zinc-400" />
   732→                  )}
   733→                </div>
   734→                <div className="flex-1 min-w-0">
   735→                  <div className="text-sm font-medium text-white truncate">{coach.fullName}</div>
   736→                  <div className="text-xs text-zinc-400">{coach.position}</div>
   737→                </div>
   738→              </div>
   739→            ))}
   740→          </div>
   741→        ) : (
   742→          <p className="text-zinc-500 text-sm">No coaching staff found</p>
   743→        )}
   744→      </div>
   745→
   746→      {/* Rankings */}
