  sleep,
  getGenderPath,
  getConsistencyEvents,
  getMvpEvents,
  getIndividualFields,
  getIndividualEventNumbers,
  getTopScoreEvents,
  getTeamRankingType,

  // Fetch functions
  fetchWithRetry,
  rateLimitedFetch,
  fetchConsistency,
  fetchMVP,
  fetchTopScores,
  fetchLineup,
  fetchIndividualHighs,
  fetchIndividualAverages,
  fetchTeamRanking,
  getCurrentWeek,

  // URL builder
  buildTeamStatUrls,
};

