    db = admin.database();
    initialized = true;
    return db;
  } catch (error) {
    console.error('[ProductionConfigService] Failed to initialize Firebase Admin SDK:', error.message);
    return null;
  }
}

function getDb() {
  if (!db) {
    initializeFirebase();
  }
  return db;
}
