   633→// ============================================================================
   634→// Orchestration Functions (Task 5)
   635→// ============================================================================
   636→
   637→import productionConfigService from './productionConfigService.js';
   638→
   639→const DEDUP_WINDOW_MS = 60 * 1000; // 60 seconds — skip if another ingestion just completed
   640→
   641→/**
   642→ * Parse competition type to extract gender and team count.
   643→ * @param {string} compType - e.g., "womens-dual", "mens-tri", "womens-quad"
   644→ * @returns {{ gender: string, teamCount: number }}
   645→ */
   646→function parseCompetitionType(compType) {
   647→  if (!compType) return { gender: 'womens', teamCount: 2 };
   648→  const parts = compType.toLowerCase().split('-');
   649→  const gender = parts[0] === 'mens' ? 'mens' : 'womens';
   650→  let teamCount = 2;
   651→  if (parts[1]) {
   652→    const typeMap = { dual: 2, tri: 3, quad: 4, '5': 5, '6': 6 };
   653→    teamCount = typeMap[parts[1]] || 2;
   654→  }
   655→  return { gender, teamCount };
   656→}
   657→
   658→/**
   659→ * Build a teamsDatabase key from a team name and gender.
   660→ * Matches the client-side buildTeamKey() logic: lowercase, strip gender suffixes, hyphenate.
   661→ * @param {string} schoolName - e.g., "Oklahoma", "Stanford"
   662→ * @param {string} gender - "mens" or "womens"
   663→ * @returns {string} e.g., "oklahoma-womens"
   664→ */
   665→function buildTeamDbKey(schoolName, gender) {
   666→  if (!schoolName) return '';
   667→  const normalized = schoolName
   668→    .toLowerCase()
   669→    .replace(/['']/g, '')
   670→    .replace(/[^a-z0-9\s-]/g, '')
   671→    .replace(/-mens$/, '')
   672→    .replace(/-womens$/, '')
   673→    .replace(/ mens$/, '')
   674→    .replace(/ womens$/, '')
   675→    .replace(/ men$/, '')
   676→    .replace(/ women$/, '')
   677→    .replace(/\s+/g, '-')
   678→    .trim();
   679→  if (!normalized) return '';
   680→  const genderSuffix = gender === 'womens' ? 'womens' : 'mens';
   681→  return `${normalized}-${genderSuffix}`;
   682→}
   683→
   684→/**
   685→ * Check if a team's stats are stale (older than STALENESS_TTL).
   686→ * @param {string} teamKey - teamsDatabase key, e.g., "oklahoma-womens"
   687→ * @returns {Promise<{ isStale: boolean, fetchedAt: string|null, withinDedup: boolean }>}
   688→ */
   689→async function checkStaleness(teamKey) {
   690→  const db = productionConfigService.getDb();
   691→  if (!db) return { isStale: true, fetchedAt: null, withinDedup: false };
   692→
   693→  try {
   694→    const snapshot = await db.ref(`teamsDatabase/stats/${teamKey}/meta/fetchedAt`).once('value');
   695→    const fetchedAt = snapshot.val();
   696→
   697→    if (!fetchedAt) return { isStale: true, fetchedAt: null, withinDedup: false };
   698→
   699→    const fetchedTime = new Date(fetchedAt).getTime();
   700→    const now = Date.now();
   701→    const age = now - fetchedTime;
   702→
   703→    return {
   704→      isStale: age > STALENESS_TTL,
   705→      fetchedAt,
   706→      withinDedup: age < DEDUP_WINDOW_MS,
   707→    };
   708→  } catch (err) {
   709→    console.error(`[rtnStatsService] Error checking staleness for ${teamKey}:`, err.message);
   710→    return { isStale: true, fetchedAt: null, withinDedup: false };
   711→  }
   712→}
   713→
   714→/**
   715→ * Ingest stats for a single team: fetch all RTN endpoints, normalize, and write to Firebase.
   716→ *
   717→ * @param {string} teamKey - teamsDatabase key, e.g., "oklahoma-womens"
   718→ * @param {string|number} rtnId - RTN team ID
   719→ * @param {string} gender - "mens" or "womens"
   720→ * @param {number} year - Season year
   721→ * @param {Object} [io] - Socket.IO server instance for progress events
   722→ * @param {string} [compId] - Competition ID for progress events
   723→ * @returns {Promise<{ status: string, endpointStatus: Object, errors: Object|null }>}
   724→ */
   725→async function ingestTeamStats(teamKey, rtnId, gender, year, io, compId) {
   726→  const db = productionConfigService.getDb();
   727→  if (!db) {
   728→    return { status: 'error', endpointStatus: {}, errors: { firebase: 'Firebase not available' } };
   729→  }
   730→
   731→  const tidStr = String(rtnId);
   732→
   733→  // Get current week for team ranking endpoint
   734→  let week;
   735→  try {
   736→    week = await getCurrentWeek(gender, year);
   737→  } catch (err) {
   738→    console.warn(`[rtnStatsService] Failed to get week, using 1: ${err.message}`);
   739→    week = 1;
   740→  }
   741→
   742→  // Build URLs and fetch all endpoints
   743→  const urls = buildTeamStatUrls(gender, year, tidStr, week);
   744→
   745→  const onProgress = (label, step, total, status) => {
   746→    console.log(`[rtnStatsService] ${teamKey}: ${label} (${step}/${total}) - ${status}`);
   747→    if (io && compId) {
   748→      const roomName = `competition:${compId}`;
   749→      io.to(roomName).emit('rtnStatsProgress', {
   750→        compId,
   751→        teamKey,
   752→        endpoint: label,
   753→        step,
   754→        total,
   755→        status,
   756→      });
   757→    }
   758→  };
   759→
   760→  const fetchResults = await rateLimitedFetch(urls, onProgress);
   761→
   762→  // Normalize all results
   763→  const { normalized, endpointStatus } = normalizeAllResults(fetchResults, gender, tidStr);
   764→
   765→  // Determine overall status
   766→  const statuses = Object.values(endpointStatus);
   767→  const errorCount = statuses.filter(s => s === 'error').length;
   768→  let overallStatus;
   769→  if (errorCount === statuses.length) {
   770→    overallStatus = 'error';
   771→  } else if (errorCount > 0) {
   772→    overallStatus = 'partial';
   773→  } else {
   774→    overallStatus = 'complete';
   775→  }
   776→
   777→  // Build error details
   778→  const errors = {};
   779→  for (const result of fetchResults) {
   780→    if (result.status === 'error') {
   781→      errors[result.label] = result.error || 'Unknown error';
   782→    }
   783→  }
   784→
   785→  // Build meta
   786→  const meta = {
   787→    fetchedAt: new Date().toISOString(),
   788→    rtnId: tidStr,
   789→    year,
   790→    gender,
   791→    week,
   792→    status: overallStatus,
   793→    errors: Object.keys(errors).length > 0 ? errors : null,
   794→    endpointStatus,
   795→  };
   796→
   797→  // Write to Firebase: teamsDatabase/stats/{teamKey}/
   798→  try {
   799→    const statsRef = db.ref(`teamsDatabase/stats/${teamKey}`);
   800→    const writeData = { ...normalized, meta };
   801→    await statsRef.set(writeData);
   802→    console.log(`[rtnStatsService] Wrote stats for ${teamKey} (status: ${overallStatus})`);
   803→  } catch (err) {
   804→    console.error(`[rtnStatsService] Failed to write stats for ${teamKey}:`, err.message);
   805→    return { status: 'error', endpointStatus, errors: { ...errors, firebase: err.message } };
   806→  }
   807→
   808→  return { status: overallStatus, endpointStatus, errors: Object.keys(errors).length > 0 ? errors : null };
   809→}
   810→
   811→/**
   812→ * Ingest RTN stats for all teams in a competition.
   813→ * Checks staleness, deduplicates, fetches if needed, writes to shared store.
   814→ *
   815→ * @param {string} compId - Competition ID
   816→ * @param {Object} [io] - Socket.IO server instance for progress/result events
   817→ * @returns {Promise<{ success: boolean, teams: Object, error?: string }>}
   818→ */
   819→async function ingestCompetitionStats(compId, io) {
   820→  const db = productionConfigService.getDb();
   821→  if (!db) {
   822→    return { success: false, teams: {}, error: 'Firebase not available' };
   823→  }
   824→
   825→  console.log(`[rtnStatsService] Starting ingestion for competition ${compId}`);
   826→
   827→  // Read competition config
   828→  let config;
   829→  try {
   830→    const configSnapshot = await db.ref(`competitions/${compId}/config`).once('value');
   831→    config = configSnapshot.val();
   832→  } catch (err) {
   833→    console.error(`[rtnStatsService] Failed to read config for ${compId}:`, err.message);
   834→    return { success: false, teams: {}, error: `Failed to read config: ${err.message}` };
   835→  }
   836→
   837→  if (!config) {
   838→    return { success: false, teams: {}, error: 'Competition config not found' };
   839→  }
   840→
   841→  // Extract gender and team count
   842→  const { gender, teamCount } = parseCompetitionType(config.compType);
   843→  const year = new Date().getFullYear();
   844→
   845→  // Build team name list from config
   846→  const teamNames = [];
   847→  for (let i = 1; i <= teamCount; i++) {
   848→    const name = config[`team${i}Name`];
   849→    if (name) teamNames.push({ index: i, name });
   850→  }
   851→
   852→  if (teamNames.length === 0) {
   853→    return { success: false, teams: {}, error: 'No team names found in config' };
   854→  }
   855→
   856→  const teamResults = {};
   857→
   858→  for (const { index, name } of teamNames) {
   859→    const teamKey = buildTeamDbKey(name, gender);
   860→    if (!teamKey) {
   861→      console.warn(`[rtnStatsService] Could not build team key for "${name}"`);
   862→      teamResults[`team${index}`] = { teamKey: null, status: 'error', error: 'Invalid team name' };
   863→      continue;
   864→    }
   865→
   866→    // Look up RTN ID from teamsDatabase
   867→    let rtnId;
   868→    try {
   869→      const rtnIdSnapshot = await db.ref(`teamsDatabase/teams/${teamKey}/rtnId`).once('value');
   870→      rtnId = rtnIdSnapshot.val();
   871→    } catch (err) {
   872→      console.error(`[rtnStatsService] Failed to read rtnId for ${teamKey}:`, err.message);
   873→    }
   874→
   875→    if (!rtnId) {
   876→      console.warn(`[rtnStatsService] No RTN ID for team ${teamKey} — skipping`);
   877→      // Write error to meta so the UI can see it
   878→      try {
   879→        await db.ref(`teamsDatabase/stats/${teamKey}/meta`).update({
   880→          status: 'error',
   881→          errors: { rtnId: 'RTN ID not set. Run Media Manager team setup first.' },
   882→          fetchedAt: new Date().toISOString(),
   883→        });
   884→      } catch (e) {
   885→        // Best effort
   886→      }
   887→      teamResults[`team${index}`] = { teamKey, status: 'error', error: 'Missing RTN ID' };
   888→      continue;
   889→    }
   890→
   891→    // Check staleness
   892→    const staleness = await checkStaleness(teamKey);
   893→
   894→    if (staleness.withinDedup) {
   895→      console.log(`[rtnStatsService] ${teamKey}: Recently ingested (dedup window), skipping`);
   896→      teamResults[`team${index}`] = { teamKey, status: 'skipped', reason: 'dedup' };
   897→      continue;
   898→    }
   899→
   900→    if (!staleness.isStale) {
   901→      console.log(`[rtnStatsService] ${teamKey}: Stats are fresh (fetched ${staleness.fetchedAt}), skipping`);
   902→      teamResults[`team${index}`] = { teamKey, status: 'skipped', reason: 'fresh' };
   903→      continue;
   904→    }
   905→
   906→    // Stats are stale or missing — fetch from RTN
   907→    console.log(`[rtnStatsService] ${teamKey}: Stats are stale/missing, fetching from RTN...`);
   908→    const result = await ingestTeamStats(teamKey, rtnId, gender, year, io, compId);
   909→    teamResults[`team${index}`] = { teamKey, ...result };
   910→  }
   911→
   912→  const allStatuses = Object.values(teamResults).map(r => r.status);
