  fetchConsistency,
  fetchMVP,
  fetchTopScores,
  fetchLineup,
  fetchIndividualHighs,
  fetchIndividualAverages,
  fetchTeamRanking,
  getCurrentWeek,

  // URL builder
  buildTeamStatUrls,

  // Score parsing
  parseScore,
  toRtnIdString,

  // Normalization functions (Task 4)
  normalizeConsistency,
  normalizeMVP,
  normalizeTopScores,
  normalizeLineup,
  normalizeIndividualHighs,
  normalizeIndividualAverages,
  normalizeIndividualStats,
