  timesheetEngine.on('autoAdvancing', (data) => {
    console.log(`Timesheet: Auto-advancing from ${data.fromSegmentId} to segment ${data.toSegmentIndex}`);
    io.to(localRoom).emit('timesheetAutoAdvancing', data);
