  vmPoolManager.on('vmInUse', (data) => {
    console.log(`[VMPool] VM ${data.vmId} is now in use for competition ${data.competitionId}`);
    io.emit('vmInUse', data);
    io.emit('vmPoolStatus', vmPoolManager.getPoolStatus());
