      socket.emit('aiContextRefreshResult', {
        success: false,
        error: 'No competition ID provided'
      });
      return;
    }

    const service = getContextService(targetCompId);
    if (!service || !service.isRunning) {
      socket.emit('aiContextRefreshResult', {
        success: false,
        error: 'AI Context Service not running'
      });
      return;
