   156→
   157→    const fetchAll = async () => {
   158→      const results = new Map();
   159→
   160→      // Group by gender to minimize API calls
   161→      const byGender = {
   162→        mens: teamsList.filter(t => t.gender === 'mens'),
   163→        womens: teamsList.filter(t => t.gender === 'womens'),
   164→      };
   165→
   166→      try {
   167→        // Fetch men's teams data once
   168→        if (byGender.mens.length > 0) {
   169→          const mensData = await getCachedTeams('mens');
   170→          for (const team of byGender.mens) {
