    71→    const unsubAliases = onValue(aliasesRef, (snapshot) => {
    72→      setAliases(snapshot.val() || {});
    73→      checkLoaded();
    74→    }, (err) => {
    75→      setError(err.message);
    76→      checkLoaded();
    77→    });
    78→
    79→    return () => {
    80→      unsubTeams();
    81→      unsubHeadshots();
    82→      unsubAliases();
    83→    };
    84→  }, []);
