   254→  /**
   255→   * Get team logo with flexible matching
   256→   * @param {string} teamName - Team name in any format
   257→   * @param {'womens' | 'mens' | null} preferredGender - Preferred gender for fallback lookup
   258→   */
   259→  const getTeamLogo = useCallback((teamName, preferredGender = null) => {
   260→    if (!teamName) return '';
   261→
   262→    const normalized = normalizeName(teamName);
   263→
   264→    // Direct match
   265→    if (teams[normalized]) return teams[normalized].logo || '';
   266→
   267→    // Try with -mens/-womens suffix removed
   268→    const withoutGender = normalized
   269→      .replace(/-mens$/, '')
   270→      .replace(/-womens$/, '')
   271→      .replace(/ men'?s?$/i, '')
   272→      .replace(/ women'?s?$/i, '');
   273→
   274→    // Determine lookup order based on preferredGender
   275→    const genderOrder = preferredGender === 'womens'
   276→      ? ['womens', 'mens']
   277→      : ['mens', 'womens'];
   278→
   279→    // Check aliases
   280→    const aliasKey = aliases[withoutGender];
   281→    if (aliasKey) {
   282→      for (const gender of genderOrder) {
   283→        const team = teams[`${aliasKey}-${gender}`];
   284→        if (team?.logo) return team.logo;
   285→      }
   286→    }
   287→
   288→    // Try direct school match with gender preference
   289→    for (const gender of genderOrder) {
   290→      if (teams[`${withoutGender}-${gender}`]?.logo) {
   291→        return teams[`${withoutGender}-${gender}`].logo;
   292→      }
   293→    }
   294→
   295→    return '';
   296→  }, [teams, aliases]);
