   298→  /**
   299→   * Get athlete headshot URL using flexible lookup
   300→   * Tries multiple normalized keys to handle accents, hyphens, etc.
   301→   *
   302→   * Lookup order (optimized for speed):
   303→   * 1. Safe Firebase key (most likely match - this is how we save)
   304→   * 2. Normalized name (fallback for legacy data)
   305→   * 3. Extended keys for edge cases (accents, middle names, etc.)
   306→   */
   307→  const getHeadshot = useCallback((athleteName) => {
   308→    if (!athleteName) return '';
   309→
   310→    // Primary lookup: normalize name and convert to safe Firebase key
   311→    // This matches how saveHeadshot() stores the data
   312→    const normalized = normalizeName(athleteName);
   313→    const safeKey = getSafeFirebaseKey(normalized);
   314→
   315→    // Try safe key first (this is how we save headshots)
   316→    if (headshots[safeKey]?.url) {
   317→      return headshots[safeKey].url;
   318→    }
   319→
   320→    // Fallback: try normalized name without safe key transformation
   321→    // (handles legacy data or data imported differently)
   322→    if (headshots[normalized]?.url) {
   323→      return headshots[normalized].url;
   324→    }
   325→
   326→    // Extended fallback: use getLookupKeys for edge cases (accents, middle names, etc.)
   327→    const parts = athleteName.trim().split(/\s+/);
   328→    const firstName = parts[0] || '';
   329→    const lastName = parts.slice(1).join(' ') || '';
   330→    const keys = getLookupKeys(firstName, lastName);
   331→
   332→    for (const key of keys) {
   333→      const keySafe = getSafeFirebaseKey(key);
   334→      if (headshots[keySafe]?.url) {
   335→        return headshots[keySafe].url;
   336→      }
   337→      if (headshots[key]?.url) {
   338→        return headshots[key].url;
   339→      }
   340→    }
   341→
   342→    return '';
   343→  }, [headshots]);
