   385→  /**
   386→   * Resolve a team name to a school key (handles aliases and variations)
   387→   * E.g., "California" -> "cal", "Penn State" -> "penn-state"
   388→   */
   389→  const resolveSchoolKey = useCallback((teamName) => {
   390→    if (!teamName) return null;
   391→
   392→    const normalized = normalizeName(teamName)
   393→      .replace(/ men'?s?$/i, '')
   394→      .replace(/ women'?s?$/i, '')
   395→      .replace(/-mens$/, '')
   396→      .replace(/-womens$/, '');
   397→
   398→    // Check aliases first
   399→    if (aliases[normalized]) {
   400→      return aliases[normalized];
   401→    }
   402→
   403→    // Check if any team key starts with this school name
   404→    const possibleKeys = Object.keys(teams).filter(key =>
   405→      key.startsWith(normalized + '-') ||
   406→      key === normalized
   407→    );
   408→
   409→    if (possibleKeys.length > 0) {
   410→      // Extract school part from key (e.g., "penn-state-mens" -> "penn-state")
   411→      return possibleKeys[0].replace(/-mens$/, '').replace(/-womens$/, '');
   412→    }
   413→
   414→    // Try converting spaces to dashes
   415→    const dashedName = normalized.replace(/ /g, '-');
   416→    if (aliases[dashedName]) {
   417→      return aliases[dashedName];
   418→    }
   419→
   420→    const dashedPossibleKeys = Object.keys(teams).filter(key =>
   421→      key.startsWith(dashedName + '-') ||
   422→      key === dashedName
   423→    );
   424→
   425→    if (dashedPossibleKeys.length > 0) {
   426→      return dashedPossibleKeys[0].replace(/-mens$/, '').replace(/-womens$/, '');
   427→    }
   428→
   429→    return null;
   430→  }, [teams, aliases]);
