   432→  /**
   433→   * Get team with flexible matching (handles various name formats)
   434→   * @param {string} teamName - Team name in any format (e.g., "Penn State", "California Men's")
   435→   * @param {string} gender - Optional gender: 'mens' or 'womens'
   436→   */
   437→  const getTeamFlexible = useCallback((teamName, gender = null) => {
   438→    if (!teamName) return null;
   439→
   440→    // First try exact match
   441→    const exactMatch = getTeam(teamName);
   442→    if (exactMatch) return exactMatch;
   443→
   444→    // Resolve to school key
   445→    const schoolKey = resolveSchoolKey(teamName);
   446→    if (!schoolKey) return null;
   447→
   448→    // Determine gender from input
   449→    const normalized = normalizeName(teamName);
   450→    let targetGender = gender;
   451→    if (!targetGender) {
   452→      if (normalized.includes('women') || normalized.includes('womens')) {
   453→        targetGender = 'womens';
   454→      } else if (normalized.includes('men') || normalized.includes('mens')) {
   455→        targetGender = 'mens';
   456→      }
   457→    }
   458→
   459→    // Try to get team with specific gender
   460→    if (targetGender) {
   461→      const teamWithGender = teams[`${schoolKey}-${targetGender}`];
   462→      if (teamWithGender) return teamWithGender;
   463→    }
   464→
   465→    // Try mens first, then womens
   466→    if (teams[`${schoolKey}-mens`]) return teams[`${schoolKey}-mens`];
   467→    if (teams[`${schoolKey}-womens`]) return teams[`${schoolKey}-womens`];
   468→
   469→    return null;
   470→  }, [teams, getTeam, resolveSchoolKey]);
