   565→  // ============================================
   566→  // DIAGNOSTICS
   567→  // ============================================
   568→
   569→  /**
   570→   * Run data integrity diagnostics
   571→   * Checks for common issues like orphaned headshots, missing data, etc.
   572→   * @returns {Object} Diagnostic results with issues found
   573→   */
   574→  const runDiagnostics = useCallback(() => {
   575→    const issues = [];
   576→    const stats = {
   577→      totalTeams: Object.keys(teams).length,
   578→      totalHeadshots: Object.keys(headshots).length,
   579→      teamsWithRosters: 0,
   580→      teamsWithLogos: 0,
   581→      totalRosterEntries: 0,
   582→      headshotsMatched: 0,
   583→      headshotsOrphaned: 0,
   584→    };
   585→
   586→    // Check each team
   587→    for (const [teamKey, team] of Object.entries(teams)) {
   588→      if (team.logo) stats.teamsWithLogos++;
   589→      if (team.roster?.length > 0) {
   590→        stats.teamsWithRosters++;
   591→        stats.totalRosterEntries += team.roster.length;
   592→
   593→        // Check each roster entry for headshot
   594→        for (const name of team.roster) {
   595→          const headshotUrl = getHeadshot(name);
   596→          if (!headshotUrl) {
   597→            issues.push({
   598→              type: 'missing_headshot',
   599→              severity: 'warning',
   600→              teamKey,
   601→              athleteName: name,
   602→              message: `No headshot found for "${name}" on ${team.displayName || teamKey}`,
   603→            });
   604→          } else {
   605→            stats.headshotsMatched++;
   606→          }
   607→        }
   608→      }
   609→
   610→      // Check for missing required fields
   611→      if (!team.displayName) {
   612→        issues.push({
   613→          type: 'missing_field',
   614→          severity: 'error',
   615→          teamKey,
   616→          field: 'displayName',
   617→          message: `Team "${teamKey}" is missing displayName`,
   618→        });
   619→      }
   620→      if (!team.school) {
   621→        issues.push({
   622→          type: 'missing_field',
   623→          severity: 'error',
   624→          teamKey,
   625→          field: 'school',
   626→          message: `Team "${teamKey}" is missing school name`,
   627→        });
   628→      }
   629→      if (!team.gender) {
   630→        issues.push({
   631→          type: 'missing_field',
   632→          severity: 'error',
   633→          teamKey,
   634→          field: 'gender',
   635→          message: `Team "${teamKey}" is missing gender`,
   636→        });
   637→      }
   638→    }
   639→
   640→    // Check for headshots with invalid teamKey references
   641→    for (const [key, headshot] of Object.entries(headshots)) {
   642→      if (headshot.teamKey && !teams[headshot.teamKey]) {
   643→        issues.push({
   644→          type: 'orphaned_headshot',
   645→          severity: 'warning',
   646→          headshotKey: key,
   647→          athleteName: headshot.name,
   648→          referencedTeam: headshot.teamKey,
   649→          message: `Headshot for "${headshot.name}" references non-existent team "${headshot.teamKey}"`,
   650→        });
   651→        stats.headshotsOrphaned++;
   652→      }
   653→    }
   654→
   655→    // Calculate unmatched headshots (headshots not in any roster)
   656→    const rosterNames = new Set();
   657→    for (const team of Object.values(teams)) {
   658→      if (team.roster) {
   659→        for (const name of team.roster) {
   660→          const normalized = normalizeName(name);
   661→          const safeKey = getSafeFirebaseKey(normalized);
   662→          rosterNames.add(normalized);
   663→          rosterNames.add(safeKey);
   664→        }
   665→      }
   666→    }
   667→
   668→    return {
   669→      stats,
   670→      issues,
   671→      summary: {
   672→        totalIssues: issues.length,
   673→        errors: issues.filter(i => i.severity === 'error').length,
   674→        warnings: issues.filter(i => i.severity === 'warning').length,
   675→        missingHeadshots: issues.filter(i => i.type === 'missing_headshot').length,
   676→        orphanedHeadshots: issues.filter(i => i.type === 'orphaned_headshot').length,
