  });

  return () => {
    unsubTeams();
    unsubHeadshots();
    unsubAliases();
  };
}, []);
```

#### **useAlerts.js** (Lines 37-76)
```javascript
useEffect(() => {
  const competitionId = isLocalMode ? 'local' : compId;

  if (!competitionId) {
    setLoading(false);
    return;
  }

  const alertsRef = ref(db, `alerts/${competitionId}`);

  const unsubscribe = onValue(
    alertsRef,
    (snapshot) => {
      const data = snapshot.val() || {};
      const alertArray = Object.values(data)
        .filter(alert => alert && !alert.resolved)
        .sort((a, b) => { /* sort logic */ });

      setAlerts(alertArray);
      setLoading(false);
      setError(null);
    },
    (err) => {
      console.error('[useAlerts] Firebase error:', err);
      setError(err.message);
      setLoading(false);
    }
  );

  return () => unsubscribe();
}, [compId, isLocalMode]);
```

---

## Key Pattern Takeaways

### **Socket Listeners:**
1. Get `socket` from `useShow()`
2. Define handler functions **inside** the `useEffect`
3. Register with `socket.on(eventName, handler)`
4. **MUST** cleanup with `socket.off(eventName, handler)` using the **same function reference**
5. Dependency: `[socket]`

### **Firebase Listeners:**
1. Import `{ db, ref, onValue }` from `'../lib/firebase'`
2. Create ref: `const myRef = ref(db, 'path/to/data')`
3. Subscribe: `const unsub = onValue(myRef, callback, errorCallback)`
4. **MUST** cleanup by calling `unsub()` in the return function
5. Typical dependencies: `[compId]`, `[teamKey]`, or `[]` for global data

### **Common Pattern:**
```javascript
useEffect(() => {
  if (!requiredDependency) return; // Early exit if deps not ready

  // Create listeners
  const cleanup1 = setupListener1();
  const cleanup2 = setupListener2();

  // Cleanup on unmount
  return () => {
    cleanup1();
    cleanup2();
  };
}, [dependencies]);
```

