  if (!schoolName) return '';
  const normalized = schoolName
    .toLowerCase()
    .replace(/['']/g, '')
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/-mens$/, '')
    .replace(/-womens$/, '')
    .replace(/ mens$/, '')
    .replace(/ womens$/, '')
    .replace(/ men$/, '')
    .replace(/ women$/, '')
    .replace(/\s+/g, '-')
    .trim();
