  if (!socket || !compId) return;
  setAIContextState(prev => ({ ...prev, isLoading: true, error: null }));
  socket.emit('getAIContext', { compId });  // EMIT EVENT
}, [socket, compId]);

const refresh = useCallback(() => {
  if (!socket || !compId) return;
  setAIContextState(prev => ({ ...prev, isLoading: true, error: null }));
  socket.emit('refreshAIContext', { compId });  // EMIT EVENT
}, [socket, compId]);
```

