  if (!socket || !compId) return;
  socket.emit('refreshRtnStats', { compId, teamKey: teamKey || undefined });  // EMIT EVENT
  setProgress({ status: 'starting' });
}, [socket, compId]);
```

---

### 4. The useShow Hook - How to Access ShowContext

**File:** `/Users/juliacosmiano/code/gymnastics-graphics/show-controller/src/context/ShowContext.jsx` (Lines 696-702)

```javascript
export function useShow() {
  const context = useContext(ShowContext);
  if (!context) {
    throw new Error('useShow must be used within a ShowProvider');
  }
  return context;
}
```

---

## Socket Access Pattern Summary

### Key Pattern Steps:

1. **Import and use the hook:**
   ```javascript
   import { useShow } from '../context/ShowContext';
   ```

2. **Get socket reference:**
   ```javascript
   const { socket, compId } = useShow();
   ```

3. **Listen for events (in useEffect):**
   ```javascript
   useEffect(() => {
     if (!socket) return;

     socket.on('eventName', handleFunction);

     return () => {
       socket.off('eventName', handleFunction);
     };
   }, [socket]);
   ```

4. **Emit events (in callbacks):**
   ```javascript
   socket.emit('eventName', { compId, data });
   ```

5. **Handle socket dependency in callbacks:**
   ```javascript
   useCallback(() => {
     if (!socket || !compId) return;
     socket.emit('eventName', { compId, data });
   }, [socket, compId]);
   ```

### Critical Points:

- Always check `if (!socket)` before using it
- Always include `socket` in dependency arrays
- Always clean up listeners with `socket.off()` in useEffect cleanup
- The `compId` is typically passed along with emit payloads
- ShowContext provides the socket directly as `socket` (not a method)

