     1→import { createContext, useContext, useEffect, useState, useCallback, useRef } from 'react';
     2→import { io } from 'socket.io-client';
     3→import { useCompetition } from './CompetitionContext';
     4→import { db, ref, set } from '../lib/firebase';
     5→
     6→const ShowContext = createContext(null);
     7→
     8→// Initial state values for resetting on connection changes
     9→const INITIAL_STATE = {
    10→  currentSegmentIndex: 0,
    11→  currentSegment: null,
    12→  nextSegment: null,
    13→  isPlaying: false,
    14→  isPaused: false,
    15→  talentLocked: false,
    16→  obsConnected: false,
    17→  obsCurrentScene: null,
    18→  obsIsStreaming: false,
    19→  obsIsRecording: false,
    20→  connectedClients: [],
    21→  showProgress: { completed: 0, total: 0 },
    22→  showConfig: null
    23→};
    24→
    25→const INITIAL_TIMESHEET_STATE = {
    26→  state: 'stopped',
    27→  isRunning: false,
    28→  isPaused: false,
    29→  currentSegmentIndex: -1,
    30→  currentSegment: null,
    31→  nextSegment: null,
    32→  segmentElapsedMs: 0,
    33→  segmentRemainingMs: 0,
    34→  segmentProgress: 0,
    35→  showElapsedMs: 0,
    36→  isHoldSegment: false,
    37→  canAdvanceHold: false,
    38→  holdRemainingMs: 0,
    39→  segments: [],
    40→  rundownLoaded: false,
    41→  isRehearsalMode: false,
    42→  rundownModified: false,
    43→  rundownModifiedSummary: null
    44→};
    45→
    46→export function ShowProvider({ children }) {
    47→  // Get socket URL and competition info from CompetitionContext
    48→  const { socketUrl, compId, competitionConfig } = useCompetition();
    49→
    50→  const [socket, setSocket] = useState(null);
    51→  const [connected, setConnected] = useState(false);
    52→  const [clientId, setClientId] = useState(null);
    53→  const [state, setState] = useState(INITIAL_STATE);
    54→  const [elapsed, setElapsed] = useState(0);
    55→  const [error, setError] = useState(null);
    56→
    57→  // Camera state
    58→  const [cameraHealth, setCameraHealth] = useState([]);
    59→  const [cameraRuntimeState, setCameraRuntimeState] = useState([]);
    60→  const [activeFallbacks, setActiveFallbacks] = useState([]);
    61→
    62→  // Timesheet state
    63→  const [timesheetState, setTimesheetState] = useState(INITIAL_TIMESHEET_STATE);
    64→  const [overrideLog, setOverrideLog] = useState([]);
    65→
    66→  // Ref to always have access to latest competitionConfig in socket handlers
    67→  const competitionConfigRef = useRef(competitionConfig);
    68→  useEffect(() => {
    69→    competitionConfigRef.current = competitionConfig;
    70→  }, [competitionConfig]);
    71→
    72→  useEffect(() => {
    73→    // Don't connect if no socket URL is available
    74→    if (!socketUrl) {
    75→      console.log('ShowContext: No socket URL available, skipping connection');
    76→      return;
    77→    }
    78→
    79→    console.log(`ShowContext: Connecting to ${socketUrl} for competition ${compId}`);
    80→
    81→    // Clear all state when connection changes
    82→    setState(INITIAL_STATE);
    83→    setElapsed(0);
    84→    setError(null);
    85→    setCameraHealth([]);
    86→    setCameraRuntimeState([]);
    87→    setActiveFallbacks([]);
    88→    setTimesheetState(INITIAL_TIMESHEET_STATE);
    89→    setOverrideLog([]);
    90→
    91→    const newSocket = io(socketUrl, {
    92→      transports: ['websocket', 'polling'],
    93→      query: { compId }  // Include competition ID for server to route to correct VM
    94→    });
    95→
    96→    newSocket.on('connect', () => {
    97→      console.log(`ShowContext: Connected to ${socketUrl} for ${compId}`);
    98→      setConnected(true);
    99→    });
   100→
   101→    newSocket.on('connected', ({ clientId, state }) => {
   102→      setClientId(clientId);
   103→      setState(state);
   104→    });
   105→
   106→    newSocket.on('stateUpdate', (newState) => {
   107→      setState(newState);
   108→    });
   109→
   110→    newSocket.on('timeUpdate', ({ elapsed }) => {
   111→      setElapsed(elapsed);
   112→    });
   113→
   114→    newSocket.on('sceneChanged', (sceneName) => {
   115→      setState(prev => ({ ...prev, obsCurrentScene: sceneName }));
   116→    });
   117→
   118→    // Also listen for new event format from obsStateSync
   119→    newSocket.on('obs:currentSceneChanged', (data) => {
   120→      const sceneName = data?.sceneName || data;
   121→      setState(prev => ({ ...prev, obsCurrentScene: sceneName }));
   122→    });
   123→
   124→    // Listen for OBS connection status from obsConnectionManager
   125→    newSocket.on('obs:connected', (data) => {
   126→      console.log('ShowContext: OBS connected', data);
   127→      setState(prev => ({ ...prev, obsConnected: true }));
   128→      // Force a full state refresh to get fresh scene list
   129→      newSocket.emit('obs:refreshState');
   130→    });
   131→
   132→    newSocket.on('obs:disconnected', (data) => {
   133→      console.log('ShowContext: OBS disconnected', data);
   134→      setState(prev => ({ ...prev, obsConnected: false }));
   135→    });
   136→
   137→    // Also extract connection status from obs:stateUpdated (sent on initial connection)
   138→    newSocket.on('obs:stateUpdated', (data) => {
   139→      console.log('ShowContext: OBS state updated', data);
   140→      if (data?.connected !== undefined) {
   141→        setState(prev => ({ ...prev, obsConnected: data.connected }));
   142→      }
   143→      if (data?.currentScene) {
   144→        setState(prev => ({ ...prev, obsCurrentScene: data.currentScene }));
   145→      }
   146→    });
   147→
   148→    newSocket.on('error', ({ message }) => {
   149→      setError(message);
   150→      setTimeout(() => setError(null), 3000);
   151→    });
   152→
   153→    newSocket.on('disconnect', () => {
   154→      console.log(`ShowContext: Disconnected from ${socketUrl}`);
   155→      setConnected(false);
   156→    });
   157→
   158→    // Camera health events
   159→    newSocket.on('cameraHealth', (health) => {
   160→      console.log('Camera health update:', health);
   161→      setCameraHealth(health);
   162→    });
   163→
   164→    // Camera runtime state events
   165→    newSocket.on('cameraRuntimeState', (runtimeState) => {
   166→      console.log('Camera runtime state update:', runtimeState);
   167→      setCameraRuntimeState(runtimeState);
   168→    });
   169→
   170→    // Camera status changed event (individual camera transitions)
   171→    newSocket.on('cameraStatusChanged', ({ cameraId, previousStatus, currentStatus, health }) => {
   172→      console.log(`Camera ${cameraId} status changed: ${previousStatus} -> ${currentStatus}`);
   173→      // Update the specific camera in cameraHealth array
   174→      setCameraHealth(prev => prev.map(cam =>
   175→        cam.cameraId === cameraId ? { ...cam, status: currentStatus, ...health } : cam
   176→      ));
   177→    });
   178→
   179→    // Fallback events
   180→    newSocket.on('activeFallbacks', (fallbacks) => {
   181→      console.log('Active fallbacks:', fallbacks);
   182→      setActiveFallbacks(fallbacks);
   183→    });
   184→
   185→    newSocket.on('fallbackActivated', ({ originalCameraId, fallbackCameraId, reason }) => {
   186→      console.log(`Fallback activated: ${originalCameraId} -> ${fallbackCameraId} (${reason})`);
   187→      setActiveFallbacks(prev => [
   188→        ...prev.filter(f => f.originalCameraId !== originalCameraId),
   189→        { originalCameraId, fallbackCameraId, reason, activatedAt: Date.now() }
   190→      ]);
   191→    });
   192→
   193→    newSocket.on('fallbackCleared', ({ cameraId }) => {
   194→      console.log(`Fallback cleared for camera: ${cameraId}`);
   195→      setActiveFallbacks(prev => prev.filter(f => f.originalCameraId !== cameraId));
   196→    });
   197→
   198→    newSocket.on('fallbackUnavailable', ({ cameraId, reason }) => {
   199→      console.log(`No fallback available for camera ${cameraId}: ${reason}`);
