          {/* Roster status */}
          {hasRoster && rosterStats && (
            <span className="flex items-center gap-1 text-xs text-green-400">
              <CheckCircleIcon className="w-3 h-3" /> {rosterStats.total} athletes ({rosterStats.withHeadshots} photos)
