                      className="px-3 py-2.5 bg-zinc-800 border border-zinc-700 text-zinc-300 text-sm rounded-lg hover:bg-zinc-700 transition-colors"
                    >
                      Duplicate
                    </button>
                    <button
                      onClick={() => handleDeleteFromCard(compId)}
                      className="px-3 py-2.5 bg-zinc-800 border border-zinc-700 text-red-400 text-sm rounded-lg hover:bg-zinc-700 transition-colors"
                    >
                      Delete
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Modal */}
      {showModal && (
        <div
          className="fixed inset-0 bg-black/80 flex items-center justify-center z-50"
          onClick={() => setShowModal(false)}
        >
          <div
            className="bg-zinc-900 border border-zinc-800 rounded-xl p-8 w-full max-w-lg max-h-[90vh] overflow-y-auto"
            onClick={(e) => e.stopPropagation()}
          >
            <h2 className="text-xl font-bold text-white mb-2">
              {editingCompId ? 'Edit Competition' : 'Create Competition'}
            </h2>
            <p className="text-sm text-zinc-500 mb-6">Configure competition details</p>

            <form onSubmit={handleSubmit}>
              {/* Virtius Import Section */}
              <div className="mb-6 p-4 bg-zinc-800/50 border border-zinc-700 rounded-lg">
                <div className="text-xs text-zinc-400 mb-2">Import from Virtius (optional)</div>
                <div className="flex gap-2">
                  <input
                    type="text"
                    value={virtiusSessionId}
                    onChange={(e) => setVirtiusSessionId(e.target.value)}
                    placeholder="Session ID, e.g., EeUcxrjyBD"
                    className="flex-1 px-3 py-2 bg-zinc-800 border border-zinc-700 rounded-lg text-white text-sm focus:outline-none focus:border-blue-500"
                  />
                  <button
                    type="button"
                    onClick={fetchFromVirtius}
                    disabled={virtiusFetching || !virtiusSessionId.trim()}
                    className="px-4 py-2 bg-blue-600 hover:bg-blue-500 disabled:bg-zinc-700 disabled:text-zinc-500 text-white text-sm font-medium rounded-lg transition-colors"
                  >
                    {virtiusFetching ? 'Fetching...' : 'Fetch'}
                  </button>
                </div>
                {virtiusError && (
                  <div className="mt-2 text-xs text-red-400">{virtiusError}</div>
                )}
              </div>

              <FormGroup label="Competition ID (no spaces, lowercase)">
                <input
                  type="text"
                  value={formData.compId}
                  onChange={(e) => setFormData({ ...formData, compId: e.target.value })}
                  disabled={!!editingCompId}
                  placeholder="e.g., court1, meet-a, ncaa-finals"
                  pattern="[a-z0-9-]+"
                  required
                  className="w-full px-3 py-2.5 bg-zinc-800 border border-zinc-700 rounded-lg text-white text-sm focus:outline-none focus:border-blue-500 disabled:opacity-50"
                />
              </FormGroup>

              <div className="grid grid-cols-2 gap-3">
                <FormGroup label="Competition Type">
                  <select
                    value={formData.compType}
                    onChange={(e) => {
                      const newCompType = e.target.value;
                      // Auto-set gender based on competition type selection
                      const inferredGender = getGenderFromCompType(newCompType);
                      setFormData({ ...formData, compType: newCompType, gender: inferredGender || formData.gender });
                    }}
                    required
                    className="w-full px-3 py-2.5 bg-zinc-800 border border-zinc-700 rounded-lg text-white text-sm focus:outline-none focus:border-blue-500"
                  >
                    <option value="">Select type...</option>
                    {competitionTypes.map((type) => (
                      <option key={type.value} value={type.value}>{type.label}</option>
                    ))}
                  </select>
                </FormGroup>

                <FormGroup label="Gender (for team lookups)">
                  <select
                    value={formData.gender}
                    onChange={(e) => setFormData({ ...formData, gender: e.target.value })}
                    required
                    className="w-full px-3 py-2.5 bg-zinc-800 border border-zinc-700 rounded-lg text-white text-sm focus:outline-none focus:border-blue-500"
                  >
                    <option value="">Select gender...</option>
                    <option value="womens">Women's</option>
                    <option value="mens">Men's</option>
                  </select>
                </FormGroup>
              </div>

              <FormGroup label="Event Name">
                <input
                  type="text"
                  value={formData.eventName}
                  onChange={(e) => setFormData({ ...formData, eventName: e.target.value })}
                  placeholder="e.g., Big Ten Dual Meet"
                  required
                  className="w-full px-3 py-2.5 bg-zinc-800 border border-zinc-700 rounded-lg text-white text-sm focus:outline-none focus:border-blue-500"
                />
              </FormGroup>

              <FormGroup label="Meet Date">
                <input
                  type="text"
                  value={formData.meetDate}
                  onChange={(e) => setFormData({ ...formData, meetDate: e.target.value })}
                  placeholder="e.g., January 15, 2025"
                  required
                  className="w-full px-3 py-2.5 bg-zinc-800 border border-zinc-700 rounded-lg text-white text-sm focus:outline-none focus:border-blue-500"
                />
              </FormGroup>

              <div className="grid grid-cols-2 gap-3">
                <FormGroup label="Venue">
                  <input
                    type="text"
                    value={formData.venue}
                    onChange={(e) => setFormData({ ...formData, venue: e.target.value })}
                    placeholder="e.g., Crisler Center"
                    required
                    className="w-full px-3 py-2.5 bg-zinc-800 border border-zinc-700 rounded-lg text-white text-sm focus:outline-none focus:border-blue-500"
                  />
                </FormGroup>
                <FormGroup label="Location">
                  <input
                    type="text"
                    value={formData.location}
                    onChange={(e) => setFormData({ ...formData, location: e.target.value })}
                    placeholder="e.g., Ann Arbor, MI"
                    required
                    className="w-full px-3 py-2.5 bg-zinc-800 border border-zinc-700 rounded-lg text-white text-sm focus:outline-none focus:border-blue-500"
                  />
                </FormGroup>
              </div>

              <TeamLogoInput
                teamNum={1}
                teamName={formData.team1Name}
                teamLogo={formData.team1Logo}
                onNameChange={(val) => setFormData({ ...formData, team1Name: val })}
                onLogoChange={(val) => setFormData({ ...formData, team1Logo: val })}
                gender={formData.gender}
                required
              />

              <TeamLogoInput
                teamNum={2}
                teamName={formData.team2Name}
                teamLogo={formData.team2Logo}
                onNameChange={(val) => setFormData({ ...formData, team2Name: val })}
                onLogoChange={(val) => setFormData({ ...formData, team2Logo: val })}
                gender={formData.gender}
                required
              />

              {teamCount >= 3 && (
                <TeamLogoInput
                  teamNum={3}
                  teamName={formData.team3Name}
                  teamLogo={formData.team3Logo}
                  onNameChange={(val) => setFormData({ ...formData, team3Name: val })}
                  onLogoChange={(val) => setFormData({ ...formData, team3Logo: val })}
                  gender={formData.gender}
                  required
                />
              )}

              {teamCount >= 4 && (
                <TeamLogoInput
                  teamNum={4}
                  teamName={formData.team4Name}
                  teamLogo={formData.team4Logo}
                  onNameChange={(val) => setFormData({ ...formData, team4Name: val })}
                  onLogoChange={(val) => setFormData({ ...formData, team4Logo: val })}
                  gender={formData.gender}
                  required
                />
              )}

              {teamCount >= 5 && (
                <TeamLogoInput
                  teamNum={5}
                  teamName={formData.team5Name}
                  teamLogo={formData.team5Logo}
                  onNameChange={(val) => setFormData({ ...formData, team5Name: val })}
                  onLogoChange={(val) => setFormData({ ...formData, team5Logo: val })}
                  gender={formData.gender}
                  required
                />
              )}

              {teamCount >= 6 && (
                <TeamLogoInput
                  teamNum={6}
                  teamName={formData.team6Name}
                  teamLogo={formData.team6Logo}
                  onNameChange={(val) => setFormData({ ...formData, team6Name: val })}
                  onLogoChange={(val) => setFormData({ ...formData, team6Logo: val })}
                  gender={formData.gender}
                  required
                />
              )}

              {/* Refresh Team Data button - only show when editing */}
              {editingCompId && (
                <div className="mb-4 p-4 bg-zinc-800/50 border border-zinc-700 rounded-lg">
                  <div className="text-xs text-zinc-400 mb-2">Sync Headshots from Media Manager</div>
                  <p className="text-xs text-zinc-500 mb-3">
                    Re-fetch rosters from RTN and merge latest headshots from Firebase. Use this after adding new headshots in Media Manager.
                  </p>
                  <button
                    type="button"
                    onClick={handleRefreshTeamData}
                    disabled={refreshing}
                    className="px-4 py-2 bg-green-600 hover:bg-green-500 disabled:bg-zinc-700 disabled:text-zinc-500 text-white text-sm font-medium rounded-lg transition-colors"
                  >
                    {refreshing ? 'Refreshing...' : 'Refresh Team Data'}
                  </button>
                </div>
              )}

              <div className="flex gap-3 mt-6">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 px-4 py-2.5 bg-zinc-800 text-zinc-300 rounded-lg hover:bg-zinc-700 transition-colors"
                >
                  Cancel
                </button>
                {editingCompId && (
                  <button
                    type="button"
                    onClick={handleDelete}
                    className="px-4 py-2.5 bg-red-600 text-white rounded-lg hover:bg-red-500 transition-colors"
                  >
                    Delete
                  </button>
                )}
                <button
                  type="submit"
                  className="flex-1 px-4 py-2.5 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-500 transition-colors"
                >
                  Save Competition
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

function FormGroup({ label, children }) {
  return (
    <div className="mb-4">
      <label className="block text-xs text-zinc-400 mb-1.5">{label}</label>
      {children}
    </div>
  );
}

function TeamLogoInput({ teamNum, teamName, teamLogo, onNameChange, onLogoChange, required, gender }) {
  // Use explicit gender prop (passed from form's gender field)
  const effectiveGender = gender || 'mens';

  // Use Firebase teamsDatabase for roster data (with flexible name matching)
  const { hasTeamRoster, getTeamRosterStatsFlexible, getTeamLogo } = useTeamsDatabase();

  const hasLogoFromFirebase = teamName && getTeamLogo(teamName, effectiveGender);
  const hasLogoUrl = !!teamLogo;
  const logoStatus = hasLogoUrl ? 'has-url' : hasLogoFromFirebase ? 'in-library' : teamName ? 'missing' : 'no-name';

  // Use flexible matching to find roster (handles "Penn State", "penn-state-mens", etc.)
  const hasRoster = teamName && hasTeamRoster(teamName, effectiveGender);
  const rosterStats = teamName ? getTeamRosterStatsFlexible(teamName, effectiveGender) : null;

  // Fetch head coach from Road to Nationals using explicit gender
  const { coach, loading: coachLoading } = useHeadCoach(teamName, effectiveGender);

  // Build the team key that will be used
  const teamKey = teamName ? buildTeamKey(teamName, effectiveGender) : null;

  return (
    <div className="mb-4 p-3 bg-zinc-800/30 rounded-lg border border-zinc-800">
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
          <span className="text-xs text-zinc-400">Team {teamNum}</span>
          {/* Gender indicator badge */}
          {effectiveGender && (
            <span className={`px-1.5 py-0.5 rounded text-[10px] font-medium ${
              effectiveGender === 'womens'
                ? 'bg-pink-500/20 text-pink-400 border border-pink-500/30'
                : 'bg-blue-500/20 text-blue-400 border border-blue-500/30'
            }`}>
              {effectiveGender === 'womens' ? "W" : "M"}
            </span>
          )}
        </div>
        <div className="flex items-center gap-3">
          {/* Logo status */}
          {logoStatus === 'has-url' && (
            <span className="flex items-center gap-1 text-xs text-green-400">
              <CheckCircleIcon className="w-3 h-3" /> Logo set
            </span>
          )}
          {logoStatus === 'in-library' && (
            <span className="flex items-center gap-1 text-xs text-blue-400">
              <CheckCircleIcon className="w-3 h-3" /> In library
            </span>
          )}
          {logoStatus === 'missing' && (
            <Link
              to="/media-manager"
              className="flex items-center gap-1 text-xs text-amber-400 hover:text-amber-300"
            >
              <ExclamationTriangleIcon className="w-3 h-3" /> Add logo
            </Link>
          )}
          {/* Roster status */}
          {hasRoster && rosterStats && (
            <span className="flex items-center gap-1 text-xs text-green-400">
              <CheckCircleIcon className="w-3 h-3" /> {rosterStats.total} athletes ({rosterStats.withHeadshots} photos)
            </span>
          )}
          {teamName && !hasRoster && (
            <Link
              to="/media-manager"
              className="flex items-center gap-1 text-xs text-amber-400 hover:text-amber-300"
            >
              <ExclamationTriangleIcon className="w-3 h-3" /> No roster
            </Link>
          )}
        </div>
      </div>
      <div className="flex gap-2">
        {/* Logo preview - use explicit gender for lookup */}
        <div className="w-12 h-12 bg-zinc-700 rounded-lg flex items-center justify-center overflow-hidden flex-shrink-0">
          {(teamLogo || (teamName && getTeamLogo(teamName, effectiveGender))) ? (
            <img
              src={teamLogo || getTeamLogo(teamName, effectiveGender)}
              alt={teamName || 'Team logo'}
              className="w-10 h-10 object-contain"
            />
          ) : (
            <span className="text-zinc-500 text-lg">?</span>
          )}
        </div>
        <div className="flex-1 space-y-2">
          <input
            type="text"
            value={teamName}
            onChange={(e) => onNameChange(e.target.value)}
            placeholder={`Team ${teamNum} name`}
            required={required}
            className="w-full px-3 py-2 bg-zinc-800 border border-zinc-700 rounded-lg text-white text-sm focus:outline-none focus:border-blue-500"
          />
          <input
            type="text"
            value={teamLogo}
            onChange={(e) => onLogoChange(e.target.value)}
            placeholder="Logo URL (auto-filled if in library)"
            className="w-full px-3 py-1.5 bg-zinc-800 border border-zinc-700 rounded text-white text-xs focus:outline-none focus:border-blue-500"
          />
          {/* Head Coach from Road to Nationals */}
          {teamName && (
            <div className="flex items-center gap-1.5 text-xs text-zinc-400">
              <UserIcon className="w-3 h-3" />
              {coachLoading ? (
                <span className="text-zinc-500">Loading coach...</span>
              ) : coach ? (
                <span className="text-zinc-300">HC: {coach.fullName}</span>
              ) : (
                <span className="text-zinc-500">Coach not found in RTN</span>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

const STALENESS_TTL = 24 * 60 * 60 * 1000; // 24 hours

/**
 * StatsStatusBadge - Shows RTN stats status for a competition card.
 * Reads directly from Firebase (no ShowContext needed).
 * Includes a Refresh Stats button that uses a temporary socket connection.
 */
function StatsStatusBadge({ compId, config }) {
  const [teamMetas, setTeamMetas] = useState({});
  const [refreshing, setRefreshing] = useState(false);

  // Build team keys from config
  const { gender } = parseCompetitionType(config?.compType);
  const teamKeys = [];
  for (let i = 1; i <= 6; i++) {
    const teamName = config?.[`team${i}Name`];
    if (teamName) {
      const teamKey = buildTeamDbKey(teamName, gender);
      if (teamKey) teamKeys.push({ index: i, teamKey });
    }
  }

  // Subscribe to meta for each team
  useEffect(() => {
    if (!teamKeys.length) return;

    const unsubs = [];
    for (const { index, teamKey } of teamKeys) {
      const metaRef = ref(db, `teamsDatabase/stats/${teamKey}/meta`);
      const unsub = onValue(metaRef, (snapshot) => {
        setTeamMetas(prev => ({
          ...prev,
          [index]: snapshot.val() || null,
        }));
      }, () => {
        // Ignore errors silently
      });
      unsubs.push(unsub);
    }

    return () => unsubs.forEach(u => u());
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [compId, config?.compType, config?.team1Name, config?.team2Name]);

  // Determine overall status from all team metas
  const metas = Object.values(teamMetas).filter(Boolean);
  const hasAnyStats = metas.length > 0;
  const allComplete = hasAnyStats && metas.every(m => m.status === 'complete');
  const anyError = metas.some(m => m.status === 'error');
  const anyPartial = metas.some(m => m.status === 'partial');

  // Find the oldest fetchedAt across all teams
  const oldestFetchedAt = metas.reduce((oldest, m) => {
    if (!m.fetchedAt) return oldest;
    const t = new Date(m.fetchedAt).getTime();
    return oldest === null ? t : Math.min(oldest, t);
  }, null);

  const isStale = oldestFetchedAt === null || (Date.now() - oldestFetchedAt > STALENESS_TTL);

  // Format timestamp
  const formatTimestamp = (ts) => {
    if (!ts) return 'Never';
    const d = new Date(ts);
    const now = new Date();
    const diffMs = now - d;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  };

  // Refresh handler using temporary socket
  const handleRefresh = useCallback(() => {
    if (refreshing || !compId) return;
    setRefreshing(true);

    try {
      const socket = io(SERVER_URL, {
        transports: ['websocket', 'polling'],
        query: { compId },
      });

      const cleanup = () => {
        setRefreshing(false);
        try { socket.disconnect(); } catch { /* ignore */ }
      };

      socket.on('connect', () => {
        socket.emit('refreshRtnStats', { compId });
      });

      socket.on('rtnStatsResult', () => {
        cleanup();
      });

      socket.on('connect_error', () => {
        cleanup();
      });

      setTimeout(cleanup, 60000);
    } catch {
      setRefreshing(false);
    }
  }, [compId, refreshing]);

  // Determine badge color and text
  let badgeColor, badgeText;
  if (!hasAnyStats) {
    badgeColor = 'bg-zinc-700 text-zinc-400';
    badgeText = 'No stats';
  } else if (anyError) {
    badgeColor = 'bg-red-500/20 text-red-400 border border-red-500/30';
    badgeText = 'Stats error';
  } else if (anyPartial) {
    badgeColor = 'bg-yellow-500/20 text-yellow-400 border border-yellow-500/30';
    badgeText = 'Partial';
  } else if (allComplete) {
    badgeColor = 'bg-green-500/20 text-green-400 border border-green-500/30';
    badgeText = 'Stats loaded';
  } else {
    badgeColor = 'bg-zinc-700 text-zinc-400';
    badgeText = 'No stats';
  }

  return (
    <div className="flex items-center gap-2 flex-wrap">
      <span className={`px-2 py-0.5 rounded text-[10px] font-medium ${badgeColor}`}>
        {badgeText}
      </span>
      {hasAnyStats && (
        <span className="text-[10px] text-zinc-500">
          {formatTimestamp(oldestFetchedAt)}
        </span>
      )}
      {isStale && hasAnyStats && (
        <span className="text-[10px] text-yellow-500">Stale</span>
      )}
      <button
        onClick={(e) => { e.preventDefault(); e.stopPropagation(); handleRefresh(); }}
        disabled={refreshing}
        title="Refresh RTN Stats"
        className="p-0.5 rounded hover:bg-zinc-700 text-zinc-500 hover:text-zinc-300 disabled:opacity-50 transition-colors"
      >
        <ArrowPathIcon className={`w-3.5 h-3.5 ${refreshing ? 'animate-spin' : ''}`} />
      </button>
    </div>
  );
}

