        {/* System Administration Section */}
        <Section title="System Administration">
          <ToolCard
            to="/_admin/vm-pool"
            icon="[vm]"
            title="VM Pool"
            description="Manage EC2 instances"
          />
          <ToolCard
            to="/_admin/setup-guide"
            icon="[doc]"
            title="Setup Guide"
            description="Documentation for coordinator system"
