     1→import { useState, useEffect, useMemo } from 'react';
     2→import { Link, useNavigate } from 'react-router-dom';
     3→import { useCompetitions, checkVmStatus } from '../hooks/useCompetitions';
     4→import { useVMPool, VM_STATUS } from '../hooks/useVMPool';
     5→import { useCoordinator, COORDINATOR_STATUS } from '../hooks/useCoordinator';
     6→import CoordinatorStatus from '../components/CoordinatorStatus';
     7→import { competitionTypes, teamCounts, typeLabels } from '../lib/graphicButtons';
     8→import { useTeamsDatabase } from '../hooks/useTeamsDatabase';
     9→import { useHeadCoach } from '../hooks/useRoadToNationals';
    10→import { getGenderFromCompType, buildTeamKey } from '../lib/competitionUtils';
    11→import { ExclamationTriangleIcon, CheckCircleIcon, UserIcon } from '@heroicons/react/24/solid';
    12→import StatsStatusBadge from '../components/StatsStatusBadge';
    13→
    14→/**
    15→ * HomePage - Consolidated landing page combining:
    16→ * - CompetitionSelector: Competition list, VM assignment, coordinator status
    17→ * - HubPage: Links to all tools and overlays
