   849→// Competition Card Component
   850→function CompetitionCard({
   851→  competition,
   852→  vmStatuses,
   853→  getGenderBadge,
   854→  getTeams,
   855→  formatDisplayDate,
   856→  getVMStatusBadge,
   857→  hasVMAssigned,
   858→  availableVMs,
   859→  isCoordinatorOffline,
   860→  assigningVm,
   861→  releasingVm,
   862→  onAssignVM,
   863→  onReleaseVM,
   864→  onEdit,
   865→  onDuplicate,
   866→  onDelete,
   867→  VmStatusIndicator,
   868→  navigate
   869→}) {
   870→  const { compId, config, meetDate } = competition;
   871→  const genderBadge = getGenderBadge(config);
   872→  const teams = getTeams(config);
   873→  const vmBadge = getVMStatusBadge(compId);
   874→  const hasVM = hasVMAssigned(compId);
   875→  const isAssigning = assigningVm === compId;
   876→  const isReleasing = releasingVm === compId;
   877→  const canAssignVM = availableVMs.length > 0 && !hasVM && !isCoordinatorOffline;
   878→  const canReleaseVM = hasVM && !isCoordinatorOffline;
   879→
   880→  return (
   881→    <div className="bg-zinc-900 border-2 border-zinc-800 rounded-xl p-5 hover:border-zinc-700 transition-colors">
   882→      <div className="flex items-start justify-between mb-3">
   883→        <div className="flex items-center gap-2">
   884→          <VmStatusIndicator compId={compId} />
   885→          <span className={`px-2 py-0.5 rounded text-xs font-bold text-white ${genderBadge.color}`}>
   886→            {genderBadge.label}
   887→          </span>
   888→          {vmBadge && (
   889→            <span
   890→              className={`px-2 py-0.5 rounded text-xs font-bold text-white ${vmBadge.color} cursor-help`}
   891→              title={vmBadge.vm.publicIp ? `IP: ${vmBadge.vm.publicIp}` : 'No IP assigned'}
   892→            >
   893→              {vmBadge.label}
   894→            </span>
   895→          )}
   896→        </div>
   897→        <span className="text-xs text-zinc-500">{compId}</span>
   898→      </div>
   899→
   900→      <h3 className="text-lg font-bold text-white mb-1">
   901→        {config?.eventName || 'Untitled Competition'}
   902→      </h3>
   903→
   904→      <div className="text-sm text-zinc-400 mb-2">
   905→        {formatDisplayDate(meetDate)}
   906→        {config?.venue && <span className="text-zinc-500"> - {config.venue}</span>}
   907→      </div>
   908→
   909→      {teams.length > 0 && (
   910→        <div className="text-sm text-zinc-500 mb-2">
   911→          {teams.join(' vs ')}
   912→        </div>
   913→      )}
   914→
   915→      <div className="mb-3">
   916→        <StatsStatusBadge compId={compId} config={config} />
   917→      </div>
   918→
   919→      {vmBadge?.vm?.publicIp && (
   920→        <div className="text-xs text-zinc-500 mb-3 font-mono">
   921→          VM: {vmBadge.vm.publicIp}
   922→        </div>
   923→      )}
   924→
   925→      {/* Action buttons - always navigate, CompetitionLayout handles VM errors */}
   926→      <div className="flex gap-2 flex-wrap">
   927→        <Link
   928→          to={`/${compId}/producer`}
   929→          className="px-3 py-1.5 text-sm font-medium rounded-lg transition-colors bg-blue-600 text-white hover:bg-blue-500"
   930→        >
   931→          Producer
   932→        </Link>
   933→        <Link
   934→          to={`/${compId}/talent`}
   935→          className="px-3 py-1.5 text-sm font-medium rounded-lg transition-colors bg-zinc-800 text-zinc-300 hover:bg-zinc-700"
   936→        >
   937→          Talent
   938→        </Link>
   939→        <a
   940→          href={`/output.html?comp=${compId}`}
   941→          target="_blank"
   942→          rel="noopener noreferrer"
   943→          className="px-3 py-1.5 bg-zinc-800 text-zinc-300 text-sm font-medium rounded-lg hover:bg-zinc-700 transition-colors"
   944→        >
   945→          Graphics
   946→        </a>
