   998→              </span>
   999→            ) : (
  1000→              'Release VM'
  1001→            )}
  1002→          </button>
  1003→        )}
  1004→        <button
  1005→          onClick={() => onEdit(compId)}
  1006→          className="px-3 py-1.5 bg-zinc-800 text-zinc-300 text-sm rounded-lg hover:bg-zinc-700 transition-colors"
