  1027→// Competition Group Component
  1028→function CompetitionGroup({ title, competitions, emptyMessage, renderCard }) {
  1029→  if (competitions.length === 0) {
  1030→    if (emptyMessage) {
  1031→      return (
  1032→        <div className="mb-8">
  1033→          <h2 className="text-sm font-semibold text-zinc-400 uppercase tracking-wide mb-4 pb-2 border-b border-zinc-800">
  1034→            {title}
  1035→          </h2>
  1036→          <p className="text-zinc-600 text-sm italic">{emptyMessage}</p>
  1037→        </div>
  1038→      );
  1039→    }
  1040→    return null;
  1041→  }
  1042→
  1043→  return (
  1044→    <div className="mb-8">
  1045→      <h2 className="text-sm font-semibold text-zinc-400 uppercase tracking-wide mb-4 pb-2 border-b border-zinc-800">
  1046→        {title} ({competitions.length})
  1047→      </h2>
  1048→      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
  1049→        {competitions.map(renderCard)}
  1050→      </div>
  1051→    </div>
  1052→  );
  1053→}
