  onChange={(v) => setFormData({ ...formData, team1Coaches: v })}
  rows={3}
/>
```

**ConfigInput Component** (Lines 303-316):
```javascript
function ConfigInput({ label, value, onChange, placeholder }) {
  return (
    <div className="mb-3">
      <label className="block text-xs text-zinc-500 mb-1">{label}</label>
      <input
        type="text"
        value={value || ''}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="w-full px-2.5 py-2 bg-zinc-800 border border-zinc-700 rounded-md text-white text-sm focus:outline-none focus:border-blue-500"
      />
    </div>
  );
}
```

---

### 2. How Data is Saved to Firebase

**Current Pattern** (ControllerPage does NOT directly save config):

The ControllerPage stores form data in local state only:
- **Lines 12-36**: Initialize `formData` state from `config` (from Firebase)
- **Lines 44-57**: When sending a graphic, formData is passed as the `data` payload to `setGraphic()`
- **No direct config save**: Changes to formData are **not automatically persisted** to Firebase config

**What Actually Happens**:
```javascript
const handleSendGraphic = useCallback(async (graphicId, frameTitle = null) => {
  const data = { ...formData }; // Current form state
  if (frameTitle) {
    data.frameTitle = frameTitle;
  }

  await setGraphic(graphicType, data); // Sends to currentGraphic, NOT config
  showToast(`Showing: ${graphicNames[graphicId] || graphicId}`);
}, [formData, setGraphic, showToast]);
```

This means:
- Editing fields in ControllerPage updates local state
- Clicking a graphic button sends those values to `currentGraphic` (used by output.html)
- The values are **NOT saved back to the competition config** in Firebase

---

### 3. Where Config IS Saved to Firebase

**DashboardPage.jsx** and **HomePage.jsx** both save config:
- **File**: `/Users/juliacosmiano/code/gymnastics-graphics/show-controller/src/pages/DashboardPage.jsx`
- **Lines 227-250**: Default values set when creating/editing competition

```javascript
// Lines 227-250 - Defaults set in handleSubmit
const config = {
  compType: formData.compType,
  gender: gender,
  // ... other fields ...
  hosts: 'Host Name',
  team1Ave: '0.000',
  team1High: '0.000',
  team1Con: '0%',
  team1Coaches: 'Coach Name',
  team2Ave: '0.000',
  team2High: '0.000',
  team2Con: '0%',
  team2Coaches: 'Coach Name',
  // ... team3-6 ...
};

if (editingCompId) {
  await updateCompetition(editingCompId, config); // Saves to Firebase
} else {
  await createCompetition(compId, config); // Saves to Firebase
}
```

**Note**: DashboardPage and HomePage modals do NOT have UI fields for Ave/High/Con/Coaches. They only set default values.

---

### 4. Firebase Update Pattern

**Hook**: `/Users/juliacosmiano/code/gymnastics-graphics/show-controller/src/hooks/useCompetitions.js`
- **Lines 714-722**: `updateConfig` function

```javascript
const updateConfig = useCallback(async (updates) => {
  if (!compId) return { success: false, error: 'No competition ID' };
  try {
    await update(ref(db, `competitions/${compId}/config`), updates);
    return { success: true };
  } catch (err) {
    return { success: false, error: err.message };
  }
}, [compId]);
```

**Usage Pattern**:
- Call `updateConfig({ team1Ave: '406.850', team1High: '409.200' })` to save changes
- Uses Firebase's `update()` method (merges, doesn't overwrite entire config)

---

### 5. Lock Fields Search Results

**No "_locks" UI found**: The search for "_locks" returned no results, meaning there's currently no lock UI implemented.

---

### 6. Current UI Pattern Summary

**Editable Fields Location**:
- **ControllerPage.jsx** (lines 100-217): Left sidebar config panel
  - Event Info section (eventName, meetDate, venue, location, hosts)
  - Team 1 section (name, logo, ave, high, con, coaches)
  - Team 2 section (name, logo, ave, high, con, coaches)

**Data Flow**:
1. User types in ConfigInput → updates `formData` state (local only)
2. User clicks graphic button → sends `formData` to `currentGraphic` in Firebase
3. Config changes are **NOT automatically persisted** to `config` in Firebase
4. To persist config, need to call `updateConfig(updates)` from `useCompetition` hook

**Visual Pattern**:
- Three stats fields (Ave/High/Con) displayed side-by-side in a flex row
- Coaches field as a textarea below them
- Dark theme with zinc-800 backgrounds, zinc-700 borders
- Blue focus states (border-blue-500)

---

