     2→import { db, ref, onValue, set, update, remove, get } from '../lib/firebase';
     3→import { getTeamDashboard } from '../lib/roadToNationals';
     4→import { normalizeName, getLookupKeys } from '../lib/nameNormalization';
     5→import { buildTeamKey } from '../lib/competitionUtils';
     6→import { io } from 'socket.io-client';
     7→import { SERVER_URL } from '../lib/serverUrl';
