        </div>

        {/* Control Area */}
        <div className="flex-1 p-6 overflow-y-auto">
          <ButtonSection title="Pre-Meet Graphics">
            {graphicButtons.preMeet.map((btn) => (
              <GraphicButton
                key={btn.id}
