// Fields that can be locked to prevent auto-sync from RTN stats
const LOCKABLE_FIELDS = [
  'team1Ave', 'team1High', 'team1Con', 'team1Coaches',
  'team2Ave', 'team2High', 'team2Con', 'team2Coaches',
];

