    32→  }, [updateConfig]);
    33→
    34→  // Handle field change with auto-lock: when user manually edits a lockable field, engage the lock
    35→  const handleFieldChange = useCallback((fieldName, value) => {
    36→    setFormData(prev => ({ ...prev, [fieldName]: value }));
    37→    // Auto-lock on manual edit for lockable fields
    38→    if (LOCKABLE_FIELDS.includes(fieldName) && !locksRef.current[fieldName]) {
    39→      updateConfig({ [`_locks/${fieldName}`]: true });
    40→    }
    41→  }, [updateConfig]);
    42→
    43→  // Initialize form data when config loads
    44→  useEffect(() => {
    45→    if (config) {
