    52→        team1Name: config.team1Name || '',
    53→        team1Logo: config.team1Logo || '',
    54→        team1Ave: config.team1Ave || '',
    55→        team1High: config.team1High || '',
    56→        team1Con: config.team1Con || '',
    57→        team1Coaches: config.team1Coaches || '',
    58→        team2Name: config.team2Name || '',
    59→        team2Logo: config.team2Logo || '',
    60→        team2Ave: config.team2Ave || '',
    61→        team2High: config.team2High || '',
    62→        team2Con: config.team2Con || '',
    63→        team2Coaches: config.team2Coaches || '',
    64→      });
    65→    }
    66→  }, [config]);
    67→
    68→  const showToast = useCallback((message) => {
    69→    setToast(message);
    70→    setTimeout(() => setToast(''), 2000);
    71→  }, []);
    72→
    73→  const handleSendGraphic = useCallback(async (graphicId, frameTitle = null) => {
    74→    const data = { ...formData };
