                    )}
                  </div>
                  <div className="flex items-center gap-2">
                    {aiLoading && (
                      <ArrowPathIcon className="w-4 h-4 text-purple-400 animate-spin" />
                    )}
                    <button
                      onClick={(e) => { e.stopPropagation(); refreshAI(); }}
