                    <li className="flex items-center gap-2 text-red-400">
                      <span className="w-1.5 h-1.5 bg-red-400 rounded-full"></span>
                      {rundownModifiedSummary.removed.length} segment{rundownModifiedSummary.removed.length !== 1 ? 's' : ''} removed
                    </li>
