            <ExclamationTriangleIcon className="w-5 h-5 text-yellow-400 flex-shrink-0" />
            <div className="flex-1">
              <span className="text-yellow-400 font-medium">Camera Mismatch Alert: </span>
              <span className="text-yellow-300/80">
