                  <span className="text-zinc-400">OBS</span>
                  <span className={obsConnected ? 'text-green-400' : 'text-red-400'}>
                    {obsConnected ? 'Connected' : 'Disconnected'}
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

