    73→/**
    74→ * Parse Virtius roster HTML to extract RTN IDs and headshot URLs
    75→ * @param {string} html - Raw HTML from Virtius roster table
    76→ * @returns {Array<{rtnId: string, headshotUrl: string, name: string}>}
    77→ */
    78→export function parseVirtiusRosterHtml(html) {
    79→  const results = [];
    80→
    81→  // Match each row: find athlete name, headshot URL, and RTN ID
    82→  // Pattern: img src for headshot, then name in a div, then rtnId in an input
    83→  const rowRegex = /<tr[^>]*role="row"[^>]*>([\s\S]*?)<\/tr>/gi;
    84→  const imgRegex = /src="(https:\/\/media\.virti\.us\/upload\/images\/athlete\/[^"]+)"/i;
    85→  const nameRegex = /alt="([^"]+)\s+Profile"/i;
    86→  const rtnIdRegex = /<input[^>]*readonly[^>]*value="(\d+)"/i;
    87→
    88→  let match;
    89→  while ((match = rowRegex.exec(html)) !== null) {
    90→    const rowHtml = match[1];
    91→
    92→    const imgMatch = rowHtml.match(imgRegex);
    93→    const nameMatch = rowHtml.match(nameRegex);
    94→    const rtnIdMatch = rowHtml.match(rtnIdRegex);
    95→
    96→    if (imgMatch && rtnIdMatch) {
    97→      results.push({
    98→        headshotUrl: imgMatch[1],
    99→        name: nameMatch ? nameMatch[1] : 'Unknown',
   100→        rtnId: rtnIdMatch[1],
   101→      });
   102→    }
   103→  }
   104→
   105→  return results;
   106→}
