   124→  // Fetch RTN team dashboards and Firebase headshots in parallel
   125→  const [rtnResults, firebaseHeadshots] = await Promise.all([
   126→    Promise.allSettled(teamNames.map(name => getTeamDashboard(name, gender))),
   127→    getFirebaseHeadshots()
   128→  ]);
   129→
   130→  rtnResults.forEach((result, index) => {
   131→    const teamKey = `team${index + 1}`;
   132→    if (result.status === 'fulfilled' && result.value) {
   133→      const dashboard = result.value;
   134→
   135→      // Extract and normalize the data we care about
   136→      teamData[teamKey] = {
   137→        rtnId: dashboard.info?.team_id || null,
   138→        fetchedAt: new Date().toISOString(),
   139→
   140→        // Coaching staff (filtered to coaches only)
   141→        coaches: (dashboard.staff || [])
   142→          .filter(s => s.position?.toLowerCase().includes('coach'))
   143→          .map(s => ({
   144→            id: s.id,
