   151→          .sort((a, b) => {
   152→            if (a.position?.toLowerCase().includes('head')) return -1;
   153→            if (b.position?.toLowerCase().includes('head')) return 1;
   154→            return 0;
   155→          }),
   156→
   157→        // Rankings
   158→        rankings: dashboard.ranks ? (gender === 'womens' ? {
   159→          vault: dashboard.ranks.vault ? parseInt(dashboard.ranks.vault) : null,
   160→          bars: dashboard.ranks.bars ? parseInt(dashboard.ranks.bars) : null,
   161→          beam: dashboard.ranks.beam ? parseInt(dashboard.ranks.beam) : null,
   162→          floor: dashboard.ranks.floor ? parseInt(dashboard.ranks.floor) : null,
   163→          team: dashboard.ranks.team ? parseInt(dashboard.ranks.team) : null,
   164→        } : {
   165→          floor: dashboard.ranks.floor ? parseInt(dashboard.ranks.floor) : null,
   166→          pommel: dashboard.ranks.phorse ? parseInt(dashboard.ranks.phorse) : null,
   167→          rings: dashboard.ranks.rings ? parseInt(dashboard.ranks.rings) : null,
   168→          vault: dashboard.ranks.vault ? parseInt(dashboard.ranks.vault) : null,
   169→          pBars: dashboard.ranks.pbars ? parseInt(dashboard.ranks.pbars) : null,
   170→          hBar: dashboard.ranks.highbar ? parseInt(dashboard.ranks.highbar) : null,
   171→          team: dashboard.ranks.team ? parseInt(dashboard.ranks.team) : null,
   172→        }) : null,
   173→
   174→        // Team scoring stats (from RTN 'test' field)
   175→        stats: dashboard.test ? {
   176→          average: dashboard.test.ave || null,
   177→          high: dashboard.test.high || null,
   178→          rqs: dashboard.test.rqs || null, // Ranking Qualifying Score
   179→        } : null,
   180→
   181→        // Roster - merge with Firebase headshots by matching athlete names
   182→        // Uses lookupHeadshot which tries multiple normalized keys for flexible matching
   183→        roster: (dashboard.roster || []).map(r => {
   184→          const firstName = r.fname?.trim() || '';
   185→          const lastName = r.lname?.trim() || '';
   186→          const fullName = `${firstName} ${lastName}`.trim();
   187→          const headshotUrl = lookupHeadshot(firebaseHeadshots, firstName, lastName);
   188→
   189→          return {
   190→            id: r.id,
   191→            rtnId: r.id ? String(r.id) : null, // RTN athlete ID for stats joining
   192→            firstName,
   193→            lastName,
   194→            fullName,
   195→            hometown: r.hometown || '',
   196→            year: r.school_year ? parseInt(r.school_year) : null,
   197→            headshotUrl, // Merged from Firebase teamsDatabase using flexible matching
   198→          };
   199→        }),
   200→
   201→        // Social links
   202→        links: (() => {
   203→          const links = {};
   204→          for (const link of (dashboard.links || [])) {
   205→            const type = link.tax_value?.toLowerCase() || '';
   206→            if (type.includes('facebook')) links.facebook = link.link;
   207→            else if (type.includes('twitter')) links.twitter = link.link;
   208→            else if (type.includes('instagram')) links.instagram = link.link;
   209→            else if (type.includes('official')) links.officialSite = link.link;
   210→          }
   211→          return links;
   212→        })(),
   213→
   214→        // Schedule
   215→        schedule: (dashboard.meets || []).map(m => ({
   216→          meetId: m.meet_id,
   217→          date: m.meet_date,
   218→          opponent: m.opponent,
   219→          description: m.meet_desc || '',
   220→          home: m.home === 'H',
   221→          away: m.home === 'A',
