   230→  for (let i = 0; i < teamNames.length; i++) {
   231→    const teamKey = `team${i + 1}`;
   232→    const data = teamData[teamKey];
   233→    if (!data?.rtnId) continue;
   234→
   235→    const teamDbKey = buildTeamKey(teamNames[i], gender);
