   240→      const teamRtnIdRef = ref(db, `teamsDatabase/teams/${teamDbKey}/rtnId`);
   241→      const existingRtnId = await get(teamRtnIdRef);
   242→      if (!existingRtnId.exists() || existingRtnId.val() !== data.rtnId) {
   243→        await set(teamRtnIdRef, data.rtnId);
   244→        console.log(`[enrichTeamsWithRTN] Stored RTN ID ${data.rtnId} for team ${teamDbKey}`);
   245→      }
   246→
   247→      // Store per-athlete RTN IDs in teamsDatabase/headshots/{name}/rtnId
   248→      if (data.roster && Array.isArray(data.roster)) {
   249→        for (const athlete of data.roster) {
   250→          if (!athlete.rtnId || !athlete.fullName) continue;
   251→          const headshotKey = normalizeName(athlete.fullName).replace(/\s+/g, '_');
   252→          if (!headshotKey) continue;
   253→          try {
   254→            const athleteRtnIdRef = ref(db, `teamsDatabase/headshots/${headshotKey}/rtnId`);
   255→            const existingAthleteRtnId = await get(athleteRtnIdRef);
   256→            if (!existingAthleteRtnId.exists() || String(existingAthleteRtnId.val()) !== athlete.rtnId) {
   257→              await set(athleteRtnIdRef, athlete.rtnId);
   258→            }
   259→          } catch (err) {
   260→            console.warn(`[enrichTeamsWithRTN] Failed to store RTN ID for athlete ${athlete.fullName}:`, err.message);
   261→          }
   262→        }
   263→      }
   264→    } catch (err) {
   265→      console.warn(`[enrichTeamsWithRTN] Failed to store RTN ID for team ${teamDbKey}:`, err.message);
   266→    }
   267→  }
   268→
   269→  return teamData;
   270→}
