   303→/**
   304→ * Check VM status by fetching /api/status endpoint
   305→ * In production (HTTPS), routes through the coordinator to avoid Mixed Content errors.
   306→ * In development (HTTP), calls the VM directly.
   307→ *
   308→ * @param {string} vmAddress - The VM address (host:port format, no protocol)
   309→ * @param {number} timeout - Timeout in milliseconds (default 5000)
   310→ * @param {string} compId - Competition ID (required for production routing)
   311→ * @returns {Promise<{online: boolean, obsConnected?: boolean, noVm?: boolean, error?: string}>}
   312→ */
   313→export async function checkVmStatus(vmAddress, timeout = 5000, compId = null) {
   314→  // In production (HTTPS), route through coordinator to avoid Mixed Content
   315→  if (isSecureContext() && compId) {
   316→    const controller = new AbortController();
   317→    const timeoutId = setTimeout(() => controller.abort(), timeout);
   318→
   319→    try {
   320→      const response = await fetch(`https://api.commentarygraphic.com/api/vm/${compId}/status`, {
   321→        signal: controller.signal,
   322→        headers: { 'Accept': 'application/json' },
   323→      });
   324→
   325→      clearTimeout(timeoutId);
   326→
   327→      if (!response.ok) {
   328→        return { online: false, error: `HTTP ${response.status}` };
   329→      }
   330→
   331→      return await response.json();
   332→    } catch (err) {
   333→      clearTimeout(timeoutId);
   334→      if (err.name === 'AbortError') {
   335→        return { online: false, error: 'Request timed out' };
   336→      }
   337→      return { online: false, error: err.message || 'Connection failed' };
   338→    }
   339→  }
   340→
   341→  // Development mode: call VM directly
   342→  if (!isValidVmAddress(vmAddress)) {
   343→    return { online: false, error: 'Invalid VM address format' };
   344→  }
   345→
   346→  const controller = new AbortController();
   347→  const timeoutId = setTimeout(() => controller.abort(), timeout);
   348→
   349→  try {
   350→    const response = await fetch(`http://${vmAddress}/api/status`, {
   351→      signal: controller.signal,
   352→      headers: {
   353→        'Accept': 'application/json',
   354→      },
   355→    });
   356→
   357→    clearTimeout(timeoutId);
   358→
   359→    if (!response.ok) {
   360→      return { online: false, error: `HTTP ${response.status}` };
   361→    }
   362→
   363→    const data = await response.json();
   364→
   365→    return {
   366→      online: true,
   367→      obsConnected: data.obsConnected || false,
   368→    };
   369→  } catch (err) {
   370→    clearTimeout(timeoutId);
   371→
   372→    if (err.name === 'AbortError') {
   373→      return { online: false, error: 'Request timed out' };
   374→    }
   375→
   376→    return { online: false, error: err.message || 'Connection failed' };
   377→  }
   378→}
