   380→/**
   381→ * Fire-and-forget: trigger RTN stats ingestion on the coordinator server.
   382→ * Creates a temporary socket connection, emits ingestRtnStats, then disconnects.
   383→ * Non-blocking — the competition is usable immediately while stats fetch in background.
   384→ */
   385→function triggerStatsIngestion(compId) {
   386→  if (!compId) return;
   387→
   388→  try {
   389→    const socket = io(SERVER_URL, {
   390→      transports: ['websocket', 'polling'],
   391→      query: { compId },
   392→    });
   393→
   394→    const cleanup = () => {
   395→      try { socket.disconnect(); } catch { /* ignore */ }
   396→    };
   397→
   398→    socket.on('connect', () => {
   399→      console.log(`[triggerStatsIngestion] Connected, emitting ingestRtnStats for ${compId}`);
   400→      socket.emit('ingestRtnStats', { compId });
   401→    });
   402→
   403→    socket.on('rtnStatsResult', (data) => {
   404→      if (data.success) {
   405→        console.log(`[triggerStatsIngestion] Stats ingestion complete for ${compId}`);
   406→      } else {
   407→        console.warn(`[triggerStatsIngestion] Stats ingestion failed for ${compId}:`, data.error);
   408→      }
   409→      cleanup();
   410→    });
   411→
   412→    socket.on('connect_error', (err) => {
   413→      console.warn(`[triggerStatsIngestion] Connection failed:`, err.message);
   414→      cleanup();
   415→    });
   416→
   417→    // Safety timeout: disconnect after 60s regardless
   418→    setTimeout(cleanup, 60000);
   419→  } catch (err) {
   420→    console.warn(`[triggerStatsIngestion] Failed to trigger stats ingestion:`, err.message);
   421→  }
   422→}
