    35→    for (const { index, teamKey } of teamKeys) {
    36→      const metaRef = ref(db, `teamsDatabase/stats/${teamKey}/meta`);
    37→      const unsub = onValue(metaRef, (snapshot) => {
    38→        setTeamMetas(prev => ({
    39→          ...prev,
    40→          [index]: snapshot.val() || null,
    41→        }));
    42→      }, () => {
    43→        // Ignore errors silently
    44→      });
    45→      unsubs.push(unsub);
    46→    }
    47→
    48→    return () => unsubs.forEach(u => u());
    49→  // eslint-disable-next-line react-hooks/exhaustive-deps
    50→  }, [compId, config?.compType, config?.team1Name, config?.team2Name]);
    51→
    52→  // Determine overall status from all team metas
