    47→  } = useCoordinator();
    48→  const { getTeamLogo } = useTeamsDatabase();
    49→
    50→  const [searchQuery, setSearchQuery] = useState('');
    51→  const [vmStatuses, setVmStatuses] = useState({});
    52→  const [assigningVm, setAssigningVm] = useState(null);
    53→  const [releasingVm, setReleasingVm] = useState(null);
    54→  const [showPastCompetitions, setShowPastCompetitions] = useState(false);
    55→  const navigate = useNavigate();
    56→
    57→  // Modal state for create/edit
    58→  const [showModal, setShowModal] = useState(false);
    59→  const [editingCompId, setEditingCompId] = useState(null);
    60→  const [formData, setFormData] = useState(getDefaultFormData());
    61→  const [virtiusSessionId, setVirtiusSessionId] = useState('');
    62→  const [virtiusFetching, setVirtiusFetching] = useState(false);
    63→  const [virtiusError, setVirtiusError] = useState(null);
    64→  const [refreshing, setRefreshing] = useState(false);
    65→
    66→  // Coordinator status helpers
    67→  const isCoordinatorOffline = coordinatorStatus === COORDINATOR_STATUS.OFFLINE;
    68→  const isCoordinatorStarting = coordinatorStatus === COORDINATOR_STATUS.STARTING;
    69→
    70→  function getDefaultFormData() {
    71→    return {
    72→      compId: '',
    73→      compType: '',
    74→      gender: '',
    75→      eventName: '',
    76→      meetDate: '',
    77→      venue: '',
    78→      location: '',
    79→      team1Name: '', team1Logo: '', team1Tricode: '',
    80→      team2Name: '', team2Logo: '', team2Tricode: '',
    81→      team3Name: '', team3Logo: '', team3Tricode: '',
    82→      team4Name: '', team4Logo: '', team4Tricode: '',
    83→      team5Name: '', team5Logo: '', team5Tricode: '',
    84→      team6Name: '', team6Logo: '', team6Tricode: '',
    85→    };
    86→  }
    87→
    88→  function generateCompId() {
    89→    const chars = 'abcdefghijklmnopqrstuvwxyz0123456789';
    90→    let result = '';
    91→    for (let i = 0; i < 8; i++) {
    92→      result += chars.charAt(Math.floor(Math.random() * chars.length));
    93→    }
    94→    return result;
    95→  }
    96→
    97→  // Group competitions by date
    98→  const groupedCompetitions = useMemo(() => {
    99→    const now = new Date();
   100→    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
   101→    const tomorrow = new Date(today);
   102→    tomorrow.setDate(tomorrow.getDate() + 1);
   103→
   104→    const groups = {
   105→      today: [],
   106→      tomorrow: [],
   107→      upcoming: [],
   108→      past: []
   109→    };
   110→
   111→    Object.entries(competitions).forEach(([compId, data]) => {
   112→      const config = data?.config;
   113→      if (!config) return;
   114→
   115→      const searchLower = searchQuery.toLowerCase();
   116→      const matchesSearch = !searchQuery ||
   117→        config.eventName?.toLowerCase().includes(searchLower) ||
   118→        config.venue?.toLowerCase().includes(searchLower) ||
   119→        config.team1Name?.toLowerCase().includes(searchLower) ||
   120→        config.team2Name?.toLowerCase().includes(searchLower) ||
   121→        compId.toLowerCase().includes(searchLower);
   122→
   123→      if (!matchesSearch) return;
   124→
   125→      const meetDate = config.meetDate ? new Date(config.meetDate) : null;
   126→      const competition = { compId, config, meetDate };
   127→
   128→      if (!meetDate) {
   129→        groups.upcoming.push(competition);
   130→      } else if (meetDate >= today && meetDate < tomorrow) {
   131→        groups.today.push(competition);
   132→      } else if (meetDate >= tomorrow && meetDate < new Date(tomorrow.getTime() + 86400000)) {
   133→        groups.tomorrow.push(competition);
   134→      } else if (meetDate >= today) {
   135→        groups.upcoming.push(competition);
   136→      } else {
   137→        groups.past.push(competition);
   138→      }
   139→    });
   140→
   141→    const sortByDate = (a, b) => {
   142→      if (!a.meetDate && !b.meetDate) return 0;
   143→      if (!a.meetDate) return 1;
   144→      if (!b.meetDate) return -1;
   145→      return a.meetDate - b.meetDate;
   146→    };
   147→
   148→    groups.today.sort(sortByDate);
   149→    groups.tomorrow.sort(sortByDate);
   150→    groups.upcoming.sort(sortByDate);
   151→    groups.past.sort((a, b) => sortByDate(b, a));
   152→
   153→    return groups;
   154→  }, [competitions, searchQuery]);
   155→
   156→  // Check VM status for competitions (routes through coordinator in production)
   157→  useEffect(() => {
   158→    const checkStatuses = async () => {
   159→      for (const [compId, data] of Object.entries(competitions)) {
