   188→    if (!result.success) {
   189→      console.error('Failed to release VM:', result.error);
   190→    }
   191→  };
   192→
   193→  // Virtius import
   194→  function formatDate(dateStr) {
   195→    if (!dateStr) return '';
   196→    const date = new Date(dateStr + 'T00:00:00');
   197→    return date.toLocaleDateString('en-US', {
   198→      year: 'numeric', month: 'long', day: 'numeric'
   199→    });
   200→  }
   201→
   202→  function inferCompType(sex, teamCount) {
   203→    const prefix = sex === 'women' ? 'womens' : 'mens';
   204→    const suffix = teamCount === 2 ? 'dual' :
   205→                   teamCount === 3 ? 'tri' :
   206→                   teamCount === 4 ? 'quad' :
   207→                   teamCount === 5 ? '5-team' : '6-team';
   208→    return `${prefix}-${suffix}`;
   209→  }
   210→
   211→  async function fetchFromVirtius() {
   212→    if (!virtiusSessionId.trim()) return;
   213→    setVirtiusFetching(true);
   214→    setVirtiusError(null);
   215→
   216→    try {
   217→      const response = await fetch(`https://api.virti.us/session/${virtiusSessionId.trim()}/json`);
   218→      if (!response.ok) throw new Error('Session not found');
   219→      const data = await response.json();
   220→
   221→      const meet = data.meet;
   222→      const teams = meet.teams || [];
   223→      const sortedTeams = [...teams].sort((a, b) => (a.team_order || 0) - (b.team_order || 0));
