    95→/**
    96→ * Fetch a single URL with timeout and retry-once on 500 errors.
    97→ * @param {string} url
    98→ * @returns {Promise<Object>} Parsed JSON response
    99→ */
   100→async function fetchWithRetry(url) {
   101→  const attempt = async () => {
   102→    const controller = new AbortController();
   103→    const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
   104→    try {
   105→      const response = await fetch(url, { signal: controller.signal });
   106→      clearTimeout(timeoutId);
   107→      if (!response.ok) {
   108→        throw new Error(`${response.status} ${response.statusText}`);
   109→      }
   110→      return response.json();
   111→    } catch (err) {
   112→      clearTimeout(timeoutId);
   113→      throw err;
   114→    }
   115→  };
   116→
   117→  try {
   118→    return await attempt();
   119→  } catch (err) {
   120→    // Retry once on 500-level errors
   121→    if (err.message && err.message.startsWith('5')) {
   122→      console.log(`[rtnStatsService] Retrying after 500 error: ${url}`);
   123→      await sleep(1000);
   124→      return await attempt();
   125→    }
   126→    throw err;
   127→  }
   128→}
