   146→      const isEmpty = data === null || data === undefined ||
   147→        (Array.isArray(data) && data.length === 0) ||
   148→        (typeof data === 'object' && !Array.isArray(data) && Object.keys(data).length === 0);
   149→
   150→      if (isEmpty) {
   151→        results.push({ label, data: null, status: 'empty' });
   152→      } else {
   153→        results.push({ label, data, status: 'ok' });
   154→      }
   155→    } catch (err) {
   156→      console.error(`[rtnStatsService] Fetch failed for ${label}: ${err.message}`);
   157→      results.push({ label, data: null, status: 'error', error: err.message });
   158→    }
   159→    if (onProgress) onProgress(label, i + 1, urls.length, results[results.length - 1].status);
   160→    if (i < urls.length - 1) await sleep(RATE_LIMIT_MS);
   161→  }
   162→  return results;
   163→}
   164→
   165→// ============================================================================
