   234→
   235→/**
   236→ * Determine the current RTN week for a given gender and year.
   237→ * Fetches the results schema and looks for the current week.
   238→ *
   239→ * Endpoint: /{gender}/results/{year}/1/0/{type}
   240→ * The response includes a `schema.weeks` array with week objects.
   241→ * Looks for the week with `current: "1"` or falls back to the latest week with `rqs: "1"`.
   242→ *
   243→ * @param {string} gender - "mens" or "womens"
   244→ * @param {number} year
   245→ * @returns {Promise<number>} Week number (defaults to 1 on failure)
   246→ */
   247→async function getCurrentWeek(gender, year) {
   248→  try {
   249→    const type = getTeamRankingType(gender);
   250→    const url = `${RTN_BASE}/${getGenderPath(gender)}/results/${year}/1/0/${type}`;
   251→    const data = await fetchWithRetry(url);
   252→
   253→    if (data?.schema?.weeks && Array.isArray(data.schema.weeks)) {
   254→      // Look for the week marked as current
   255→      const currentWeek = data.schema.weeks.find(w => w.current === '1' || w.current === 1);
   256→      if (currentWeek?.week) {
   257→        return parseInt(currentWeek.week, 10);
   258→      }
   259→
   260→      // Fallback: latest week with rqs enabled
   261→      const rqsWeeks = data.schema.weeks.filter(w => w.rqs === '1' || w.rqs === 1);
   262→      if (rqsWeeks.length > 0) {
   263→        const latest = rqsWeeks[rqsWeeks.length - 1];
   264→        return parseInt(latest.week, 10);
   265→      }
   266→
   267→      // Fallback: last week in array
   268→      if (data.schema.weeks.length > 0) {
   269→        const last = data.schema.weeks[data.schema.weeks.length - 1];
   270→        return parseInt(last.week, 10);
   271→      }
   272→    }
   273→
   274→    console.warn('[rtnStatsService] Could not determine current week, defaulting to 1');
   275→    return 1;
   276→  } catch (err) {
   277→    console.error(`[rtnStatsService] Failed to get current week: ${err.message}`);
   278→    return 1;
   279→  }
   280→}
