     1→/**
     2→ * useRtnStats - React hook for accessing RTN (Road To Nationals) statistics
     3→ *
     4→ * Subscribes to team stats from Firebase:
     5→ * - Before show: reads from shared store at teamsDatabase/stats/{teamKey}/
     6→ * - During show: reads from frozen snapshot at competitions/{compId}/rtnStats/
     7→ *
     8→ * Also listens for socket events (rtnStatsResult, rtnStatsProgress) to track
     9→ * ingestion status in real-time.
    10→ *
    11→ * NOTE: This hook consumes server-side normalized stats from Firebase.
    12→ * It is separate from useRoadToNationals.js which handles client-side RTN
    13→ * dashboard fetching for coach names.
    14→ */
    15→
    16→import { useState, useEffect, useMemo, useCallback, useRef } from 'react';
    17→import { db, ref, onValue } from '../lib/firebase';
    18→import { useShow } from '../context/ShowContext';
    19→
    20→const STALENESS_TTL = 24 * 60 * 60 * 1000; // 24 hours
    21→
    22→/**
    23→ * Build a teamsDatabase key from a team name and gender.
    24→ * Mirrors server-side buildTeamDbKey() in server/lib/rtnStatsService.js.
    25→ * @param {string} schoolName - e.g., "Oklahoma", "Stanford"
    26→ * @param {string} gender - "mens" or "womens"
    27→ * @returns {string} e.g., "oklahoma-womens"
    28→ */
    29→function buildTeamDbKey(schoolName, gender) {
    30→  if (!schoolName) return '';
    31→  const normalized = schoolName
    32→    .toLowerCase()
    33→    .replace(/['']/g, '')
    34→    .replace(/[^a-z0-9\s-]/g, '')
    35→    .replace(/-mens$/, '')
    36→    .replace(/-womens$/, '')
    37→    .replace(/ mens$/, '')
    38→    .replace(/ womens$/, '')
    39→    .replace(/ men$/, '')
    40→    .replace(/ women$/, '')
    41→    .replace(/\s+/g, '-')
    42→    .trim();
    43→  if (!normalized) return '';
    44→  const genderSuffix = gender === 'womens' ? 'womens' : 'mens';
    45→  return `${normalized}-${genderSuffix}`;
    46→}
    47→
    48→/**
    49→ * Parse competition type string to extract gender and team count.
    50→ * @param {string} compType - e.g., "womens-dual", "mens-tri", "womens-quad"
    51→ * @returns {{ gender: string, teamCount: number }}
    52→ */
    53→function parseCompetitionType(compType) {
    54→  if (!compType) return { gender: 'womens', teamCount: 2 };
    55→  const parts = compType.toLowerCase().split('-');
    56→  const gender = parts[0] === 'mens' ? 'mens' : 'womens';
    57→  const typeMap = { dual: 2, tri: 3, quad: 4, '5': 5, '6': 6 };
    58→  const teamCount = typeMap[parts[1]] || 2;
    59→  return { gender, teamCount };
    60→}
    61→
    62→/**
    63→ * Hook for accessing RTN statistics for teams in a competition.
    64→ *
    65→ * @param {string} compId - Competition ID
    66→ * @param {object} config - Competition config object (from useCompetition)
    67→ * @returns {{
    68→ *   stats: Object,
    69→ *   meta: Object,
    70→ *   loading: boolean,
    71→ *   error: string|null,
    72→ *   refresh: (teamKey?: string) => void,
    73→ *   isStale: boolean,
    74→ *   progress: Object|null,
    75→ *   teamKeys: Array<{index: number, teamKey: string}>
    76→ * }}
    77→ */
    78→export function useRtnStats(compId, config) {
    79→  const { socket, timesheetState } = useShow();
    80→
    81→  const [sharedStats, setSharedStats] = useState({});
    82→  const [snapshotStats, setSnapshotStats] = useState(null);
    83→  const [loading, setLoading] = useState(true);
    84→  const [error, setError] = useState(null);
    85→  const [progress, setProgress] = useState(null);
    86→  const loadedCountRef = useRef(0);
    87→
    88→  const showIsRunning = useMemo(() => {
    89→    return timesheetState?.isRunning || false;
    90→  }, [timesheetState?.isRunning]);
    91→
    92→  // Parse gender from competition type
    93→  const { gender, teamCount } = useMemo(() => {
    94→    return parseCompetitionType(config?.compType);
    95→  }, [config?.compType]);
    96→
    97→  // Build team keys from config
    98→  const teamKeys = useMemo(() => {
    99→    if (!config) return [];
   100→    const keys = [];
   101→    for (let i = 1; i <= 6; i++) {
   102→      const teamName = config[`team${i}Name`];
   103→      if (teamName) {
   104→        const teamKey = buildTeamDbKey(teamName, gender);
   105→        if (teamKey) {
   106→          keys.push({ index: i, teamKey });
   107→        }
   108→      }
   109→    }
   110→    return keys;
   111→  }, [config, gender]);
   112→
   113→  // Subscribe to shared stats store (teamsDatabase/stats/{teamKey}/) for pre-show
   114→  useEffect(() => {
   115→    if (!teamKeys.length || showIsRunning) {
   116→      setLoading(false);
   117→      return;
   118→    }
   119→
   120→    setLoading(true);
   121→    loadedCountRef.current = 0;
   122→    const expectedCount = teamKeys.length;
   123→    const unsubs = [];
   124→
   125→    for (const { index, teamKey } of teamKeys) {
   126→      const statsRef = ref(db, `teamsDatabase/stats/${teamKey}`);
   127→      const unsub = onValue(statsRef, (snapshot) => {
   128→        const data = snapshot.val();
   129→        setSharedStats(prev => ({
   130→          ...prev,
   131→          [`team${index}`]: data || null,
   132→        }));
   133→        loadedCountRef.current++;
   134→        if (loadedCountRef.current >= expectedCount) {
   135→          setLoading(false);
   136→        }
   137→      }, (err) => {
   138→        console.error(`[useRtnStats] Firebase error for ${teamKey}:`, err);
   139→        setError(err.message);
   140→        loadedCountRef.current++;
   141→        if (loadedCountRef.current >= expectedCount) {
   142→          setLoading(false);
   143→        }
   144→      });
   145→      unsubs.push(unsub);
   146→    }
   147→
   148→    return () => {
   149→      unsubs.forEach(unsub => unsub());
   150→    };
   151→  }, [teamKeys, showIsRunning]);
   152→
   153→  // Subscribe to competition snapshot (competitions/{compId}/rtnStats/) during show
   154→  useEffect(() => {
   155→    if (!compId || !showIsRunning) {
   156→      setSnapshotStats(null);
   157→      return;
   158→    }
   159→
   160→    const snapshotRef = ref(db, `competitions/${compId}/rtnStats`);
   161→    const unsub = onValue(snapshotRef, (snapshot) => {
   162→      setSnapshotStats(snapshot.val() || null);
   163→      setLoading(false);
   164→    }, (err) => {
   165→      console.error('[useRtnStats] Firebase snapshot error:', err);
   166→      setError(err.message);
   167→      setLoading(false);
   168→    });
   169→
   170→    return () => unsub();
   171→  }, [compId, showIsRunning]);
   172→
   173→  // Socket listeners for rtnStatsResult and rtnStatsProgress
   174→  useEffect(() => {
   175→    if (!socket) return;
   176→
   177→    const handleStatsResult = (data) => {
   178→      if (data.compId && data.compId !== compId) return;
   179→      if (data.error) {
   180→        setError(data.error);
   181→      } else {
   182→        setError(null);
   183→      }
   184→      setProgress(null);
   185→    };
   186→
   187→    const handleStatsProgress = (data) => {
   188→      if (data.compId && data.compId !== compId) return;
   189→      setProgress(data);
   190→    };
   191→
   192→    socket.on('rtnStatsResult', handleStatsResult);
   193→    socket.on('rtnStatsProgress', handleStatsProgress);
   194→
   195→    return () => {
   196→      socket.off('rtnStatsResult', handleStatsResult);
   197→      socket.off('rtnStatsProgress', handleStatsProgress);
   198→    };
   199→  }, [socket, compId]);
   200→
   201→  // Use snapshot stats during show, shared stats otherwise
   202→  const stats = useMemo(() => {
   203→    if (showIsRunning && snapshotStats) {
   204→      return snapshotStats;
   205→    }
   206→    return sharedStats;
   207→  }, [showIsRunning, snapshotStats, sharedStats]);
   208→
   209→  // Derive meta from the first team that has it
   210→  const meta = useMemo(() => {
   211→    for (let i = 1; i <= 6; i++) {
   212→      const teamStats = stats[`team${i}`];
   213→      if (teamStats?.meta) {
   214→        return teamStats.meta;
   215→      }
   216→    }
   217→    return null;
   218→  }, [stats]);
   219→
   220→  // Check staleness from meta.fetchedAt
   221→  const isStale = useMemo(() => {
   222→    if (!meta?.fetchedAt) return true;
   223→    const fetchedTime = new Date(meta.fetchedAt).getTime();
   224→    return Date.now() - fetchedTime > STALENESS_TTL;
   225→  }, [meta?.fetchedAt]);
   226→
   227→  // Refresh function - emits refreshRtnStats socket event
   228→  const refresh = useCallback((teamKey) => {
   229→    if (!socket || !compId) return;
   230→    socket.emit('refreshRtnStats', { compId, teamKey: teamKey || undefined });
   231→    setProgress({ status: 'starting' });
   232→  }, [socket, compId]);
   233→
   234→  return {
   235→    stats,
   236→    meta,
   237→    loading,
   238→    error,
   239→    refresh,
   240→    isStale,
   241→    progress,
   242→    teamKeys,
   243→  };
   244→}
   245→
   246→export { buildTeamDbKey, parseCompetitionType };
   247→
   248→export default useRtnStats;
   249→

