     1→/**
     2→ * RTN Stats Service
     3→ *
     4→ * Server-side service for fetching, normalizing, and storing NCAA gymnastics
     5→ * statistics from Road To Nationals (roadtonationals.com).
     6→ *
     7→ * This service handles:
     8→ * - Fetching all 8 RTN stat endpoints per team (rate-limited)
     9→ * - Rate limiting (200ms between requests, 10s timeout, retry on 500)
    10→ * - Event code translation for men's and women's gymnastics
    11→ *
    12→ * Firebase paths written:
    13→ *   teamsDatabase/stats/{teamKey}/  - Shared stats store (source of truth)
    14→ *
    15→ * Task 3: Fetch functions and rate limiting only.
    16→ * Tasks 4-7 add normalization, orchestration, config sync, and socket wiring.
    17→ */
    18→
    19→// ============================================================================
    20→// Constants
    21→// ============================================================================
    22→
    23→const RTN_BASE = 'https://www.roadtonationals.com/api';
    24→const RATE_LIMIT_MS = 200;
    25→const REQUEST_TIMEOUT_MS = 10000;
    26→const STALENESS_TTL = 24 * 60 * 60 * 1000; // 24 hours
    27→const RANKINGS_CACHE_TTL = 24 * 60 * 60 * 1000; // 24 hours
    28→
    29→// Women's consistency event field -> standard code
    30→const WOMENS_CONSISTENCY_EVENTS = { vts: 'VT', ubs: 'UB', bbs: 'BB', fxs: 'FX' };
    31→// Men's consistency event field -> standard code
    32→const MENS_CONSISTENCY_EVENTS = { fxs: 'FX', phs: 'PH', srs: 'SR', vts: 'VT', pbs: 'PB', hbs: 'HB' };
    33→
    34→// Women's MVP sum fields -> standard code
    35→const WOMENS_MVP_EVENTS = { vsum: 'VT', ubsum: 'UB', bbsum: 'BB', fsum: 'FX' };
    36→// Men's MVP sum fields -> standard code
    37→const MENS_MVP_EVENTS = { fxsum: 'FX', phsum: 'PH', srsum: 'SR', vsum: 'VT', pbsum: 'PB', hbsum: 'HB' };
    38→
    39→// Women's individual stats fields (highs/averages) -> standard code
    40→const WOMENS_INDIVIDUAL_FIELDS = { maxv: 'VT', maxub: 'UB', maxbb: 'BB', maxfx: 'FX', maxaa: 'AA' };
    41→// Men's individual stats fields -> standard code
    42→const MENS_INDIVIDUAL_FIELDS = { maxfx: 'FX', maxph: 'PH', maxsr: 'SR', maxvt: 'VT', maxpb: 'PB', maxhb: 'HB', maxaa: 'AA' };
    43→
    44→// Individual ranking event numbers -> standard code
    45→const WOMENS_INDIVIDUAL_EVENTS = { 1: 'VT', 2: 'UB', 3: 'BB', 4: 'FX', 5: 'AA' };
    46→const MENS_INDIVIDUAL_EVENTS = { 1: 'FX', 2: 'PH', 3: 'SR', 4: 'VT', 5: 'PB', 6: 'HB', 7: 'AA' };
    47→
    48→// Team ranking type codes
    49→const TEAM_RANKING_TYPE = { womens: 5, mens: 7 };
    50→
    51→// Top scores event field names (same for men/women where applicable)
    52→const WOMENS_TOP_SCORE_EVENTS = { vault: 'VT', bars: 'UB', beam: 'BB', floor: 'FX' };
    53→const MENS_TOP_SCORE_EVENTS = { floor: 'FX', phorse: 'PH', rings: 'SR', vault: 'VT', pbars: 'PB', highbar: 'HB' };
    54→
    55→// ============================================================================
    56→// Helpers
    57→// ============================================================================
    58→
    59→function sleep(ms) {
    60→  return new Promise(resolve => setTimeout(resolve, ms));
    61→}
    62→
    63→function getGenderPath(gender) {
    64→  return gender === 'womens' ? 'women' : 'men';
    65→}
    66→
    67→function getConsistencyEvents(gender) {
    68→  return gender === 'womens' ? WOMENS_CONSISTENCY_EVENTS : MENS_CONSISTENCY_EVENTS;
    69→}
    70→
    71→function getMvpEvents(gender) {
    72→  return gender === 'womens' ? WOMENS_MVP_EVENTS : MENS_MVP_EVENTS;
    73→}
    74→
    75→function getIndividualFields(gender) {
    76→  return gender === 'womens' ? WOMENS_INDIVIDUAL_FIELDS : MENS_INDIVIDUAL_FIELDS;
    77→}
    78→
    79→function getIndividualEventNumbers(gender) {
    80→  return gender === 'womens' ? WOMENS_INDIVIDUAL_EVENTS : MENS_INDIVIDUAL_EVENTS;
    81→}
    82→
    83→function getTopScoreEvents(gender) {
    84→  return gender === 'womens' ? WOMENS_TOP_SCORE_EVENTS : MENS_TOP_SCORE_EVENTS;
    85→}
    86→
    87→function getTeamRankingType(gender) {
    88→  return TEAM_RANKING_TYPE[gender] || 5;
    89→}
    90→
    91→// ============================================================================
    92→// Rate-Limited Fetch
    93→// ============================================================================
    94→
    95→/**
    96→ * Fetch a single URL with timeout and retry-once on 500 errors.
    97→ * @param {string} url
    98→ * @returns {Promise<Object>} Parsed JSON response
    99→ */
   100→async function fetchWithRetry(url) {
   101→  const attempt = async () => {
   102→    const controller = new AbortController();
   103→    const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
   104→    try {
   105→      const response = await fetch(url, { signal: controller.signal });
   106→      clearTimeout(timeoutId);
   107→      if (!response.ok) {
   108→        throw new Error(`${response.status} ${response.statusText}`);
   109→      }
   110→      return response.json();
   111→    } catch (err) {
   112→      clearTimeout(timeoutId);
   113→      throw err;
   114→    }
   115→  };
   116→
   117→  try {
   118→    return await attempt();
   119→  } catch (err) {
   120→    // Retry once on 500-level errors
   121→    if (err.message && err.message.startsWith('5')) {
   122→      console.log(`[rtnStatsService] Retrying after 500 error: ${url}`);
   123→      await sleep(1000);
   124→      return await attempt();
   125→    }
   126→    throw err;
   127→  }
   128→}
   129→
   130→/**
   131→ * Fetch multiple URLs sequentially with rate limiting.
   132→ * Each entry: { url, label }
   133→ * Returns array of { label, data, status, error? }
   134→ *
   135→ * @param {Array<{url: string, label: string}>} urls
   136→ * @param {Function} [onProgress] - Callback: (label, step, total, status)
   137→ * @returns {Promise<Array<{label: string, data: Object|null, status: string, error?: string}>>}
   138→ */
   139→async function rateLimitedFetch(urls, onProgress) {
   140→  const results = [];
   141→  for (let i = 0; i < urls.length; i++) {
   142→    const { url, label } = urls[i];
   143→    try {
   144→      const data = await fetchWithRetry(url);
   145→      // Check for empty responses
   146→      const isEmpty = data === null || data === undefined ||
   147→        (Array.isArray(data) && data.length === 0) ||
   148→        (typeof data === 'object' && !Array.isArray(data) && Object.keys(data).length === 0);
   149→
   150→      if (isEmpty) {
   151→        results.push({ label, data: null, status: 'empty' });
   152→      } else {
   153→        results.push({ label, data, status: 'ok' });
   154→      }
   155→    } catch (err) {
   156→      console.error(`[rtnStatsService] Fetch failed for ${label}: ${err.message}`);
   157→      results.push({ label, data: null, status: 'error', error: err.message });
   158→    }
   159→    if (onProgress) onProgress(label, i + 1, urls.length, results[results.length - 1].status);
   160→    if (i < urls.length - 1) await sleep(RATE_LIMIT_MS);
   161→  }
   162→  return results;
   163→}
   164→
   165→// ============================================================================
   166→// Individual Fetch Functions
   167→// ============================================================================
   168→
   169→/**
   170→ * Fetch team consistency data (per-meet event scores over season)
   171→ * Endpoint: /{gender}/teamConsistency/{year}/{tid}
   172→ */
   173→async function fetchConsistency(gender, year, tid) {
   174→  const url = `${RTN_BASE}/${getGenderPath(gender)}/teamConsistency/${year}/${tid}`;
   175→  return fetchWithRetry(url);
   176→}
   177→
   178→/**
   179→ * Fetch MVP data (athlete contribution totals)
   180→ * Endpoint: /{gender}/mvp/{year}/{tid}
   181→ */
   182→async function fetchMVP(gender, year, tid) {
   183→  const url = `${RTN_BASE}/${getGenderPath(gender)}/mvp/${year}/${tid}`;
   184→  return fetchWithRetry(url);
   185→}
   186→
   187→/**
   188→ * Fetch top scores (best possible lineup)
   189→ * Endpoint: /{gender}/topscores/{year}/{tid}
   190→ */
   191→async function fetchTopScores(gender, year, tid) {
   192→  const url = `${RTN_BASE}/${getGenderPath(gender)}/topscores/${year}/${tid}`;
   193→  return fetchWithRetry(url);
   194→}
   195→
   196→/**
   197→ * Fetch lineup data (meet-by-meet lineup usage)
   198→ * Endpoint: /{gender}/lineup/{year}/{tid}
   199→ */
   200→async function fetchLineup(gender, year, tid) {
   201→  const url = `${RTN_BASE}/${getGenderPath(gender)}/lineup/${year}/${tid}`;
   202→  return fetchWithRetry(url);
   203→}
   204→
   205→/**
   206→ * Fetch individual high scores per athlete
   207→ * Endpoint: /{gender}/rostermain/{year}/{tid}/2
   208→ */
   209→async function fetchIndividualHighs(gender, year, tid) {
   210→  const url = `${RTN_BASE}/${getGenderPath(gender)}/rostermain/${year}/${tid}/2`;
   211→  return fetchWithRetry(url);
   212→}
   213→
   214→/**
   215→ * Fetch individual averages per athlete
   216→ * Endpoint: /{gender}/rostermain/{year}/{tid}/3
   217→ */
   218→async function fetchIndividualAverages(gender, year, tid) {
   219→  const url = `${RTN_BASE}/${getGenderPath(gender)}/rostermain/${year}/${tid}/3`;
   220→  return fetchWithRetry(url);
   221→}
   222→
   223→/**
   224→ * Fetch team ranking from league results
   225→ * Endpoint: /{gender}/results/{year}/{week}/0/{type}
   226→ *
   227→ * Returns the full ranking results; caller should find the team by tid.
   228→ */
   229→async function fetchTeamRanking(gender, year, week, tid) {
   230→  const type = getTeamRankingType(gender);
   231→  const url = `${RTN_BASE}/${getGenderPath(gender)}/results/${year}/${week}/0/${type}`;
   232→  return fetchWithRetry(url);
   233→}
   234→
   235→/**
   236→ * Determine the current RTN week for a given gender and year.
   237→ * Fetches the results schema and looks for the current week.
   238→ *
   239→ * Endpoint: /{gender}/results/{year}/1/0/{type}
   240→ * The response includes a `schema.weeks` array with week objects.
   241→ * Looks for the week with `current: "1"` or falls back to the latest week with `rqs: "1"`.
   242→ *
   243→ * @param {string} gender - "mens" or "womens"
   244→ * @param {number} year
   245→ * @returns {Promise<number>} Week number (defaults to 1 on failure)
   246→ */
   247→async function getCurrentWeek(gender, year) {
   248→  try {
   249→    const type = getTeamRankingType(gender);
   250→    const url = `${RTN_BASE}/${getGenderPath(gender)}/results/${year}/1/0/${type}`;
   251→    const data = await fetchWithRetry(url);
   252→
   253→    if (data?.schema?.weeks && Array.isArray(data.schema.weeks)) {
   254→      // Look for the week marked as current
   255→      const currentWeek = data.schema.weeks.find(w => w.current === '1' || w.current === 1);
   256→      if (currentWeek?.week) {
   257→        return parseInt(currentWeek.week, 10);
   258→      }
   259→
   260→      // Fallback: latest week with rqs enabled
   261→      const rqsWeeks = data.schema.weeks.filter(w => w.rqs === '1' || w.rqs === 1);
   262→      if (rqsWeeks.length > 0) {
   263→        const latest = rqsWeeks[rqsWeeks.length - 1];
   264→        return parseInt(latest.week, 10);
   265→      }
   266→
   267→      // Fallback: last week in array
   268→      if (data.schema.weeks.length > 0) {
   269→        const last = data.schema.weeks[data.schema.weeks.length - 1];
   270→        return parseInt(last.week, 10);
   271→      }
   272→    }
   273→
   274→    console.warn('[rtnStatsService] Could not determine current week, defaulting to 1');
   275→    return 1;
   276→  } catch (err) {
   277→    console.error(`[rtnStatsService] Failed to get current week: ${err.message}`);
   278→    return 1;
   279→  }
   280→}
   281→
   282→/**
   283→ * Build the list of URLs for all 8 stat endpoints for a team.
   284→ * Used by rateLimitedFetch for sequential fetching.
   285→ *
   286→ * @param {string} gender - "mens" or "womens"
   287→ * @param {number} year
   288→ * @param {number|string} tid - RTN team ID
   289→ * @param {number} week - Current RTN week
   290→ * @returns {Array<{url: string, label: string}>}
   291→ */
   292→function buildTeamStatUrls(gender, year, tid, week) {
   293→  const g = getGenderPath(gender);
   294→  const type = getTeamRankingType(gender);
   295→  return [
   296→    { url: `${RTN_BASE}/${g}/results/${year}/${week}/0/${type}`, label: 'teamRanking' },
   297→    { url: `${RTN_BASE}/${g}/teamConsistency/${year}/${tid}`, label: 'consistency' },
   298→    { url: `${RTN_BASE}/${g}/mvp/${year}/${tid}`, label: 'mvp' },
   299→    { url: `${RTN_BASE}/${g}/topscores/${year}/${tid}`, label: 'topScores' },
   300→    { url: `${RTN_BASE}/${g}/lineup/${year}/${tid}`, label: 'lineup' },
   301→    { url: `${RTN_BASE}/${g}/rostermain/${year}/${tid}/2`, label: 'individualHighs' },
   302→    { url: `${RTN_BASE}/${g}/rostermain/${year}/${tid}/3`, label: 'individualAverages' },
   303→  ];
   304→}
   305→
   306→// ============================================================================
   307→// Score Parsing Helpers
   308→// ============================================================================
   309→
   310→/**
   311→ * Parse a score value from RTN.
   312→ * - String scores are parsed to numbers (e.g., "9.9250" -> 9.925)
   313→ * - Negative scores (exhibition/scratch) are treated as null
   314→ * - null/undefined/empty string -> null
   315→ * - Results are rounded to 4 decimal places
   316→ *
   317→ * @param {*} val - Raw score value from RTN
   318→ * @returns {number|null}
   319→ */
   320→function parseScore(val) {
   321→  if (val === null || val === undefined || val === '' || val === '0.0000' || val === 0) return null;
   322→  const num = typeof val === 'number' ? val : parseFloat(val);
   323→  if (isNaN(num)) return null;
   324→  if (num < 0) return null; // Negative = exhibition/scratch
   325→  return Math.round(num * 10000) / 10000;
   326→}
   327→
   328→/**
   329→ * Coerce an RTN athlete ID to a string for consistent storage.
   330→ * RTN uses 'id', 'gid', or 'gymnast_id' depending on endpoint, and types vary (string or number).
   331→ *
   332→ * @param {*} val - Raw ID value
   333→ * @returns {string|null}
   334→ */
   335→function toRtnIdString(val) {
   336→  if (val === null || val === undefined || val === '') return null;
   337→  return String(val);
   338→}
   339→
   340→// ============================================================================
   341→// Normalization Functions (Task 4)
   342→// ============================================================================
   343→
   344→/**
   345→ * Normalize consistency data.
   346→ * Raw shape: { labels: [...], vts: [...], ubs: [...], bbs: [...], fxs: [...] }
   347→ * (men: fxs, phs, srs, vts, pbs, hbs)
   348→ *
   349→ * @param {Object} raw - Raw RTN consistency response
   350→ * @param {string} gender - "mens" or "womens"
   351→ * @returns {Object|null} { labels: string[], events: { VT: number[], UB: number[], ... } }
   352→ */
   353→function normalizeConsistency(raw, gender) {
   354→  if (!raw || typeof raw !== 'object') return null;
   355→
   356→  const labels = raw.labels || [];
   357→  const eventMap = getConsistencyEvents(gender);
   358→  const events = {};
   359→
   360→  for (const [rtnField, stdCode] of Object.entries(eventMap)) {
   361→    if (raw[rtnField] && Array.isArray(raw[rtnField])) {
   362→      events[stdCode] = raw[rtnField].map(v => parseScore(v));
   363→    }
   364→  }
   365→
   366→  if (Object.keys(events).length === 0) return null;
   367→
   368→  return { labels, events };
   369→}
   370→
   371→/**
   372→ * Normalize MVP data.
   373→ * Raw shape: array of athlete objects with sum fields (vsum, ubsum, etc.) and gid.
   374→ *
   375→ * @param {Array} raw - Raw RTN MVP response
   376→ * @param {string} gender - "mens" or "womens"
   377→ * @returns {Array|null} Array of { rtnId, firstName, lastName, fullName, events: {...}, total }
   378→ */
   379→function normalizeMVP(raw, gender) {
   380→  if (!raw || !Array.isArray(raw) || raw.length === 0) return null;
   381→
   382→  const eventMap = getMvpEvents(gender);
   383→
   384→  return raw.map(athlete => {
   385→    const events = {};
   386→    let total = 0;
   387→
   388→    for (const [rtnField, stdCode] of Object.entries(eventMap)) {
   389→      const score = parseScore(athlete[rtnField]);
   390→      events[stdCode] = score;
   391→      if (score !== null) total += score;
   392→    }
   393→
   394→    // Round total to 4 decimals to avoid floating-point artifacts
   395→    total = Math.round(total * 10000) / 10000;
   396→
   397→    return {
   398→      rtnId: toRtnIdString(athlete.gid),
   399→      firstName: (athlete.fname || '').trim(),
   400→      lastName: (athlete.lname || '').trim(),
   401→      fullName: `${(athlete.fname || '').trim()} ${(athlete.lname || '').trim()}`.trim(),
   402→      events,
   403→      total,
   404→    };
   405→  }).sort((a, b) => b.total - a.total);
   406→}
   407→
   408→/**
   409→ * Normalize top scores data.
   410→ * Raw shape: { data: [...top lineup entries...], max: number }
   411→ * Each entry has gymnast_id and event-named fields (vault, bars, beam, floor for women).
   412→ *
   413→ * @param {Object} raw - Raw RTN top scores response
   414→ * @param {string} gender - "mens" or "womens"
   415→ * @returns {Object|null} { theoreticalMax, scores: [...], events: { VT: [...], UB: [...], ... } }
   416→ */
   417→function normalizeTopScores(raw, gender) {
   418→  if (!raw || typeof raw !== 'object') return null;
   419→
   420→  const rawData = raw.data || raw;
   421→  if (!Array.isArray(rawData)) return null;
   422→
   423→  const eventMap = getTopScoreEvents(gender);
   424→  const theoreticalMax = parseScore(raw.max) || null;
   425→
   426→  // Group athletes by event
   427→  const events = {};
   428→  for (const stdCode of Object.values(eventMap)) {
   429→    events[stdCode] = [];
   430→  }
   431→
   432→  // Also build the flat scores array (top lineup entries)
   433→  const scores = rawData.map(entry => {
   434→    const row = {};
   435→    for (const [rtnField, stdCode] of Object.entries(eventMap)) {
   436→      row[rtnField] = entry[rtnField] || '';
   437→    }
   438→    return row;
   439→  });
   440→
   441→  // Build per-event top athletes
   442→  for (const [rtnField, stdCode] of Object.entries(eventMap)) {
   443→    // Collect athletes who have a score for this event
   444→    const athletesWithScores = rawData
   445→      .filter(entry => {
   446→        const score = parseScore(entry[rtnField]);
   447→        return score !== null;
   448→      })
   449→      .map(entry => ({
   450→        rtnId: toRtnIdString(entry.gymnast_id || entry.gid || entry.id),
   451→        firstName: (entry.fname || '').trim(),
   452→        lastName: (entry.lname || '').trim(),
   453→        fullName: `${(entry.fname || '').trim()} ${(entry.lname || '').trim()}`.trim(),
   454→        high: parseScore(entry[rtnField]),
   455→      }))
   456→      .sort((a, b) => (b.high || 0) - (a.high || 0));
   457→
   458→    events[stdCode] = athletesWithScores;
   459→  }
   460→
   461→  return { theoreticalMax, scores, events };
   462→}
   463→
   464→/**
   465→ * Normalize lineup data.
   466→ * Raw shape: array of athlete objects with binary meets arrays and id field.
   467→ *
   468→ * @param {Array} raw - Raw RTN lineup response
   469→ * @param {string} gender - "mens" or "womens"
   470→ * @returns {Array|null} Array of { rtnId, firstName, lastName, fullName, meets: number[], rate: number }
   471→ */
   472→function normalizeLineup(raw, gender) {
   473→  if (!raw || !Array.isArray(raw) || raw.length === 0) return null;
   474→
   475→  return raw.map(athlete => {
   476→    const meets = athlete.meets || [];
   477→    const totalMeets = meets.length;
   478→    const competed = meets.filter(m => m === 1 || m === '1').length;
   479→    const rate = totalMeets > 0 ? Math.round((competed / totalMeets) * 10000) / 10000 : 0;
   480→
   481→    return {
   482→      rtnId: toRtnIdString(athlete.id || athlete.gid),
   483→      firstName: (athlete.fname || '').trim(),
   484→      lastName: (athlete.lname || '').trim(),
   485→      fullName: `${(athlete.fname || '').trim()} ${(athlete.lname || '').trim()}`.trim(),
   486→      meets: meets.map(m => (m === 1 || m === '1') ? 1 : 0),
   487→      rate,
   488→    };
   489→  });
   490→}
   491→
   492→/**
   493→ * Normalize individual stats (highs or averages).
   494→ * Raw shape: { team: [...], ind: [...] } — NOT a flat array.
   495→ * The `ind` array contains athlete records with fields like maxv, maxub, maxbb, maxfx, maxaa (women)
   496→ * or maxfx, maxph, maxsr, maxvt, maxpb, maxhb, maxaa (men), plus gid.
   497→ *
   498→ * @param {Object} raw - Raw RTN rostermain response
   499→ * @param {string} gender - "mens" or "womens"
   500→ * @returns {Array|null} Array of { rtnId, firstName, lastName, fullName, events: { VT, UB, ... } }
   501→ */
   502→function normalizeIndividualStats(raw, gender) {
   503→  if (!raw || typeof raw !== 'object') return null;
   504→
   505→  // Handle { team, ind } structure
   506→  const athletes = raw.ind || raw;
   507→  if (!Array.isArray(athletes) || athletes.length === 0) return null;
   508→
   509→  const fieldMap = getIndividualFields(gender);
   510→
   511→  return athletes.map(athlete => {
   512→    const events = {};
   513→
   514→    for (const [rtnField, stdCode] of Object.entries(fieldMap)) {
   515→      events[stdCode] = parseScore(athlete[rtnField]);
   516→    }
   517→
   518→    return {
   519→      rtnId: toRtnIdString(athlete.gid || athlete.id),
   520→      firstName: (athlete.fname || '').trim(),
   521→      lastName: (athlete.lname || '').trim(),
   522→      fullName: `${(athlete.fname || '').trim()} ${(athlete.lname || '').trim()}`.trim(),
   523→      events,
   524→    };
   525→  });
   526→}
   527→
   528→/**
   529→ * Normalize individual highs (convenience wrapper).
   530→ * @param {Object} raw - Raw RTN rostermain/{tid}/2 response
   531→ * @param {string} gender
   532→ * @returns {Array|null}
   533→ */
   534→function normalizeIndividualHighs(raw, gender) {
   535→  return normalizeIndividualStats(raw, gender);
   536→}
   537→
   538→/**
   539→ * Normalize individual averages (convenience wrapper).
   540→ * @param {Object} raw - Raw RTN rostermain/{tid}/3 response
   541→ * @param {string} gender
   542→ * @returns {Array|null}
   543→ */
   544→function normalizeIndividualAverages(raw, gender) {
   545→  return normalizeIndividualStats(raw, gender);
   546→}
   547→
   548→/**
   549→ * Normalize team ranking from league results.
   550→ * The results endpoint returns ALL teams; we find ours by tid.
   551→ *
   552→ * Raw shape: { data: [...], schema: {...} }
   553→ * Each entry in data has: tid, rank, ave, high, rqs, conference, region, division, etc.
   554→ *
   555→ * @param {Object} raw - Raw RTN results response
   556→ * @param {string} gender - "mens" or "womens"
   557→ * @param {number|string} tid - RTN team ID to find
   558→ * @returns {Object|null} { rank, ave, high, rqs, conference, region, division }
   559→ */
   560→function normalizeTeamRanking(raw, gender, tid) {
   561→  if (!raw || typeof raw !== 'object') return null;
   562→
   563→  const results = raw.data || raw;
   564→  if (!Array.isArray(results) || results.length === 0) return null;
   565→
   566→  const tidStr = String(tid);
   567→  const team = results.find(t =>
   568→    String(t.tid) === tidStr || String(t.id) === tidStr
   569→  );
   570→
   571→  if (!team) {
   572→    console.warn(`[rtnStatsService] Team tid=${tid} not found in ranking results`);
   573→    return null;
   574→  }
   575→
   576→  return {
   577→    rank: team.rank ? String(team.rank) : null,
   578→    ave: team.ave ? String(team.ave) : null,
   579→    high: team.high ? String(team.high) : null,
   580→    rqs: team.rqs != null ? String(team.rqs) : null,
   581→    conference: team.conference || team.conf || null,
   582→    region: team.region || null,
   583→    division: team.division || team.div || null,
   584→  };
   585→}
   586→
   587→/**
   588→ * Normalize all raw fetch results for a team into the Firebase schema.
   589→ * Takes the results array from rateLimitedFetch and produces the full stats object.
   590→ *
   591→ * @param {Array<{label: string, data: Object|null, status: string}>} fetchResults
   592→ * @param {string} gender - "mens" or "womens"
   593→ * @param {number|string} tid - RTN team ID
   594→ * @returns {Object} { normalized: {...}, endpointStatus: {...} }
   595→ */
   596→function normalizeAllResults(fetchResults, gender, tid) {
   597→  const normalized = {};
   598→  const endpointStatus = {};
   599→
   600→  for (const result of fetchResults) {
   601→    endpointStatus[result.label] = result.status;
   602→
   603→    if (result.status !== 'ok' || !result.data) continue;
   604→
   605→    switch (result.label) {
   606→      case 'teamRanking':
   607→        normalized.teamRanking = normalizeTeamRanking(result.data, gender, tid);
   608→        break;
   609→      case 'consistency':
   610→        normalized.consistency = normalizeConsistency(result.data, gender);
   611→        break;
   612→      case 'mvp':
   613→        normalized.mvp = normalizeMVP(result.data, gender);
   614→        break;
   615→      case 'topScores':
   616→        normalized.topScores = normalizeTopScores(result.data, gender);
   617→        break;
   618→      case 'lineup':
   619→        normalized.lineup = normalizeLineup(result.data, gender);
   620→        break;
   621→      case 'individualHighs':
   622→        normalized.individualHighs = normalizeIndividualHighs(result.data, gender);
   623→        break;
   624→      case 'individualAverages':
   625→        normalized.individualAverages = normalizeIndividualAverages(result.data, gender);
   626→        break;
   627→    }
   628→  }
   629→
   630→  return { normalized, endpointStatus };
   631→}
