   633→// ============================================================================
   634→// Orchestration Functions (Task 5)
   635→// ============================================================================
   636→
   637→import productionConfigService from './productionConfigService.js';
   638→
   639→const DEDUP_WINDOW_MS = 60 * 1000; // 60 seconds — skip if another ingestion just completed
   640→
   641→/**
   642→ * Parse competition type to extract gender and team count.
   643→ * @param {string} compType - e.g., "womens-dual", "mens-tri", "womens-quad"
   644→ * @returns {{ gender: string, teamCount: number }}
   645→ */
   646→function parseCompetitionType(compType) {
   647→  if (!compType) return { gender: 'womens', teamCount: 2 };
   648→  const parts = compType.toLowerCase().split('-');
   649→  const gender = parts[0] === 'mens' ? 'mens' : 'womens';
   650→  let teamCount = 2;
   651→  if (parts[1]) {
   652→    const typeMap = { dual: 2, tri: 3, quad: 4, '5': 5, '6': 6 };
   653→    teamCount = typeMap[parts[1]] || 2;
   654→  }
   655→  return { gender, teamCount };
   656→}
   657→
   658→/**
   659→ * Build a teamsDatabase key from a team name and gender.
   660→ * Matches the client-side buildTeamKey() logic: lowercase, strip gender suffixes, hyphenate.
   661→ * @param {string} schoolName - e.g., "Oklahoma", "Stanford"
   662→ * @param {string} gender - "mens" or "womens"
   663→ * @returns {string} e.g., "oklahoma-womens"
   664→ */
   665→function buildTeamDbKey(schoolName, gender) {
   666→  if (!schoolName) return '';
   667→  const normalized = schoolName
   668→    .toLowerCase()
   669→    .replace(/['']/g, '')
   670→    .replace(/[^a-z0-9\s-]/g, '')
   671→    .replace(/-mens$/, '')
   672→    .replace(/-womens$/, '')
   673→    .replace(/ mens$/, '')
   674→    .replace(/ womens$/, '')
   675→    .replace(/ men$/, '')
   676→    .replace(/ women$/, '')
   677→    .replace(/\s+/g, '-')
   678→    .trim();
   679→  if (!normalized) return '';
   680→  const genderSuffix = gender === 'womens' ? 'womens' : 'mens';
   681→  return `${normalized}-${genderSuffix}`;
   682→}
   683→
   684→/**
   685→ * Check if a team's stats are stale (older than STALENESS_TTL).
   686→ * @param {string} teamKey - teamsDatabase key, e.g., "oklahoma-womens"
   687→ * @returns {Promise<{ isStale: boolean, fetchedAt: string|null, withinDedup: boolean }>}
   688→ */
   689→async function checkStaleness(teamKey) {
   690→  const db = productionConfigService.getDb();
   691→  if (!db) return { isStale: true, fetchedAt: null, withinDedup: false };
   692→
   693→  try {
   694→    const snapshot = await db.ref(`teamsDatabase/stats/${teamKey}/meta/fetchedAt`).once('value');
   695→    const fetchedAt = snapshot.val();
   696→
   697→    if (!fetchedAt) return { isStale: true, fetchedAt: null, withinDedup: false };
   698→
   699→    const fetchedTime = new Date(fetchedAt).getTime();
   700→    const now = Date.now();
   701→    const age = now - fetchedTime;
   702→
   703→    return {
   704→      isStale: age > STALENESS_TTL,
   705→      fetchedAt,
   706→      withinDedup: age < DEDUP_WINDOW_MS,
   707→    };
   708→  } catch (err) {
   709→    console.error(`[rtnStatsService] Error checking staleness for ${teamKey}:`, err.message);
   710→    return { isStale: true, fetchedAt: null, withinDedup: false };
   711→  }
   712→}
   713→
   714→/**
   715→ * Ingest stats for a single team: fetch all RTN endpoints, normalize, and write to Firebase.
   716→ *
   717→ * @param {string} teamKey - teamsDatabase key, e.g., "oklahoma-womens"
   718→ * @param {string|number} rtnId - RTN team ID
   719→ * @param {string} gender - "mens" or "womens"
   720→ * @param {number} year - Season year
   721→ * @param {Object} [io] - Socket.IO server instance for progress events
   722→ * @param {string} [compId] - Competition ID for progress events
   723→ * @returns {Promise<{ status: string, endpointStatus: Object, errors: Object|null }>}
   724→ */
   725→async function ingestTeamStats(teamKey, rtnId, gender, year, io, compId) {
   726→  const db = productionConfigService.getDb();
   727→  if (!db) {
   728→    return { status: 'error', endpointStatus: {}, errors: { firebase: 'Firebase not available' } };
   729→  }
   730→
   731→  const tidStr = String(rtnId);
   732→
   733→  // Get current week for team ranking endpoint
   734→  let week;
   735→  try {
   736→    week = await getCurrentWeek(gender, year);
   737→  } catch (err) {
   738→    console.warn(`[rtnStatsService] Failed to get week, using 1: ${err.message}`);
   739→    week = 1;
   740→  }
   741→
   742→  // Build URLs and fetch all endpoints
   743→  const urls = buildTeamStatUrls(gender, year, tidStr, week);
   744→
   745→  const onProgress = (label, step, total, status) => {
   746→    console.log(`[rtnStatsService] ${teamKey}: ${label} (${step}/${total}) - ${status}`);
   747→    if (io && compId) {
   748→      const roomName = `competition:${compId}`;
   749→      io.to(roomName).emit('rtnStatsProgress', {
   750→        compId,
   751→        teamKey,
   752→        endpoint: label,
   753→        step,
   754→        total,
   755→        status,
   756→      });
   757→    }
   758→  };
   759→
   760→  const fetchResults = await rateLimitedFetch(urls, onProgress);
   761→
   762→  // Normalize all results
   763→  const { normalized, endpointStatus } = normalizeAllResults(fetchResults, gender, tidStr);
   764→
   765→  // Determine overall status
   766→  const statuses = Object.values(endpointStatus);
   767→  const errorCount = statuses.filter(s => s === 'error').length;
   768→  let overallStatus;
   769→  if (errorCount === statuses.length) {
   770→    overallStatus = 'error';
   771→  } else if (errorCount > 0) {
   772→    overallStatus = 'partial';
   773→  } else {
   774→    overallStatus = 'complete';
   775→  }
   776→
   777→  // Build error details
   778→  const errors = {};
   779→  for (const result of fetchResults) {
   780→    if (result.status === 'error') {
   781→      errors[result.label] = result.error || 'Unknown error';
   782→    }
   783→  }
   784→
   785→  // Build meta
   786→  const meta = {
   787→    fetchedAt: new Date().toISOString(),
   788→    rtnId: tidStr,
   789→    year,
   790→    gender,
   791→    week,
   792→    status: overallStatus,
   793→    errors: Object.keys(errors).length > 0 ? errors : null,
   794→    endpointStatus,
   795→  };
   796→
   797→  // Write to Firebase: teamsDatabase/stats/{teamKey}/
   798→  try {
   799→    const statsRef = db.ref(`teamsDatabase/stats/${teamKey}`);
   800→    const writeData = { ...normalized, meta };
   801→    await statsRef.set(writeData);
   802→    console.log(`[rtnStatsService] Wrote stats for ${teamKey} (status: ${overallStatus})`);
   803→  } catch (err) {
   804→    console.error(`[rtnStatsService] Failed to write stats for ${teamKey}:`, err.message);
   805→    return { status: 'error', endpointStatus, errors: { ...errors, firebase: err.message } };
   806→  }
   807→
   808→  return { status: overallStatus, endpointStatus, errors: Object.keys(errors).length > 0 ? errors : null };
   809→}
   810→
   811→/**
   812→ * Ingest RTN stats for all teams in a competition.
   813→ * Checks staleness, deduplicates, fetches if needed, writes to shared store.
   814→ *
   815→ * @param {string} compId - Competition ID
   816→ * @param {Object} [io] - Socket.IO server instance for progress/result events
   817→ * @returns {Promise<{ success: boolean, teams: Object, error?: string }>}
   818→ */
   819→async function ingestCompetitionStats(compId, io) {
   820→  const db = productionConfigService.getDb();
   821→  if (!db) {
   822→    return { success: false, teams: {}, error: 'Firebase not available' };
   823→  }
   824→
   825→  console.log(`[rtnStatsService] Starting ingestion for competition ${compId}`);
   826→
   827→  // Read competition config
   828→  let config;
   829→  try {
   830→    const configSnapshot = await db.ref(`competitions/${compId}/config`).once('value');
   831→    config = configSnapshot.val();
   832→  } catch (err) {
   833→    console.error(`[rtnStatsService] Failed to read config for ${compId}:`, err.message);
   834→    return { success: false, teams: {}, error: `Failed to read config: ${err.message}` };
   835→  }
   836→
   837→  if (!config) {
   838→    return { success: false, teams: {}, error: 'Competition config not found' };
   839→  }
   840→
   841→  // Extract gender and team count
   842→  const { gender, teamCount } = parseCompetitionType(config.compType);
   843→  const year = new Date().getFullYear();
   844→
   845→  // Build team name list from config
   846→  const teamNames = [];
   847→  for (let i = 1; i <= teamCount; i++) {
   848→    const name = config[`team${i}Name`];
   849→    if (name) teamNames.push({ index: i, name });
   850→  }
   851→
   852→  if (teamNames.length === 0) {
   853→    return { success: false, teams: {}, error: 'No team names found in config' };
   854→  }
   855→
   856→  const teamResults = {};
   857→
   858→  for (const { index, name } of teamNames) {
   859→    const teamKey = buildTeamDbKey(name, gender);
   860→    if (!teamKey) {
   861→      console.warn(`[rtnStatsService] Could not build team key for "${name}"`);
   862→      teamResults[`team${index}`] = { teamKey: null, status: 'error', error: 'Invalid team name' };
   863→      continue;
   864→    }
   865→
   866→    // Look up RTN ID from teamsDatabase
   867→    let rtnId;
   868→    try {
   869→      const rtnIdSnapshot = await db.ref(`teamsDatabase/teams/${teamKey}/rtnId`).once('value');
   870→      rtnId = rtnIdSnapshot.val();
   871→    } catch (err) {
   872→      console.error(`[rtnStatsService] Failed to read rtnId for ${teamKey}:`, err.message);
   873→    }
   874→
   875→    if (!rtnId) {
   876→      console.warn(`[rtnStatsService] No RTN ID for team ${teamKey} — skipping`);
   877→      // Write error to meta so the UI can see it
   878→      try {
   879→        await db.ref(`teamsDatabase/stats/${teamKey}/meta`).update({
   880→          status: 'error',
   881→          errors: { rtnId: 'RTN ID not set. Run Media Manager team setup first.' },
   882→          fetchedAt: new Date().toISOString(),
   883→        });
   884→      } catch (e) {
   885→        // Best effort
   886→      }
   887→      teamResults[`team${index}`] = { teamKey, status: 'error', error: 'Missing RTN ID' };
   888→      continue;
   889→    }
   890→
   891→    // Check staleness
   892→    const staleness = await checkStaleness(teamKey);
   893→
   894→    if (staleness.withinDedup) {
   895→      console.log(`[rtnStatsService] ${teamKey}: Recently ingested (dedup window), skipping`);
   896→      teamResults[`team${index}`] = { teamKey, status: 'skipped', reason: 'dedup' };
   897→      continue;
   898→    }
   899→
   900→    if (!staleness.isStale) {
   901→      console.log(`[rtnStatsService] ${teamKey}: Stats are fresh (fetched ${staleness.fetchedAt}), skipping`);
   902→      teamResults[`team${index}`] = { teamKey, status: 'skipped', reason: 'fresh' };
   903→      continue;
   904→    }
   905→
   906→    // Stats are stale or missing — fetch from RTN
   907→    console.log(`[rtnStatsService] ${teamKey}: Stats are stale/missing, fetching from RTN...`);
   908→    const result = await ingestTeamStats(teamKey, rtnId, gender, year, io, compId);
   909→    teamResults[`team${index}`] = { teamKey, ...result };
   910→  }
   911→
   912→  const allStatuses = Object.values(teamResults).map(r => r.status);
   913→  const allErrors = allStatuses.every(s => s === 'error');
   914→
   915→  const success = !allErrors;
   916→
   917→  console.log(`[rtnStatsService] Ingestion complete for ${compId}: ${JSON.stringify(teamResults)}`);
   918→
   919→  return { success, teams: teamResults };
   920→}
   921→
   922→// ============================================================================
   923→// Config Sync (Task 6)
   924→// ============================================================================
   925→
   926→/**
   927→ * Sync RTN stats to competition config fields, respecting manual override locks.
   928→ *
   929→ * For each team in the competition, reads `teamsDatabase/stats/{teamKey}/teamRanking`
   930→ * and writes `team{N}Ave`, `team{N}High`, `team{N}Con` to the competition config.
   931→ * Locked fields (at `competitions/{compId}/config/_locks`) are skipped.
   932→ *
   933→ * @param {string} compId - Competition ID
   934→ * @returns {Promise<{ success: boolean, synced: Object, skipped: Object, error?: string }>}
   935→ */
   936→async function syncStatsToConfig(compId) {
   937→  const db = productionConfigService.getDb();
   938→  if (!db) {
   939→    return { success: false, synced: {}, skipped: {}, error: 'Firebase not available' };
   940→  }
   941→
   942→  console.log(`[rtnStatsService] syncStatsToConfig for competition ${compId}`);
   943→
   944→  // Read competition config
   945→  let config;
   946→  try {
   947→    const configSnapshot = await db.ref(`competitions/${compId}/config`).once('value');
   948→    config = configSnapshot.val();
   949→  } catch (err) {
   950→    console.error(`[rtnStatsService] Failed to read config for ${compId}:`, err.message);
   951→    return { success: false, synced: {}, skipped: {}, error: `Failed to read config: ${err.message}` };
   952→  }
   953→
   954→  if (!config) {
   955→    return { success: false, synced: {}, skipped: {}, error: 'Competition config not found' };
   956→  }
   957→
   958→  // Read locks — default to empty object if null/missing
   959→  const locks = config._locks || {};
   960→
   961→  // Extract gender and team count
   962→  const { gender, teamCount } = parseCompetitionType(config.compType);
   963→
   964→  const synced = {};
   965→  const skipped = {};
   966→
   967→  for (let i = 1; i <= teamCount; i++) {
   968→    const teamName = config[`team${i}Name`];
   969→    if (!teamName) continue;
   970→
   971→    const teamKey = buildTeamDbKey(teamName, gender);
   972→    if (!teamKey) {
   973→      console.warn(`[rtnStatsService] syncStatsToConfig: Could not build team key for "${teamName}"`);
   974→      continue;
   975→    }
   976→
   977→    // Read team ranking from shared stats store
   978→    let teamRanking = null;
   979→    try {
   980→      const rankingSnapshot = await db.ref(`teamsDatabase/stats/${teamKey}/teamRanking`).once('value');
   981→      teamRanking = rankingSnapshot.val();
   982→    } catch (err) {
   983→      console.warn(`[rtnStatsService] Failed to read teamRanking for ${teamKey}:`, err.message);
   984→    }
   985→
   986→    if (!teamRanking) {
   987→      console.log(`[rtnStatsService] No teamRanking data for ${teamKey}, skipping config sync`);
   988→      skipped[`team${i}`] = { teamKey, reason: 'no ranking data' };
   989→      continue;
   990→    }
   991→
   992→    // Build updates for this team, respecting locks
   993→    const updates = {};
   994→    const teamSynced = [];
   995→    const teamSkipped = [];
   996→
   997→    // team{N}Ave — from ranking average
   998→    const aveField = `team${i}Ave`;
   999→    if (locks[aveField] === true) {
  1000→      teamSkipped.push(aveField);
  1001→    } else if (teamRanking.ave) {
  1002→      updates[aveField] = teamRanking.ave;
  1003→      teamSynced.push(aveField);
  1004→    }
  1005→
  1006→    // team{N}High — from ranking high
  1007→    const highField = `team${i}High`;
  1008→    if (locks[highField] === true) {
  1009→      teamSkipped.push(highField);
  1010→    } else if (teamRanking.high) {
  1011→      updates[highField] = teamRanking.high;
  1012→      teamSynced.push(highField);
  1013→    }
  1014→
  1015→    // team{N}Con — overall ranking string (e.g., "#1", "#3(t)")
  1016→    const conField = `team${i}Con`;
  1017→    if (locks[conField] === true) {
  1018→      teamSkipped.push(conField);
  1019→    } else if (teamRanking.rank) {
  1020→      updates[conField] = `#${teamRanking.rank}`;
  1021→      teamSynced.push(conField);
  1022→    }
  1023→
  1024→    // Write updates to config
  1025→    if (Object.keys(updates).length > 0) {
  1026→      try {
  1027→        await db.ref(`competitions/${compId}/config`).update(updates);
  1028→        console.log(`[rtnStatsService] Synced config for team${i} (${teamKey}): ${teamSynced.join(', ')}`);
  1029→      } catch (err) {
  1030→        console.error(`[rtnStatsService] Failed to write config for team${i}:`, err.message);
  1031→      }
  1032→    }
  1033→
  1034→    if (teamSynced.length > 0) synced[`team${i}`] = { teamKey, fields: teamSynced };
  1035→    if (teamSkipped.length > 0) skipped[`team${i}`] = { teamKey, fields: teamSkipped, reason: 'locked' };
  1036→  }
  1037→
  1038→  console.log(`[rtnStatsService] syncStatsToConfig complete: synced=${JSON.stringify(synced)}, skipped=${JSON.stringify(skipped)}`);
  1039→
  1040→  return { success: true, synced, skipped };
  1041→}
  1042→
  1043→// ============================================================================
  1044→// Show-Start Snapshot (Task 7)
  1045→// ============================================================================
  1046→
  1047→/**
  1048→ * Copy shared stats from `teamsDatabase/stats/{teamKey}/` to
  1049→ * `competitions/{compId}/rtnStats/team{N}/` for archival at show start.
  1050→ *
  1051→ * The snapshot freezes stats so mid-show refreshes for other competitions
  1052→ * don't change the data AI services read during a live broadcast.
  1053→ *
  1054→ * @param {string} compId - Competition ID
  1055→ * @returns {Promise<{ success: boolean, teamsSnapshotted: number, error?: string }>}
  1056→ */
  1057→async function snapshotStatsForCompetition(compId) {
  1058→  const db = productionConfigService.getDb();
  1059→  if (!db) {
  1060→    return { success: false, teamsSnapshotted: 0, error: 'Firebase not available' };
  1061→  }
  1062→
  1063→  console.log(`[rtnStatsService] Taking stats snapshot for competition ${compId}`);
  1064→
  1065→  // Read competition config to find team names
  1066→  let config;
  1067→  try {
  1068→    const configSnapshot = await db.ref(`competitions/${compId}/config`).once('value');
  1069→    config = configSnapshot.val();
  1070→  } catch (err) {
  1071→    console.error(`[rtnStatsService] Failed to read config for snapshot ${compId}:`, err.message);
  1072→    return { success: false, teamsSnapshotted: 0, error: `Failed to read config: ${err.message}` };
  1073→  }
  1074→
  1075→  if (!config) {
  1076→    return { success: false, teamsSnapshotted: 0, error: 'Competition config not found' };
  1077→  }
  1078→
  1079→  const { gender, teamCount } = parseCompetitionType(config.compType);
  1080→  const snapshotData = {
  1081→    snapshotTakenAt: new Date().toISOString(),
  1082→  };
  1083→  let teamsSnapshotted = 0;
  1084→
  1085→  for (let i = 1; i <= teamCount; i++) {
  1086→    const name = config[`team${i}Name`];
  1087→    if (!name) continue;
  1088→
  1089→    const teamKey = buildTeamDbKey(name, gender);
  1090→    if (!teamKey) continue;
  1091→
  1092→    try {
  1093→      const statsSnapshot = await db.ref(`teamsDatabase/stats/${teamKey}`).once('value');
  1094→      const stats = statsSnapshot.val();
  1095→      if (stats) {
  1096→        snapshotData[`team${i}`] = stats;
  1097→        teamsSnapshotted++;
  1098→      }
  1099→    } catch (err) {
  1100→      console.warn(`[rtnStatsService] Failed to read stats for ${teamKey} during snapshot:`, err.message);
  1101→    }
  1102→  }
  1103→
  1104→  // Write snapshot to competition
  1105→  try {
  1106→    await db.ref(`competitions/${compId}/rtnStats`).set(snapshotData);
  1107→    console.log(`[rtnStatsService] Snapshot complete for ${compId}: ${teamsSnapshotted} teams`);
  1108→  } catch (err) {
  1109→    console.error(`[rtnStatsService] Failed to write snapshot for ${compId}:`, err.message);
  1110→    return { success: false, teamsSnapshotted: 0, error: `Failed to write snapshot: ${err.message}` };
  1111→  }
  1112→
  1113→  return { success: true, teamsSnapshotted };
  1114→}
  1115→
  1116→// ============================================================================
  1117→// League Rankings (Task 15)
  1118→// ============================================================================
  1119→
  1120→/**
  1121→ * Normalize team rankings from the results endpoint.
  1122→ * Raw shape: { data: [...], schema: {...} }
  1123→ * Each entry: { tid, rank, team_name/name, ave, high, rqs, conference, region, division, ... }
  1124→ *
  1125→ * @param {Object} raw - Raw RTN results response
  1126→ * @returns {Array|null} Array of { rank, name, tid, ave, high, rqs, conference, region, division }
  1127→ */
  1128→function normalizeTeamRankings(raw) {
  1129→  if (!raw || typeof raw !== 'object') return null;
  1130→
  1131→  const results = raw.data || raw;
  1132→  if (!Array.isArray(results) || results.length === 0) return null;
  1133→
  1134→  return results.map(team => ({
  1135→    rank: team.rank ? String(team.rank) : null,
  1136→    name: team.team_name || team.name || team.team || '',
  1137→    tid: team.tid ? Number(team.tid) : (team.id ? Number(team.id) : null),
  1138→    ave: team.ave ? String(team.ave) : null,
  1139→    high: team.high ? String(team.high) : null,
  1140→    rqs: team.rqs != null ? String(team.rqs) : null,
  1141→    conference: team.conference || team.conf || null,
  1142→    region: team.region || null,
  1143→    division: team.division || team.div || null,
  1144→  }));
  1145→}
  1146→
  1147→/**
  1148→ * Normalize individual rankings for a single event.
  1149→ * Raw shape: { data: [...], schema: {...} }
  1150→ * Each entry: { gid, fname, lname, team_name, ave, high, rqs, conference, rank, tid, ... }
  1151→ *
  1152→ * @param {Object} raw - Raw RTN individual results response
  1153→ * @returns {Array|null} Array of { rank, firstName, lastName, fullName, rtnId, team, teamId, ave, high, rqs, conference }
  1154→ */
  1155→function normalizeIndividualRankings(raw) {
  1156→  if (!raw || typeof raw !== 'object') return null;
  1157→
  1158→  const results = raw.data || raw;
  1159→  if (!Array.isArray(results) || results.length === 0) return null;
  1160→
  1161→  return results.map(athlete => ({
  1162→    rank: athlete.rank ? String(athlete.rank) : null,
  1163→    firstName: (athlete.fname || '').trim(),
  1164→    lastName: (athlete.lname || '').trim(),
  1165→    fullName: `${(athlete.fname || '').trim()} ${(athlete.lname || '').trim()}`.trim(),
  1166→    rtnId: toRtnIdString(athlete.gid || athlete.id),
  1167→    team: athlete.team_name || athlete.team || '',
  1168→    teamId: athlete.tid ? Number(athlete.tid) : null,
