  1187→ */
  1188→async function fetchLeagueRankings(gender, year, week) {
  1189→  const db = productionConfigService.getDb();
  1190→  if (!db) {
  1191→    return { success: false, gender, week: week || 0, teamCount: 0, individualEvents: 0, error: 'Firebase not available' };
  1192→  }
  1193→
  1194→  const resolvedYear = year || new Date().getFullYear();
  1195→  let resolvedWeek = week;
  1196→
  1197→  // Determine current week if not provided
  1198→  if (!resolvedWeek) {
  1199→    try {
  1200→      resolvedWeek = await getCurrentWeek(gender, resolvedYear);
  1201→    } catch (err) {
  1202→      console.error(`[rtnStatsService] Failed to get current week for rankings: ${err.message}`);
  1203→      return { success: false, gender, week: 0, teamCount: 0, individualEvents: 0, error: `Failed to determine current week: ${err.message}` };
  1204→    }
  1205→  }
  1206→
  1207→  const cacheKey = `${gender}-${resolvedYear}-${resolvedWeek}`;
  1208→  console.log(`[rtnStatsService] Fetching league rankings: ${cacheKey}`);
  1209→
  1210→  // Check existing cache TTL
  1211→  try {
  1212→    const cacheSnapshot = await db.ref(`rtnCache/rankings/${cacheKey}/timestamp`).once('value');
  1213→    const cachedTimestamp = cacheSnapshot.val();
  1214→    if (cachedTimestamp && (Date.now() - cachedTimestamp) < RANKINGS_CACHE_TTL) {
  1215→      console.log(`[rtnStatsService] Rankings cache still fresh for ${cacheKey}, skipping fetch`);
  1216→      // Read existing data to return counts
  1217→      const existingSnapshot = await db.ref(`rtnCache/rankings/${cacheKey}`).once('value');
  1218→      const existing = existingSnapshot.val();
  1219→      const teamCount = existing?.team ? (Array.isArray(existing.team) ? existing.team.length : Object.keys(existing.team).length) : 0;
  1220→      const individualEvents = existing?.individual ? Object.keys(existing.individual).length : 0;
  1221→      return { success: true, gender, week: resolvedWeek, teamCount, individualEvents, cached: true };
  1222→    }
  1223→  } catch (err) {
  1224→    // Cache check failed, proceed with fetch
  1225→  }
  1226→
  1227→  // Build URLs: team rankings + individual rankings per event
  1228→  const g = getGenderPath(gender);
  1229→  const type = getTeamRankingType(gender);
  1230→  const individualEvents = getIndividualEventNumbers(gender);
  1231→
  1232→  const urls = [
  1233→    { url: `${RTN_BASE}/${g}/results/${resolvedYear}/${resolvedWeek}/0/${type}`, label: 'team' },
  1234→  ];
  1235→
  1236→  // Add individual ranking URLs for each event
  1237→  for (const [eventNum, eventCode] of Object.entries(individualEvents)) {
  1238→    urls.push({
  1239→      url: `${RTN_BASE}/${g}/results/${resolvedYear}/${resolvedWeek}/1/${eventNum}`,
  1240→      label: `individual-${eventCode}`,
  1241→    });
  1242→  }
  1243→
  1244→  console.log(`[rtnStatsService] Fetching ${urls.length} ranking endpoints for ${cacheKey}`);
  1245→
  1246→  const fetchResults = await rateLimitedFetch(urls);
  1247→
  1248→  // Normalize team rankings
  1249→  const teamResult = fetchResults.find(r => r.label === 'team');
  1250→  let teamRankings = null;
  1251→  if (teamResult && teamResult.status === 'ok' && teamResult.data) {
  1252→    teamRankings = normalizeTeamRankings(teamResult.data);
  1253→  }
  1254→
  1255→  // Normalize individual rankings per event
  1256→  const individualRankings = {};
  1257→  let individualEventCount = 0;
  1258→  for (const [eventNum, eventCode] of Object.entries(individualEvents)) {
  1259→    const result = fetchResults.find(r => r.label === `individual-${eventCode}`);
  1260→    if (result && result.status === 'ok' && result.data) {
  1261→      const normalized = normalizeIndividualRankings(result.data);
  1262→      if (normalized) {
  1263→        individualRankings[eventCode] = normalized;
  1264→        individualEventCount++;
  1265→      }
  1266→    }
  1267→  }
  1268→
  1269→  // Build cache data
  1270→  const cacheData = {
  1271→    timestamp: Date.now(),
  1272→    fetchedAt: new Date().toISOString(),
  1273→    team: teamRankings || [],
  1274→    individual: individualRankings,
  1275→  };
  1276→
  1277→  // Write to Firebase
  1278→  try {
  1279→    await db.ref(`rtnCache/rankings/${cacheKey}`).set(cacheData);
  1280→    console.log(`[rtnStatsService] Wrote rankings cache for ${cacheKey}: ${teamRankings?.length || 0} teams, ${individualEventCount} events`);
  1281→  } catch (err) {
  1282→    console.error(`[rtnStatsService] Failed to write rankings cache for ${cacheKey}:`, err.message);
  1283→    return { success: false, gender, week: resolvedWeek, teamCount: 0, individualEvents: 0, error: `Failed to write cache: ${err.message}` };
  1284→  }
  1285→
  1286→  return {
  1287→    success: true,
  1288→    gender,
  1289→    week: resolvedWeek,
  1290→    teamCount: teamRankings?.length || 0,
  1291→    individualEvents: individualEventCount,
  1292→  };
  1293→}
