    io.emit('vmReady', data);
    io.emit('vmPoolStatus', vmPoolManager.getPoolStatus());
  });

  vmPoolManager.on('vmStopping', (data) => {
    console.log(`[VMPool] VM ${data.vmId} is stopping`);
    io.emit('vmStopping', data);
    io.emit('vmPoolStatus', vmPoolManager.getPoolStatus());
  });

  vmPoolManager.on('vmStopped', (data) => {
