   222→        <div className="bg-zinc-900/50 rounded p-2">
   223→          <div className="text-[10px] text-zinc-500 uppercase tracking-wide mb-1">Top Scores</div>
   224→          {topScores.theoreticalMax && (
   225→            <div className="text-[11px] mb-2">
   226→              <span className="text-zinc-400">Theoretical Max: </span>
   227→              <span className="text-green-400 font-bold">{formatScore(topScores.theoreticalMax)}</span>
   228→            </div>
   229→          )}
   230→          {topScores.events && (
   231→            <div className="grid grid-cols-2 gap-1">
   232→              {events.filter(e => e !== 'AA').map(event => {
   233→                const eventAthletes = toArray(topScores.events?.[event]);
   234→                if (!eventAthletes.length) return null;
   235→                return (
   236→                  <div key={event} className="text-[10px]">
   237→                    <span className="text-zinc-500">{event}: </span>
   238→                    <span className="text-zinc-300">
   239→                      {eventAthletes.slice(0, 2).map(a =>
   240→                        `${a.fullName || a.lastName || '?'} (${a.high || '?'})`
   241→                      ).join(', ')}
   242→                    </span>
   243→                  </div>
   244→                );
   245→              })}
   246→            </div>
   247→          )}
   248→        </div>
   249→      )}
   250→
   251→      {!ranking && !mvp.length && !topScores && (
   252→        <div className="text-[11px] text-zinc-500 italic text-center py-2">
   253→          No overview data available.
   254→        </div>
   255→      )}
   256→    </div>
   257→  );
   258→}
   259→
   260→// --- Athletes Tab: Per-athlete averages, highs, lineup rate ---
   261→function AthletesTab({ stats, events, eventFilter, setEventFilter, sortBy, setSortBy, sortDir, setSortDir }) {
   262→  const highs = toArray(stats?.individualHighs);
   263→  const averages = toArray(stats?.individualAverages);
   264→  const lineup = toArray(stats?.lineup);
   265→  const mvp = toArray(stats?.mvp);
   266→
   267→  // Merge athlete data from all sources
   268→  const athletes = mergeAthleteData(highs, averages, lineup, mvp);
   269→
   270→  // Filter by event
   271→  const filtered = eventFilter === 'ALL'
   272→    ? athletes
   273→    : athletes.filter(a => {
   274→        const avgVal = a.averages?.[eventFilter];
   275→        const highVal = a.highs?.[eventFilter];
   276→        return (avgVal !== null && avgVal !== undefined) || (highVal !== null && highVal !== undefined);
   277→      });
   278→
   279→  // Sort
   280→  const sorted = [...filtered].sort((a, b) => {
   281→    let aVal, bVal;
   282→    if (sortBy === 'total') {
   283→      aVal = a.mvpTotal || 0;
   284→      bVal = b.mvpTotal || 0;
   285→    } else if (sortBy === 'rate') {
   286→      aVal = a.lineupRate || 0;
   287→      bVal = b.lineupRate || 0;
   288→    } else if (sortBy === 'name') {
   289→      return sortDir === 'asc'
   290→        ? (a.fullName || '').localeCompare(b.fullName || '')
   291→        : (b.fullName || '').localeCompare(a.fullName || '');
   292→    } else {
   293→      // Sort by event average
   294→      aVal = a.averages?.[sortBy] || 0;
   295→      bVal = b.averages?.[sortBy] || 0;
   296→    }
   297→    return sortDir === 'desc' ? bVal - aVal : aVal - bVal;
   298→  });
   299→
   300→  const toggleSort = (col) => {
   301→    if (sortBy === col) {
   302→      setSortDir(sortDir === 'desc' ? 'asc' : 'desc');
   303→    } else {
   304→      setSortBy(col);
   305→      setSortDir('desc');
   306→    }
   307→  };
   308→
   309→  const SortArrow = ({ col }) => {
   310→    if (sortBy !== col) return null;
   311→    return <span className="ml-0.5">{sortDir === 'desc' ? '\u25BC' : '\u25B2'}</span>;
   312→  };
   313→
   314→  if (!athletes.length) {
   315→    return (
   316→      <div className="text-[11px] text-zinc-500 italic text-center py-4">
   317→        No individual athlete stats available.
   318→      </div>
   319→    );
   320→  }
   321→
   322→  return (
   323→    <div>
   324→      {/* Event filter */}
   325→      <div className="flex gap-1 mb-2 flex-wrap">
   326→        <button
   327→          onClick={() => setEventFilter('ALL')}
   328→          className={`px-1.5 py-0.5 rounded text-[10px] font-medium transition-colors ${
   329→            eventFilter === 'ALL' ? 'bg-blue-600 text-white' : 'bg-zinc-700 text-zinc-400 hover:text-zinc-200'
   330→          }`}
   331→        >
   332→          All
   333→        </button>
   334→        {events.map(event => (
   335→          <button
   336→            key={event}
   337→            onClick={() => setEventFilter(event)}
   338→            className={`px-1.5 py-0.5 rounded text-[10px] font-medium transition-colors ${
   339→              eventFilter === event ? 'bg-blue-600 text-white' : 'bg-zinc-700 text-zinc-400 hover:text-zinc-200'
   340→            }`}
   341→          >
   342→            {event}
   343→          </button>
   344→        ))}
   345→      </div>
   346→
   347→      {/* Athlete table */}
   348→      <div className="overflow-x-auto">
   349→        <table className="w-full text-[10px]">
   350→          <thead>
   351→            <tr className="text-zinc-500 border-b border-zinc-700">
   352→              <th
   353→                className="text-left py-1 pr-2 cursor-pointer hover:text-zinc-300"
   354→                onClick={() => toggleSort('name')}
   355→              >
   356→                Athlete<SortArrow col="name" />
   357→              </th>
   358→              {(eventFilter === 'ALL' ? events.filter(e => e !== 'AA') : [eventFilter]).map(event => (
   359→                <th
   360→                  key={`avg-${event}`}
   361→                  className="text-right py-1 px-1 cursor-pointer hover:text-zinc-300"
   362→                  onClick={() => toggleSort(event)}
   363→                >
   364→                  {event} Avg<SortArrow col={event} />
   365→                </th>
   366→              ))}
   367→              {(eventFilter === 'ALL' ? events.filter(e => e !== 'AA') : [eventFilter]).map(event => (
   368→                <th key={`hi-${event}`} className="text-right py-1 px-1">
   369→                  {event} Hi
   370→                </th>
   371→              ))}
   372→              <th
   373→                className="text-right py-1 px-1 cursor-pointer hover:text-zinc-300"
   374→                onClick={() => toggleSort('rate')}
   375→              >
   376→                Rate<SortArrow col="rate" />
   377→              </th>
   378→              <th
   379→                className="text-right py-1 pl-1 cursor-pointer hover:text-zinc-300"
   380→                onClick={() => toggleSort('total')}
   381→              >
   382→                MVP<SortArrow col="total" />
   383→              </th>
   384→            </tr>
   385→          </thead>
   386→          <tbody>
   387→            {sorted.map((athlete, i) => (
   388→              <tr key={athlete.rtnId || i} className="border-b border-zinc-800 hover:bg-zinc-800/50">
   389→                <td className="py-1 pr-2 text-white whitespace-nowrap">{athlete.fullName}</td>
   390→                {(eventFilter === 'ALL' ? events.filter(e => e !== 'AA') : [eventFilter]).map(event => (
   391→                  <td key={`avg-${event}`} className="text-right py-1 px-1 text-zinc-300">
   392→                    {formatScore(athlete.averages?.[event])}
   393→                  </td>
   394→                ))}
   395→                {(eventFilter === 'ALL' ? events.filter(e => e !== 'AA') : [eventFilter]).map(event => (
   396→                  <td key={`hi-${event}`} className="text-right py-1 px-1 text-zinc-400">
   397→                    {formatScore(athlete.highs?.[event])}
   398→                  </td>
   399→                ))}
   400→                <td className="text-right py-1 px-1 text-zinc-400">
   401→                  {athlete.lineupRate !== null ? `${Math.round(athlete.lineupRate * 100)}%` : '-'}
   402→                </td>
   403→                <td className="text-right py-1 pl-1 text-blue-400 font-medium">
   404→                  {formatScore(athlete.mvpTotal)}
   405→                </td>
   406→              </tr>
   407→            ))}
   408→          </tbody>
   409→        </table>
   410→      </div>
   411→      <div className="text-[10px] text-zinc-600 mt-1">{sorted.length} athletes</div>
   412→    </div>
   413→  );
   414→}
   415→
   416→// --- Consistency Tab: Event score trends over time ---
   417→function ConsistencyTab({ stats, events }) {
   418→  const consistency = stats?.consistency;
   419→
   420→  if (!consistency?.labels || !consistency?.events) {
   421→    return (
   422→      <div className="text-[11px] text-zinc-500 italic text-center py-4">
   423→        No consistency data available.
   424→      </div>
   425→    );
   426→  }
   427→
   428→  const labels = toArray(consistency.labels);
   429→  const eventData = consistency.events || {};
   430→
   431→  return (
   432→    <div className="space-y-2">
   433→      <div className="text-[10px] text-zinc-500 uppercase tracking-wide">Event Scores by Meet</div>
   434→
   435→      {events.filter(e => e !== 'AA').map(event => {
   436→        const scores = toArray(eventData[event]);
   437→        if (!scores.length) return null;
   438→
   439→        // Detect trend
   440→        const recent = scores.slice(-3);
   441→        let trend = 'stable';
   442→        if (recent.length >= 3) {
   443→          if (recent[2] > recent[0] && recent[2] > recent[1]) trend = 'up';
   444→          else if (recent[2] < recent[0] && recent[2] < recent[1]) trend = 'down';
   445→        }
   446→
   447→        const trendColor = trend === 'up' ? 'text-green-400' : trend === 'down' ? 'text-red-400' : 'text-zinc-400';
   448→        const trendIcon = trend === 'up' ? '\u2191' : trend === 'down' ? '\u2193' : '\u2194';
   449→        const avg = scores.reduce((s, v) => s + v, 0) / scores.length;
   450→
   451→        return (
   452→          <div key={event} className="bg-zinc-900/50 rounded p-2">
   453→            <div className="flex items-center justify-between mb-1">
   454→              <div className="text-[11px] text-white font-medium">{event}</div>
   455→              <div className={`text-[10px] ${trendColor}`}>
   456→                {trendIcon} {trend} (avg {formatScore(avg)})
   457→              </div>
   458→            </div>
   459→            <div className="flex gap-1 items-end h-6">
   460→              {scores.map((score, i) => {
   461→                const min = Math.min(...scores) - 0.5;
   462→                const max = Math.max(...scores) + 0.1;
   463→                const range = max - min || 1;
   464→                const height = Math.max(4, ((score - min) / range) * 24);
   465→                return (
   466→                  <div key={i} className="flex-1 flex flex-col items-center">
   467→                    <div
   468→                      className="w-full bg-blue-500/40 rounded-sm"
   469→                      style={{ height: `${height}px` }}
   470→                      title={`${labels[i] || `Meet ${i + 1}`}: ${formatScore(score)}`}
   471→                    />
   472→                  </div>
   473→                );
   474→              })}
   475→            </div>
   476→            <div className="flex gap-1 mt-0.5">
   477→              {scores.map((score, i) => (
   478→                <div key={i} className="flex-1 text-center text-[8px] text-zinc-600">
   479→                  {formatScore(score)}
   480→                </div>
   481→              ))}
   482→            </div>
   483→          </div>
   484→        );
   485→      })}
   486→    </div>
   487→  );
   488→}
   489→
   490→// --- Lineup Tab: Meet-by-meet lineup usage ---
   491→function LineupTab({ stats }) {
   492→  const lineup = toArray(stats?.lineup);
   493→
   494→  if (!lineup.length) {
   495→    return (
   496→      <div className="text-[11px] text-zinc-500 italic text-center py-4">
   497→        No lineup data available.
   498→      </div>
   499→    );
   500→  }
   501→
   502→  // Sort by lineup rate descending
   503→  const sorted = [...lineup].sort((a, b) => (b.rate || 0) - (a.rate || 0));
   504→
   505→  return (
   506→    <div>
   507→      <div className="text-[10px] text-zinc-500 uppercase tracking-wide mb-2">Lineup Frequency</div>
   508→      <div className="space-y-1">
   509→        {sorted.map((athlete, i) => {
   510→          const rate = athlete.rate || 0;
   511→          const meets = toArray(athlete.meets);
   512→          const totalMeets = meets.length;
   513→          const appeared = meets.filter(m => m === 1).length;
   514→
   515→          return (
   516→            <div key={athlete.rtnId || i} className="flex items-center gap-2 text-[11px]">
   517→              <span className="text-white w-32 truncate">
   518→                {athlete.fullName || `${athlete.firstName || ''} ${athlete.lastName || ''}`}
   519→              </span>
   520→              <div className="flex-1 h-2 bg-zinc-800 rounded overflow-hidden">
   521→                <div
   522→                  className="h-full bg-blue-500/60 rounded"
   523→                  style={{ width: `${Math.round(rate * 100)}%` }}
   524→                />
   525→              </div>
   526→              <span className="text-zinc-400 w-20 text-right">
   527→                {appeared}/{totalMeets} ({Math.round(rate * 100)}%)
   528→              </span>
   529→              {/* Individual meet dots */}
   530→              <div className="flex gap-0.5">
   531→                {meets.map((m, j) => (
   532→                  <div
   533→                    key={j}
   534→                    className={`w-1.5 h-1.5 rounded-full ${m === 1 ? 'bg-green-500' : 'bg-zinc-700'}`}
   535→                    title={`Meet ${j + 1}: ${m === 1 ? 'Competed' : 'Did not compete'}`}
   536→                  />
   537→                ))}
   538→              </div>
   539→            </div>
   540→          );
   541→        })}
   542→      </div>
   543→    </div>
   544→  );
   545→}
   546→
   547→// --- Utility functions ---
   548→
   549→/** Convert Firebase object-with-numeric-keys or array to proper array */
   550→function toArray(data) {
   551→  if (!data) return [];
   552→  if (Array.isArray(data)) return data;
   553→  if (typeof data === 'object') {
   554→    const keys = Object.keys(data);
   555→    if (keys.every(k => /^\d+$/.test(k))) {
   556→      return keys.sort((a, b) => Number(a) - Number(b)).map(k => data[k]);
   557→    }
   558→    return Object.values(data);
   559→  }
   560→  return [];
   561→}
   562→
   563→/** Format a score number for display */
   564→function formatScore(val) {
   565→  if (val === null || val === undefined) return '-';
   566→  const num = typeof val === 'string' ? parseFloat(val) : val;
   567→  if (isNaN(num)) return '-';
   568→  return num.toFixed(num >= 100 ? 2 : 3);
   569→}
   570→
   571→/** Merge athlete data from highs, averages, lineup, and MVP sources */
   572→function mergeAthleteData(highs, averages, lineup, mvp) {
   573→  const map = new Map();
   574→
   575→  const getKey = (a) => a.rtnId || a.fullName || `${a.firstName}-${a.lastName}`;
   576→
   577→  for (const a of averages) {
   578→    const key = getKey(a);
   579→    const existing = map.get(key) || {
   580→      rtnId: a.rtnId,
   581→      fullName: a.fullName || `${a.firstName || ''} ${a.lastName || ''}`.trim(),
   582→      averages: {},
   583→      highs: {},
   584→      lineupRate: null,
   585→      mvpTotal: null,
   586→    };
   587→    existing.averages = a.events || {};
   588→    map.set(key, existing);
   589→  }
   590→
   591→  for (const a of highs) {
   592→    const key = getKey(a);
   593→    const existing = map.get(key) || {
   594→      rtnId: a.rtnId,
   595→      fullName: a.fullName || `${a.firstName || ''} ${a.lastName || ''}`.trim(),
   596→      averages: {},
   597→      highs: {},
   598→      lineupRate: null,
   599→      mvpTotal: null,
   600→    };
   601→    existing.highs = a.events || {};
   602→    map.set(key, existing);
   603→  }
   604→
   605→  for (const a of lineup) {
   606→    const key = getKey(a);
   607→    const existing = map.get(key);
   608→    if (existing) {
   609→      existing.lineupRate = a.rate || null;
   610→    } else {
   611→      map.set(key, {
   612→        rtnId: a.rtnId,
   613→        fullName: a.fullName || `${a.firstName || ''} ${a.lastName || ''}`.trim(),
   614→        averages: {},
   615→        highs: {},
   616→        lineupRate: a.rate || null,
   617→        mvpTotal: null,
   618→      });
   619→    }
   620→  }
   621→
   622→  for (const a of mvp) {
   623→    const key = getKey(a);
   624→    const existing = map.get(key);
   625→    if (existing) {
   626→      existing.mvpTotal = a.total || null;
   627→    } else {
   628→      map.set(key, {
   629→        rtnId: a.rtnId,
   630→        fullName: a.fullName || `${a.firstName || ''} ${a.lastName || ''}`.trim(),
   631→        averages: {},
   632→        highs: {},
   633→        lineupRate: null,
   634→        mvpTotal: a.total || null,
   635→      });
   636→    }
   637→  }
   638→
   639→  return Array.from(map.values());
   640→}
