    98→  // Group competitions by date
    99→  const groupedCompetitions = useMemo(() => {
   100→    const now = new Date();
   101→    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
   102→    const tomorrow = new Date(today);
   103→    tomorrow.setDate(tomorrow.getDate() + 1);
   104→
   105→    const groups = {
   106→      today: [],
   107→      tomorrow: [],
   108→      upcoming: [],
   109→      past: []
   110→    };
   111→
   112→    Object.entries(competitions).forEach(([compId, data]) => {
   113→      const config = data?.config;
   114→      if (!config) return;
   115→
   116→      const searchLower = searchQuery.toLowerCase();
   117→      const matchesSearch = !searchQuery ||
   118→        config.eventName?.toLowerCase().includes(searchLower) ||
   119→        config.venue?.toLowerCase().includes(searchLower) ||
   120→        config.team1Name?.toLowerCase().includes(searchLower) ||
   121→        config.team2Name?.toLowerCase().includes(searchLower) ||
   122→        compId.toLowerCase().includes(searchLower);
   123→
   124→      if (!matchesSearch) return;
   125→
   126→      const meetDate = config.meetDate ? new Date(config.meetDate) : null;
   127→      const competition = { compId, config, meetDate };
   128→
   129→      if (!meetDate) {
   130→        groups.upcoming.push(competition);
   131→      } else if (meetDate >= today && meetDate < tomorrow) {
   132→        groups.today.push(competition);
   133→      } else if (meetDate >= tomorrow && meetDate < new Date(tomorrow.getTime() + 86400000)) {
   134→        groups.tomorrow.push(competition);
   135→      } else if (meetDate >= today) {
   136→        groups.upcoming.push(competition);
   137→      } else {
   138→        groups.past.push(competition);
   139→      }
   140→    });
   141→
   142→    const sortByDate = (a, b) => {
   143→      if (!a.meetDate && !b.meetDate) return 0;
   144→      if (!a.meetDate) return 1;
   145→      if (!b.meetDate) return -1;
   146→      return a.meetDate - b.meetDate;
   147→    };
   148→
   149→    groups.today.sort(sortByDate);
   150→    groups.tomorrow.sort(sortByDate);
   151→    groups.upcoming.sort(sortByDate);
   152→    groups.past.sort((a, b) => sortByDate(b, a));
   153→
   154→    return groups;
   155→  }, [competitions, searchQuery]);
