   850→// Competition Card Component
   851→function CompetitionCard({
   852→  competition,
   853→  vmStatuses,
   854→  getGenderBadge,
   855→  getTeams,
   856→  formatDisplayDate,
   857→  getVMStatusBadge,
   858→  hasVMAssigned,
