   877→  const isReleasing = releasingVm === compId;
   878→  const canAssignVM = availableVMs.length > 0 && !hasVM && !isCoordinatorOffline;
   879→  const canReleaseVM = hasVM && !isCoordinatorOffline;
   880→
   881→  return (
   882→    <div className="bg-zinc-900 border-2 border-zinc-800 rounded-xl p-5 hover:border-zinc-700 transition-colors">
   883→      <div className="flex items-start justify-between mb-3">
