   889→          {vmBadge && (
   890→            <span
   891→              className={`px-2 py-0.5 rounded text-xs font-bold text-white ${vmBadge.color} cursor-help`}
   892→              title={vmBadge.vm.publicIp ? `IP: ${vmBadge.vm.publicIp}` : 'No IP assigned'}
