   962→            disabled={!canAssignVM || isAssigning}
   963→            className={`px-3 py-1.5 text-sm font-medium rounded-lg transition-colors ${
   964→              canAssignVM && !isAssigning
   965→                ? 'bg-green-600 text-white hover:bg-green-500'
   966→                : 'bg-zinc-800 text-zinc-500 cursor-not-allowed'
   967→            }`}
   968→            title={
   969→              isCoordinatorOffline
   970→                ? 'Start system first'
