     1→/**
     2→ * useLeagueRankings - React hook for accessing RTN league rankings
     3→ *
     4→ * Subscribes to rtnCache/rankings/{gender}-{year}-{latestWeek}/ via Firebase.
     5→ * Returns team rankings and per-event individual rankings.
     6→ *
     7→ * The refresh() function emits a fetchLeagueRankings socket event to trigger
     8→ * server-side fetching from RTN. Uses a temporary socket connection so the hook
     9→ * works both inside and outside ShowContext.
    10→ *
    11→ * NOTE: Rankings use week-based caching. The hook determines the latest available
    12→ * week from Firebase cache keys, then subscribes to that week's data.
    13→ */
    14→
    15→import { useState, useEffect, useCallback, useRef } from 'react';
    16→import { db, ref, onValue, get } from '../lib/firebase';
    17→import { io } from 'socket.io-client';
    18→import { SERVER_URL } from '../lib/serverUrl';
    19→
    20→const RANKINGS_CACHE_TTL = 24 * 60 * 60 * 1000; // 24 hours
    21→
    22→/**
    23→ * Hook for consuming league rankings data from Firebase.
    24→ *
    25→ * @param {string} gender - "mens" or "womens"
    26→ * @param {object} [options] - Optional config
    27→ * @param {number} [options.year] - Season year (defaults to current year)
    28→ * @param {number} [options.week] - Specific week (defaults to latest available)
    29→ * @returns {{ teamRankings, individualRankings, week, loading, error, refresh, isStale }}
    30→ */
    31→export default function useLeagueRankings(gender, options = {}) {
    32→  const { year: optYear, week: optWeek } = options;
    33→  const resolvedYear = optYear || new Date().getFullYear();
    34→
    35→  const [teamRankings, setTeamRankings] = useState([]);
    36→  const [individualRankings, setIndividualRankings] = useState({});
    37→  const [week, setWeek] = useState(optWeek || null);
    38→  const [loading, setLoading] = useState(true);
    39→  const [error, setError] = useState(null);
    40→  const [fetchedAt, setFetchedAt] = useState(null);
    41→  const [refreshing, setRefreshing] = useState(false);
    42→  const unsubRef = useRef(null);
    43→
    44→  // Determine latest week from available cache keys when no week specified
    45→  useEffect(() => {
    46→    if (!gender || optWeek) {
    47→      if (optWeek) setWeek(optWeek);
    48→      return;
    49→    }
    50→
    51→    const rankingsRef = ref(db, 'rtnCache/rankings');
    52→    get(rankingsRef).then((snapshot) => {
    53→      if (!snapshot.exists()) {
    54→        setWeek(null);
    55→        setLoading(false);
    56→        return;
    57→      }
    58→
    59→      const data = snapshot.val();
    60→      const prefix = `${gender}-${resolvedYear}-`;
    61→      const weeks = Object.keys(data)
    62→        .filter(k => k.startsWith(prefix))
    63→        .map(k => parseInt(k.replace(prefix, ''), 10))
    64→        .filter(w => !isNaN(w))
    65→        .sort((a, b) => b - a); // descending
    66→
    67→      if (weeks.length > 0) {
    68→        setWeek(weeks[0]);
    69→      } else {
    70→        setWeek(null);
    71→        setLoading(false);
    72→      }
    73→    }).catch((err) => {
    74→      console.error('[useLeagueRankings] Failed to determine latest week:', err);
    75→      setWeek(null);
    76→      setLoading(false);
    77→    });
    78→  }, [gender, resolvedYear, optWeek]);
    79→
    80→  // Subscribe to rankings data for the resolved week
    81→  useEffect(() => {
    82→    // Clean up previous subscription
    83→    if (unsubRef.current) {
    84→      unsubRef.current();
    85→      unsubRef.current = null;
    86→    }
    87→
    88→    if (!gender || week === null) {
    89→      setTeamRankings([]);
    90→      setIndividualRankings({});
    91→      setLoading(false);
    92→      return;
    93→    }
    94→
    95→    const cacheKey = `${gender}-${resolvedYear}-${week}`;
    96→    const rankingsPath = ref(db, `rtnCache/rankings/${cacheKey}`);
    97→
    98→    setLoading(true);
    99→
   100→    const unsub = onValue(rankingsPath, (snapshot) => {
   101→      if (!snapshot.exists()) {
   102→        setTeamRankings([]);
   103→        setIndividualRankings({});
   104→        setFetchedAt(null);
   105→        setLoading(false);
   106→        return;
   107→      }
   108→
   109→      const data = snapshot.val();
   110→
   111→      // Normalize team rankings (Firebase may store as object with numeric keys)
   112→      const teamArr = toArray(data.team);
   113→      setTeamRankings(teamArr);
   114→
   115→      // Normalize individual rankings per event
   116→      const indiv = {};
   117→      if (data.individual) {
   118→        for (const [eventCode, athletes] of Object.entries(data.individual)) {
   119→          indiv[eventCode] = toArray(athletes);
   120→        }
   121→      }
   122→      setIndividualRankings(indiv);
   123→
   124→      setFetchedAt(data.fetchedAt || null);
   125→      setError(null);
   126→      setLoading(false);
   127→    }, (err) => {
   128→      console.error('[useLeagueRankings] Firebase listener error:', err);
   129→      setError(err.message);
   130→      setLoading(false);
   131→    });
   132→
   133→    unsubRef.current = unsub;
   134→
