   966→      HB: 'hbar',
   967→    };
   968→
   969→    const key = eventRankingKey[eventCode];
   970→    if (!key) return null;
   971→
   972→    const r1 = this._teamData.team1.rankings[key];
   973→    const r2 = this._teamData.team2.rankings[key];
   974→
   975→    if (!r1 || !r2) return null;
   976→
   977→    const team1Name = this._getTeamDisplayName('team1');
   978→    const team2Name = this._getTeamDisplayName('team2');
   979→    const eventName = EVENT_FULL_NAMES[eventCode] || eventCode;
   980→
   981→    if (r1 < r2) {
   982→      return `On ${eventName}: ${team1Name} ranked #${r1}, ${team2Name} #${r2}`;
   983→    } else if (r2 < r1) {
   984→      return `On ${eventName}: ${team2Name} ranked #${r2}, ${team1Name} #${r1}`;
   985→    }
   986→
   987→    return null;
   988→  }
