   997→    }
   998→
   999→    // Fall back to extracting from schedule opponent
  1000→    const team = this._teamData?.[teamKey];
  1001→    if (team?.schedule?.[0]?.opponent) {
  1002→      // Try to extract from context
  1003→      return teamKey === 'team1' ? 'Team 1' : 'Team 2';
  1004→    }
  1005→
  1006→    return teamKey === 'team1' ? 'Home' : 'Away';
  1007→  }
