  1344→  /**
  1345→   * Check if a score is a career high for an athlete
  1346→   *
  1347→   * Compares against:
  1348→   * 1. Stored career bests in Firebase (athleteStats/{athleteId}/careerBests)
  1349→   * 2. Season bests from current show's score tracking
  1350→   * 3. Previous scores in current meet
  1351→   *
  1352→   * @param {string} athleteName - Athlete name
  1353→   * @param {string} event - Event code (FX, VT, etc.)
  1354→   * @param {number} score - Score to check
  1355→   * @returns {Promise<Object>} Career high check result
  1356→   */
  1357→  async checkCareerHigh(athleteName, event, score) {
  1358→    if (!athleteName || !event || typeof score !== 'number') {
  1359→      return { isCareerHigh: false, reason: 'invalid_input' };
  1360→    }
  1361→
  1362→    try {
  1363→      // Get athlete's stored career bests
  1364→      const careerBests = await this._getAthleteCareerBests(athleteName);
  1365→      const previousHigh = careerBests?.[event] || null;
  1366→
  1367→      // Check if this is a career high
  1368→      const isCareerHigh = previousHigh === null || score > previousHigh;
  1369→      const isSeasonHigh = await this._checkSeasonHigh(athleteName, event, score);
  1370→      const isMeetHigh = this._checkMeetHigh(athleteName, event, score);
  1371→
  1372→      // Determine the type of achievement
  1373→      let achievementType = null;
  1374→      if (isCareerHigh && previousHigh !== null) {
  1375→        achievementType = 'career_high';
  1376→      } else if (isSeasonHigh) {
  1377→        achievementType = 'season_high';
  1378→      } else if (isMeetHigh) {
  1379→        achievementType = 'meet_high';
  1380→      }
  1381→
  1382→      const result = {
  1383→        isCareerHigh: isCareerHigh && previousHigh !== null,
  1384→        isSeasonHigh,
  1385→        isMeetHigh,
  1386→        achievementType,
  1387→        previousHigh,
  1388→        improvement: previousHigh ? (score - previousHigh).toFixed(3) : null,
  1389→        score,
  1390→        event,
  1391→        athleteName,
  1392→      };
  1393→
  1394→      // If this is a notable achievement, store it and generate alert
  1395→      if (achievementType) {
  1396→        await this._recordAchievement(result);
  1397→      }
  1398→
  1399→      return result;
  1400→    } catch (error) {
  1401→      console.error(`[AIContextService] Error checking career high:`, error);
  1402→      return { isCareerHigh: false, error: error.message };
  1403→    }
  1404→  }
  1405→
  1406→  /**
  1407→   * Detect if a score breaks any records
  1408→   *
  1409→   * Checks against:
  1410→   * 1. School records (stored in Firebase)
  1411→   * 2. Meet records (if available)
  1412→   * 3. Venue records (if available)
  1413→   *
  1414→   * @param {string} athleteName - Athlete name
  1415→   * @param {string} event - Event code
  1416→   * @param {number} score - Score to check
  1417→   * @param {string} teamTricode - Team tricode for school record lookup
  1418→   * @returns {Promise<Object>} Record check result
  1419→   */
  1420→  async checkRecords(athleteName, event, score, teamTricode = null) {
  1421→    if (!athleteName || !event || typeof score !== 'number') {
  1422→      return { breaksRecord: false, reason: 'invalid_input' };
  1423→    }
  1424→
  1425→    const brokenRecords = [];
  1426→
  1427→    try {
  1428→      // Check school record
  1429→      const schoolRecord = await this._getSchoolRecord(teamTricode, event);
  1430→      if (schoolRecord && score > schoolRecord.score) {
  1431→        brokenRecords.push({
  1432→          type: 'school',
  1433→          previousScore: schoolRecord.score,
  1434→          previousHolder: schoolRecord.holder,
  1435→          previousDate: schoolRecord.date,
  1436→          improvement: (score - schoolRecord.score).toFixed(3),
  1437→        });
  1438→      }
  1439→
  1440→      // Check meet record (from current competition config)
  1441→      const meetRecord = await this._getMeetRecord(event);
  1442→      if (meetRecord && score > meetRecord.score) {
  1443→        brokenRecords.push({
  1444→          type: 'meet',
  1445→          previousScore: meetRecord.score,
  1446→          previousHolder: meetRecord.holder,
  1447→          previousYear: meetRecord.year,
  1448→          improvement: (score - meetRecord.score).toFixed(3),
  1449→        });
  1450→      }
  1451→
  1452→      // Check if this ties a record (within 0.001)
  1453→      const tiedRecords = [];
  1454→      if (schoolRecord && Math.abs(score - schoolRecord.score) < 0.001) {
  1455→        tiedRecords.push({ type: 'school', score: schoolRecord.score });
  1456→      }
  1457→      if (meetRecord && Math.abs(score - meetRecord.score) < 0.001) {
  1458→        tiedRecords.push({ type: 'meet', score: meetRecord.score });
  1459→      }
  1460→
  1461→      const result = {
  1462→        breaksRecord: brokenRecords.length > 0,
  1463→        tiesRecord: tiedRecords.length > 0,
  1464→        records: brokenRecords,
  1465→        tiedRecords,
  1466→        athleteName,
  1467→        event,
  1468→        score,
  1469→      };
  1470→
  1471→      // If a record is broken, record it
  1472→      if (brokenRecords.length > 0) {
  1473→        await this._recordBrokenRecord(result);
  1474→      }
  1475→
  1476→      return result;
  1477→    } catch (error) {
  1478→      console.error(`[AIContextService] Error checking records:`, error);
  1479→      return { breaksRecord: false, error: error.message };
  1480→    }
  1481→  }
  1482→
  1483→  /**
  1484→   * Scan recent scores for career highs and records
  1485→   * Called during context updates to detect achievements in live scores
  1486→   *
  1487→   * @returns {Promise<Array>} List of detected achievements
  1488→   */
  1489→  async scanForAchievements() {
  1490→    const achievements = [];
  1491→
  1492→    if (!this._virtiusData?.available || !this._virtiusData.recentScores) {
  1493→      return achievements;
  1494→    }
  1495→
  1496→    // Get team tricodes for record lookups
  1497→    const teamTricodes = this._virtiusData.teams?.map(t => t.tricode) || [];
  1498→
  1499→    for (const scoreData of this._virtiusData.recentScores) {
  1500→      // Skip if already processed
  1501→      const scoreKey = `${scoreData.athlete}-${scoreData.event}-${scoreData.score}`;
  1502→      if (this._processedScores?.has(scoreKey)) {
  1503→        continue;
  1504→      }
  1505→
  1506→      // Mark as processed
  1507→      if (!this._processedScores) {
  1508→        this._processedScores = new Set();
  1509→      }
  1510→      this._processedScores.add(scoreKey);
  1511→
  1512→      // Check for career high
  1513→      const careerResult = await this.checkCareerHigh(
  1514→        scoreData.athlete,
  1515→        scoreData.event,
  1516→        scoreData.score
  1517→      );
  1518→
  1519→      if (careerResult.achievementType) {
  1520→        achievements.push({
  1521→          type: careerResult.achievementType,
  1522→          ...careerResult,
  1523→          timestamp: new Date().toISOString(),
  1524→        });
  1525→      }
  1526→
  1527→      // Check for records
  1528→      const teamTricode = scoreData.team || teamTricodes[0];
  1529→      const recordResult = await this.checkRecords(
  1530→        scoreData.athlete,
  1531→        scoreData.event,
  1532→        scoreData.score,
  1533→        teamTricode
  1534→      );
  1535→
  1536→      if (recordResult.breaksRecord) {
  1537→        achievements.push({
  1538→          type: 'record_broken',
  1539→          ...recordResult,
  1540→          timestamp: new Date().toISOString(),
  1541→        });
  1542→      } else if (recordResult.tiesRecord) {
  1543→        achievements.push({
  1544→          type: 'record_tied',
  1545→          ...recordResult,
  1546→          timestamp: new Date().toISOString(),
  1547→        });
  1548→      }
  1549→    }
  1550→
  1551→    // Store achievements in current context
  1552→    if (achievements.length > 0) {
  1553→      this._recentAchievements = [
  1554→        ...achievements,
  1555→        ...(this._recentAchievements || []).slice(0, 20), // Keep last 20
  1556→      ];
  1557→
  1558→      // Broadcast achievements
  1559→      this._broadcastAchievements(achievements);
  1560→    }
  1561→
  1562→    return achievements;
  1563→  }
  1564→
  1565→  /**
  1566→   * Get athlete's career bests from Firebase or cache
  1567→   *
  1568→   * @param {string} athleteName - Athlete name
  1569→   * @returns {Promise<Object|null>} Career bests by event
  1570→   */
  1571→  async _getAthleteCareerBests(athleteName) {
  1572→    if (!athleteName) return null;
  1573→
  1574→    // Check cache first
  1575→    if (!this._careerBestsCache) {
  1576→      this._careerBestsCache = new Map();
  1577→    }
  1578→
  1579→    const cacheKey = athleteName.toLowerCase().trim();
  1580→    if (this._careerBestsCache.has(cacheKey)) {
  1581→      return this._careerBestsCache.get(cacheKey);
  1582→    }
  1583→
  1584→    // Try to load from Firebase
  1585→    const db = getDb();
  1586→    if (db) {
  1587→      try {
  1588→        const athleteKey = this._normalizeNameForKey(athleteName);
  1589→        const snapshot = await db.ref(`athleteStats/${athleteKey}/careerBests`).once('value');
  1590→        const careerBests = snapshot.val();
  1591→
  1592→        if (careerBests) {
  1593→          this._careerBestsCache.set(cacheKey, careerBests);
  1594→          return careerBests;
  1595→        }
  1596→      } catch (error) {
  1597→        console.warn(`[AIContextService] Error loading career bests:`, error);
  1598→      }
  1599→    }
  1600→
  1601→    // Try to get from team data roster (some rosters include season bests)
  1602→    const rosterBests = this._getAthleteFromRoster(athleteName);
  1603→    if (rosterBests?.seasonBests) {
  1604→      this._careerBestsCache.set(cacheKey, rosterBests.seasonBests);
  1605→      return rosterBests.seasonBests;
  1606→    }
  1607→
  1608→    return null;
  1609→  }
  1610→
  1611→  /**
  1612→   * Check if score is a season high
  1613→   *
  1614→   * @param {string} athleteName - Athlete name
  1615→   * @param {string} event - Event code
  1616→   * @param {number} score - Score to check
  1617→   * @returns {Promise<boolean>} True if season high
  1618→   */
  1619→  async _checkSeasonHigh(athleteName, event, score) {
  1620→    // Check session-tracked scores
  1621→    if (!this._sessionScores) {
  1622→      this._sessionScores = new Map();
  1623→    }
  1624→
  1625→    const key = `${athleteName.toLowerCase()}-${event}`;
  1626→    const previousBest = this._sessionScores.get(key) || 0;
  1627→
  1628→    if (score > previousBest) {
  1629→      this._sessionScores.set(key, score);
  1630→      return previousBest > 0; // Only true if there was a previous score
  1631→    }
  1632→
  1633→    return false;
  1634→  }
  1635→
  1636→  /**
  1637→   * Check if score is the athlete's meet high
  1638→   *
  1639→   * @param {string} athleteName - Athlete name
  1640→   * @param {string} event - Event code
  1641→   * @param {number} score - Score to check
  1642→   * @returns {boolean} True if meet high
  1643→   */
  1644→  _checkMeetHigh(athleteName, event, score) {
  1645→    if (!this._virtiusData?.eventResults) return false;
  1646→
  1647→    const eventData = this._virtiusData.eventResults[event];
  1648→    if (!eventData?.gymnasts) return false;
  1649→
  1650→    // Find all scores by this athlete on this event
  1651→    const athleteScores = eventData.gymnasts.filter(
  1652→      g => g.name?.toLowerCase().includes(athleteName.toLowerCase()) ||
  1653→           athleteName.toLowerCase().includes(g.lastName?.toLowerCase() || '')
  1654→    );
  1655→
  1656→    // If only one score, it's their meet high by default
  1657→    if (athleteScores.length <= 1) return false;
  1658→
  1659→    // Check if current score is highest
  1660→    const maxPreviousScore = Math.max(...athleteScores.map(s => s.score || 0));
  1661→    return score >= maxPreviousScore;
  1662→  }
  1663→
  1664→  /**
  1665→   * Get school record for an event
  1666→   *
  1667→   * @param {string} teamTricode - Team tricode
  1668→   * @param {string} event - Event code
  1669→   * @returns {Promise<Object|null>} School record data
  1670→   */
  1671→  async _getSchoolRecord(teamTricode, event) {
  1672→    if (!teamTricode) return null;
  1673→
  1674→    const db = getDb();
  1675→    if (!db) return null;
  1676→
  1677→    try {
  1678→      const snapshot = await db.ref(`schoolRecords/${teamTricode}/${event}`).once('value');
  1679→      return snapshot.val();
  1680→    } catch (error) {
  1681→      console.warn(`[AIContextService] Error loading school record:`, error);
  1682→      return null;
  1683→    }
  1684→  }
  1685→
  1686→  /**
  1687→   * Get meet record for an event
  1688→   *
  1689→   * @param {string} event - Event code
  1690→   * @returns {Promise<Object|null>} Meet record data
  1691→   */
  1692→  async _getMeetRecord(event) {
  1693→    if (!this._competitionConfig?.meetRecords) return null;
  1694→    return this._competitionConfig.meetRecords[event] || null;
  1695→  }
  1696→
  1697→  /**
  1698→   * Record an achievement to Firebase
  1699→   *
  1700→   * @param {Object} achievement - Achievement data
  1701→   */
  1702→  async _recordAchievement(achievement) {
  1703→    const db = getDb();
  1704→    if (!db || !this.compId) return;
  1705→
  1706→    try {
  1707→      const achievementData = {
  1708→        ...achievement,
  1709→        compId: this.compId,
  1710→        recordedAt: new Date().toISOString(),
  1711→      };
  1712→
  1713→      // Store in competition's achievements
  1714→      await db.ref(`competitions/${this.compId}/production/achievements`).push(achievementData);
  1715→
  1716→      // Update athlete's career best if applicable
  1717→      if (achievement.isCareerHigh) {
  1718→        const athleteKey = this._normalizeNameForKey(achievement.athleteName);
  1719→        await db.ref(`athleteStats/${athleteKey}/careerBests/${achievement.event}`).set(achievement.score);
  1720→      }
  1721→
  1722→      console.log(`[AIContextService] Recorded achievement: ${achievement.achievementType} for ${achievement.athleteName}`);
  1723→    } catch (error) {
  1724→      console.warn(`[AIContextService] Error recording achievement:`, error);
  1725→    }
  1726→  }
  1727→
  1728→  /**
  1729→   * Record a broken record to Firebase
  1730→   *
  1731→   * @param {Object} recordData - Record data
  1732→   */
  1733→  async _recordBrokenRecord(recordData) {
  1734→    const db = getDb();
  1735→    if (!db || !this.compId) return;
  1736→
  1737→    try {
  1738→      // Store in competition's broken records
  1739→      await db.ref(`competitions/${this.compId}/production/brokenRecords`).push({
  1740→        ...recordData,
  1741→        compId: this.compId,
  1742→        recordedAt: new Date().toISOString(),
  1743→      });
  1744→
  1745→      console.log(`[AIContextService] Recorded broken record for ${recordData.athleteName}`);
  1746→    } catch (error) {
  1747→      console.warn(`[AIContextService] Error recording broken record:`, error);
  1748→    }
  1749→  }
  1750→
  1751→  /**
  1752→   * Broadcast achievements to connected clients
  1753→   *
  1754→   * @param {Array} achievements - Achievements to broadcast
  1755→   */
  1756→  _broadcastAchievements(achievements) {
  1757→    if (!this.io || !this.compId || !achievements.length) return;
  1758→
  1759→    this.io.to(`competition:${this.compId}`).emit('aiAchievementsDetected', {
  1760→      compId: this.compId,
  1761→      achievements,
  1762→      timestamp: new Date().toISOString(),
  1763→    });
  1764→  }
  1765→
  1766→  /**
  1767→   * Get athlete data from loaded roster
  1768→   *
  1769→   * @param {string} athleteName - Athlete name to find
  1770→   * @returns {Object|null} Athlete data from roster
  1771→   */
  1772→  _getAthleteFromRoster(athleteName) {
  1773→    if (!this._teamData) return null;
  1774→
  1775→    const normalized = athleteName.toLowerCase().trim();
  1776→
  1777→    for (const teamKey of ['team1', 'team2']) {
  1778→      const roster = this._teamData[teamKey]?.roster;
  1779→      if (!roster) continue;
  1780→
  1781→      const athlete = roster.find(a =>
  1782→        a.fullName?.toLowerCase() === normalized ||
  1783→        `${a.firstName} ${a.lastName}`.toLowerCase() === normalized ||
  1784→        a.lastName?.toLowerCase() === normalized.split(' ').pop()
  1785→      );
  1786→
  1787→      if (athlete) {
  1788→        return { ...athlete, teamKey };
  1789→      }
  1790→    }
  1791→
  1792→    return null;
  1793→  }
  1794→
  1795→  /**
  1796→   * Normalize athlete name to Firebase-safe key
  1797→   *
  1798→   * @param {string} name - Athlete name
  1799→   * @returns {string} Normalized key
  1800→   */
  1801→  _normalizeNameForKey(name) {
  1802→    return name
  1803→      .toLowerCase()
  1804→      .trim()
  1805→      .replace(/[.#$[\]]/g, '')
  1806→      .replace(/\s+/g, '-');
  1807→  }
  1808→
  1809→  /**
  1810→   * Get recent achievements
  1811→   *
  1812→   * @returns {Array} Recent achievements
  1813→   */
  1814→  getRecentAchievements() {
  1815→    return this._recentAchievements || [];
  1816→  }
  1817→
  1818→  // ==========================================================================
  1819→  // Broadcasting
  1820→  // ==========================================================================
  1821→
  1822→  /**
  1823→   * Broadcast context update to connected clients
  1824→   *
  1825→   * @param {Object} context - Context to broadcast
  1826→   */
  1827→  _broadcastContext(context) {
  1828→    if (!this.io || !this.compId) {
  1829→      return;
  1830→    }
  1831→
  1832→    // Broadcast to competition room
  1833→    this.io.to(`competition:${this.compId}`).emit('aiContextUpdated', {
  1834→      compId: this.compId,
  1835→      context,
  1836→      timestamp: new Date().toISOString(),
  1837→    });
  1838→  }
  1839→
  1840→  // ==========================================================================
  1841→  // Data Loading
  1842→  // ==========================================================================
  1843→
  1844→  /**
  1845→   * Load competition data from Firebase
  1846→   */
  1847→  async _loadCompetitionData() {
  1848→    const db = getDb();
  1849→    if (!db || !this.compId) {
  1850→      console.warn('[AIContextService] Cannot load data - missing db or compId');
  1851→      return;
  1852→    }
  1853→
  1854→    try {
  1855→      // Load competition config
  1856→      const configSnapshot = await db.ref(`competitions/${this.compId}/config`).once('value');
  1857→      this._competitionConfig = configSnapshot.val();
  1858→
  1859→      // Load team data
  1860→      const teamDataSnapshot = await db.ref(`competitions/${this.compId}/teamData`).once('value');
  1861→      this._teamData = teamDataSnapshot.val();
  1862→
  1863→      // Extract Virtius session ID if available
  1864→      if (this._competitionConfig?.virtiusSessionId) {
  1865→        this._virtiusSessionId = this._competitionConfig.virtiusSessionId;
  1866→        console.log(`[AIContextService] Found Virtius session ID: ${this._virtiusSessionId}`);
  1867→      }
  1868→
  1869→      console.log(`[AIContextService] Loaded competition data for ${this.compId}`);
  1870→    } catch (error) {
  1871→      console.error(`[AIContextService] Error loading competition data:`, error);
  1872→    }
  1873→  }
  1874→
  1875→  // ==========================================================================
  1876→  // Helpers
  1877→  // ==========================================================================
  1878→
  1879→  /**
  1880→   * Get current show state from engine
  1881→   *
  1882→   * @returns {Object|null} Current show state
  1883→   */
  1884→  _getShowState() {
  1885→    if (!this.engine) {
  1886→      return null;
  1887→    }
  1888→
  1889→    try {
  1890→      return this.engine.getState();
  1891→    } catch (error) {
  1892→      console.error(`[AIContextService] Error getting show state:`, error);
  1893→      return null;
  1894→    }
  1895→  }
  1896→
  1897→  /**
  1898→   * Get current context
  1899→   *
  1900→   * @returns {Object|null} Current context
  1901→   */
  1902→  getCurrentContext() {
  1903→    return this._currentContext;
  1904→  }
  1905→
  1906→  /**
  1907→   * Force a context refresh
  1908→   */
  1909→  async refreshContext() {
  1910→    this._lastSegmentId = null; // Force regeneration
  1911→    await this._updateContext();
  1912→  }
  1913→
  1914→  /**
  1915→   * Get service state for debugging
  1916→   */
  1917→  getState() {
  1918→    return {
  1919→      compId: this.compId,
  1920→      isRunning: this._isRunning,
  1921→      hasEngine: !!this.engine,
  1922→      hasCurrentContext: !!this._currentContext,
  1923→      lastSegmentId: this._lastSegmentId,
  1924→      config: this.config,
  1925→      virtius: {
  1926→        sessionId: this._virtiusSessionId,
  1927→        hasData: !!this._virtiusData,
  1928→        lastFetch: this._virtiusLastFetch
  1929→          ? new Date(this._virtiusLastFetch).toISOString()
  1930→          : null,
  1931→        available: this._virtiusData?.available || false,
  1932→      },
  1933→      achievements: {
  1934→        recentCount: this._recentAchievements?.length || 0,
  1935→        processedScoresCount: this._processedScores?.size || 0,
  1936→        careerBestsCacheSize: this._careerBestsCache?.size || 0,
  1937→      },
  1938→    };
  1939→  }
  1940→}
  1941→
  1942→// ============================================================================
  1943→// Service Factory
  1944→// ============================================================================
  1945→
  1946→// Map of active AIContextService instances by compId
  1947→const contextServices = new Map();
  1948→
  1949→/**
  1950→ * Get or create an AIContextService for a competition
  1951→ *
  1952→ * @param {string} compId - Competition ID
  1953→ * @param {Object} options - Service options
  1954→ * @returns {AIContextService} Service instance
  1955→ */
  1956→function getOrCreateContextService(compId, options = {}) {
  1957→  if (!compId) {
  1958→    throw new Error('compId is required');
  1959→  }
  1960→
  1961→  if (!contextServices.has(compId)) {
  1962→    const service = new AIContextService({ ...options, compId });
  1963→    contextServices.set(compId, service);
  1964→    console.log(`[AIContextService] Created service for ${compId}`);
  1965→  }
