    for (const teamKey of ['team1', 'team2']) {
      const team = this._teamData[teamKey];
      if (team?.roster) {
        const teamSeniors = team.roster.filter((a) => a.year === 4);
        seniors.push(...teamSeniors.map((s) => ({ ...s, team: teamKey })));
      }
    }

    return seniors;
  }

